INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Arlington Boys & Girls Club Summer Programs', 'Arlington Boys & Girls Club', 'https://www.abgclub.org/summer', 'https://web1.myvscloud.com/wbwsc/maarlingtonbgcwt.wsc/splash.html', 'abgclub@abgclub.org', '781-648-1617', '60 Pond Lane', 'Arlington', 'MA', '02474', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['sports','arts','STEM','sailing','swimming']::text[], ARRAY['outdoor games','water play','LEGO','board games','STEAM','swimming','walking field trips','themed weeks','kayaking','paddle boarding','sailing','field trips','hiking','basketball','math','science','art','cooking']::text[], NULL, NULL, NULL, NULL, 8, 'Weekly summer day programs at the Boys & Girls Club (ABGC) for preschool through 8th grade. Options include Kids Zone, Creative Explorers for preschoolers, boating on Spy Pond, the field-trip-based Extreme Summer and a basketball clinic.', NULL, NULL, 152, 420, NULL, 'week', TRUE, NULL, NULL, TRUE, 'Club membership ($35/year, non-refundable) is required. Cancel programs by May 1 for a refund or household credit, minus a $25 processing fee; no refunds or credits after May 1.', NULL, 'Kids Zone includes free swim with a brief daily swim safety lesson. Extreme Summer ends each day with a free swim in the pool. Boating (kayaking, paddle boarding, sailing on Spy Pond) requires passing a swim test (75 yards front crawl) every year before registering. Separate week-long summer swim lessons are also offered.', NULL, NULL, 2026, 'f90a1754-f79d-5259-b501-0d1890e529af', 'abgc-summer-programs', ST_GeogFromText('SRID=4326;POINT(-71.1565 42.4154)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://irp.cdn-website.com/bc06a3cd/files/uploaded/Updated+Spring-Summer+Webfile+2026.pdf','https://www.abgclub.org/contact','https://www.abgclub.org/summer']::text[], '2026-11-13', '2026-11-13', TRUE),
('Academic Adventures at FaySummer', 'Fay School (FaySummer)', 'https://www.faysummer.org/academic-adventures', 'https://www.faysummer.org/rates-and-registration', 'summer@fayschool.org', '508-490-8371', '48 Main Street', 'Southborough', 'MA', '01772', 'Boston, MA', 'sleepaway', ARRAY['academic','STEM','arts']::text[], NULL, ARRAY['Global Science (science and math)','Vox Inventum (writing)','Creators Class (design and making with 3D printers, laser cutters and CNC routers)','Swimming','Ropes/adventure course','Sports and games','Arts and crafts','Drama','Music','Weekend trips (Boston, beach, local attractions)']::text[], NULL, 10, 15, NULL, NULL, 'A boarding enrichment program for students ages 10-15 on Fay School''s campus in Southborough, MA. Students take three hands-on classes (Global Science, the Vox Inventum writing class and the Creators Class in design and making), join traditional camp activities each afternoon, and take off-campus trips on weekends.', NULL, NULL, 4950, 9400, NULL, 'session', NULL, FALSE, TRUE, TRUE, 'A non-refundable deposit is due when you register. If you cancel before June 1 you get a full refund minus the deposit. There are no refunds after June 1. If FaySummer cancels the program, you get a full refund. (The page gives the 2026 deadline of June 1, 2026.)', NULL, 'There are two pools on campus. Swimming or field games are scheduled daily from 3:30 to 4:15 PM.', NULL, NULL, 2027, '340dca64-a7ec-5e1b-a986-b56e61947649', 'academic-adventures-at-faysummer-southborough', ST_GeogFromText('SRID=4326;POINT(-71.5245 42.3057)'), FALSE, TRUE, FALSE, TRUE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.faysummer.org/academic-adventures','https://www.faysummer.org/rates-and-registration']::text[], '2026-11-13', '2026-11-13', TRUE),
('Andover Summer Session', 'Phillips Academy', 'https://www.andover.edu/summer/on-campus-programs', 'https://www.andover.edu/summer/on-campus-programs/summer-admission', 'summer@andover.edu', '(978) 749-4000', '180 Main Street', 'Andover', 'MA', '01810', 'Boston, MA', 'sleepaway', ARRAY['academic']::text[], NULL, ARRAY['Academic courses','Afternoon activities','Weekend activities','Off-site field trips','College visits in New England','College counseling','SAT & SSAT prep (Princeton Review)','Music lessons']::text[], NULL, 12, 17, 7, 12, 'A five-week academic summer program at Phillips Academy in Andover, Massachusetts, for students entering grades 7–12. Students can board or attend as day students. The Lower School Institute (grades 7–8) studies several subjects under one theme, and Upper School students (grades 9–12) choose from more than 70 courses.', NULL, NULL, 3250, 11700, NULL, 'session', NULL, FALSE, NULL, TRUE, 'A non-refundable deposit of 20% of tuition is due within two weeks of acceptance; the balance is due by May 1, 2027. 50% of paid tuition is refunded for withdrawal on or before June 15, 2027, 25% between June 16 and June 30, 2027, and none after that or on dismissal.', NULL, NULL, NULL, NULL, 2027, 'a6a9d024-f0bf-53fe-8754-234b573999da', 'andover-summer-session-andover', ST_GeogFromText('SRID=4326;POINT(-71.137 42.6584)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.andover.edu/summer/on-campus-programs','https://www.andover.edu/summer/on-campus-programs/tuition']::text[], '2026-11-13', '2026-11-13', TRUE),
('BCYF Camp Joy', 'Boston Centers for Youth and Families', 'https://www.boston.gov/departments/boston-centers-youth-and-families/bcyf-camp-joy', 'https://www.boston.gov/sites/default/files/file/2026/01/Application_CampJoy2026.pdf', 'Roberta.Smalls@boston.gov', '617-961-6952', NULL, 'Boston', 'MA', '02120', 'Boston, MA', 'day', ARRAY['special_needs']::text[], NULL, ARRAY['Group games','Gym time','Arts and crafts','Peer socialization']::text[], NULL, 3, 15, NULL, NULL, 'A city-run, four-week, full-day summer camp for Boston residents with disabilities ages 3-15 and their siblings ages 3-7, run by Boston Centers for Youth & Families. Activities range from group games to gym time and arts and crafts. It includes breakfast, lunch, door-to-door transportation and a licensed nurse at each site.', NULL, NULL, 80, 275, NULL, 'session', NULL, TRUE, TRUE, NULL, 'Fees are paid by money order only, with no refunds.', 'Open only to Boston residents with disabilities ages 3-15 (proof of residency required). Siblings ages 3-7 may also attend. Campers must be able to take part at a ratio of 4 participants to 1 staff member. Each site has a licensed nurse, and all staff are professionally trained and CPR certified. Slots are first come, first served, and only completed applications are accepted.', NULL, NULL, NULL, 2026, '9ac937df-4f4d-50c5-9163-9f0e617fc6a0', 'bcyf-camp-joy-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.boston.gov/departments/boston-centers-youth-and-families/bcyf-camp-joy','https://www.boston.gov/sites/default/files/file/2026/01/Application_CampJoy2026.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Belmont Hill Sport Camps', 'Belmont Hill School', 'https://www.belmonthill.org/about/summer-programs/sport-camps', 'https://programregistration.veracross.com/App/bhs/ProgramRegistration/sportcamps/Landing/Public', 'summerprograms@belmonthill.org', '617-993-5215', '350 Prospect Street', 'Belmont', 'MA', '02478', 'Boston, MA', 'day', ARRAY['sports']::text[], NULL, ARRAY['Baseball','Basketball','Flag football','Lacrosse','Multi-sports','Soccer','Strength & conditioning']::text[], NULL, 6, 15, NULL, NULL, 'Weeklong full-day sport camps (9:00 am–4:00 pm) for boys and girls ages 6–15, run by Belmont Hill School, with coed and single-sex camps in baseball, basketball, flag football, lacrosse, multi-sports, soccer, and strength & conditioning. Campers bring their own lunch.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 'Each week or session requires a $100 nonrefundable deposit, credited toward fees. After May 18, 2026, no refunds for enrollment changes, withdrawal, or failure to attend. Students withdrawn for insufficient English get no refund.', NULL, NULL, NULL, NULL, 2026, 'ffc84fd2-85f6-541d-b92b-372910eb60c9', 'belmont-hill-sport-camps-belmont', ST_GeogFromText('SRID=4326;POINT(-71.1787 42.3959)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.belmonthill.org/about/summer-programs/sport-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Brookline Recreation Summer Day Camp', 'Brookline Recreation Department', 'https://www.brooklinerec.com/156/Camp-Information', 'https://rec.us/brookline', 'recreation@brooklinema.gov', '617-730-2069', '725 Washington St', 'Brookline', 'MA', '02446', 'Boston, MA', 'day', ARRAY['arts']::text[], NULL, ARRAY['Arts and crafts','Non-competitive games']::text[], NULL, NULL, NULL, 0, 8, 'A town-run summer day camp for children entering grades K–8, with an emphasis on arts and crafts and non-competitive games. Campers go to one of three camps by fall grade: Camp Chestnut (K–1) at Driscoll School, Camp Coolidge (grades 2–4) at Hayes School, and Camp Washington (grades 5–8) at Runkle School. Hours are 8:30am to 4pm, with extended day to 5:30pm for Chestnut and Coolidge.', NULL, NULL, NULL, NULL, 325, 'week', TRUE, FALSE, NULL, TRUE, 'If you withdraw before Friday, May 1, 2026, you get back 80% of what you have paid. The 20% deposit and the online service fee are not refunded. After May 1 there are no refunds unless a doctor''s note supports a medical reason or emergency.', 'The camp describes itself as inclusive. Staff make individual adaptations and collect camper IEPs (individual education plans). Supports include visual and pocket-sized schedules, sensory toys and individual camp plans. One-on-one support staff are not offered. Children in summer programs run by the Public Schools of Brookline must register for camp separately.', NULL, NULL, NULL, 2026, 'b46697ea-277b-579b-83a3-c149b2290730', 'brookline-recreation-summer-day-camp-brookline', ST_GeogFromText('SRID=4326;POINT(-71.1212 42.3318)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.brooklinerec.com/156/Camp-Information']::text[], '2026-11-13', '2026-11-13', TRUE),
('Brooks Day Camp – Group 3 (Ages 8-10)', 'Summer at Brooks (Brooks School)', 'https://summer.brooksschool.org/program/brooks-day-camp-8-10/', 'https://brookssummer.campbrainregistration.com/', NULL, '(978) 725-6253', '1160 Great Pond Road', 'North Andover', 'MA', '01845', 'Boston, MA', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Archery','Arts & Crafts','Boating & Fishing','Camp Craft','Choice','Drama','Explorations','Gaga','Game Zone','Golf','Gymnastics','Music','Paddle Sports','Sports','Strength & Agility','Swim Lessons & Free Swim']::text[], NULL, 8, 10, NULL, NULL, 'A day camp for ages 8 to 10 at Brooks School in North Andover, run in two-week sessions from 8:30 AM drop-off to 4:30 PM pick-up. Campers rotate through athletics, arts, nature and swim, and also get daily choice blocks where they pick their own activities.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, TRUE, NULL, NULL, 'Daily swim lessons and free swim are included. The aquatics program is run by an Aquatics Supervisor who is lifeguard certified and a Certified Pool Operator. Boating & fishing and paddle sports are also on the activity list.', NULL, NULL, 2027, '405118cf-6e1e-59bd-915a-79743ae0dba4', 'brooks-day-camp-group-3-ages-8-10-north-andover', ST_GeogFromText('SRID=4326;POINT(-71.1351 42.6987)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://summer.brooksschool.org/dates-rates/','https://summer.brooksschool.org/program/brooks-day-camp-8-10/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Cambridge YMCA Summer Program', 'Cambridge YMCA', 'https://www.cambridgeymca.org/child-care/summer-program/', 'https://ymcacambridge.sgasoftware.com/Sales/Product?ProductTypeID=600&MemberID=&FamilyID=', 'mrothermel@cambymca.org', '(617) 661-9622', '820 Massachusetts Ave', 'Cambridge', 'MA', '02139', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','arts','STEM']::text[], ARRAY['Swim lessons','Gross motor play','Outdoor play','THINK-GIVE curriculum (ages 5–7)','STEM programs (ages 7–13)','Arts and crafts','Group games','Cooking','Team building','Weekly field trips/special events']::text[], NULL, 5, 13, NULL, NULL, 'A full-day summer program (8:00 a.m.–5:00 p.m., Monday–Friday) for ages 5–13 at the Cambridge YMCA, licensed by the Massachusetts Department of Early Education and Care. Children are grouped in three age-based classrooms. Enrichment includes swim lessons, outdoor and gross motor play, STEM programs for ages 7–13, teacher-led activities such as arts and crafts, games and cooking, and weekly field trips or special events.', NULL, NULL, 300, 300, 300, 'week', NULL, NULL, NULL, TRUE, 'A $150 non-refundable deposit is due for each enrolled week once your child is accepted. The page gives no other refund terms.', NULL, 'Swim lessons are listed as part of the program''s enrichment. The page does not say where they take place or how swimmers are supervised or tested.', NULL, NULL, 2026, '965ee1ef-dad6-5a24-861c-2bba4ddfb0b6', 'cambridge-ymca-summer-program-cambridge', ST_GeogFromText('SRID=4326;POINT(-71.1097 42.3736)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.cambridgeymca.org/child-care/summer-program/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Bauercrest', NULL, 'https://bauercrest.org', 'https://bauercrest.campintouch.com/ui/login/Login?t=HfTBfW0tWRuT9x6cYx0-NgiUzfyuRQ3w1FiVPMZR94UJMeR82BJJD_4EC-B3CirLZLl-up7KQjdWcMPO05Eb2flldwFOZHvlQXKzi8hDYXUMGYjS51va33Z2oFC16r6aMG1PfkjeAUWzDRXx8FjXUu55OEOPw_otQh5Q0mDeIR_nN5j8tSAkwsZBqJWfBMCIH3XEG5JnDGHj03pW5mr2ttEZAoH-u1TrYOwke8nsQkNEMyqI15L-reitYpoiesb5C2uHeKIH6TSKt3HFWuk-LLdrmHMa3itpkv8Pvxf4jiDDMIXaTFWOfyo_sKGnbQt9X00VNlGqFDfzOyLBdkWbPPPEg356Sb51EAWkVTdxkh4JCR4d', NULL, '(978) 388-4732', '17 Old County Road', 'Amesbury', 'MA', '01913', 'Boston, MA', 'sleepaway', ARRAY['sports','faith','arts']::text[], NULL, ARRAY['Athletics','Water sports','Creative arts & digital media']::text[], 'boys', 7, 17, NULL, NULL, 'Overnight summer camp for boys 7–17 in Amesbury, MA, built around sports and Jewish values. Families choose a 7-week full summer, one of two 3.5-week sessions, or a 2-week Mini Camp for first-time campers up to 6th grade.', NULL, NULL, 4200, 13200, NULL, NULL, NULL, NULL, NULL, TRUE, 'Deposits are nonrefundable once a spot is reserved. Cancellations must be sent in writing by email. Pay in full, half in January and half in May, or a 4-, 6- or 8-month plan charged on the 20th. Tuition is due in full by May 20; enrollments on or after May 1 pay in full at enrollment.', NULL, NULL, NULL, NULL, 2027, '936d3979-5036-51a7-9078-ea677fe0db7d', 'camp-bauercrest-amesbury', ST_GeogFromText('SRID=4326;POINT(-70.9558 42.8513)'), FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://bauercrest.org/','https://bauercrest.org/about/dates-rates/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Bournedale', NULL, 'https://campbournedale.com/', 'https://campbournedale.campintouch.com/ui/forms/application/camper/App', 'bournedale@comcast.net', '508-888-2634', '110 Valley Road', 'Plymouth', 'MA', '02360', 'Boston, MA', 'day', ARRAY['sports','nature','arts','STEM']::text[], NULL, ARRAY['Fishing','Water trampoline','Kayaking','Canoeing','Swimming','Tubing','Sailing','Wakeboarding','Waterskiing','Paddleboarding','Soccer','Pickleball','Hockey','Tennis','Basketball','Baseball','Rocketry','Marine science','Arts & crafts']::text[], NULL, 4, 14, NULL, NULL, 'Co-ed summer day camp in Plymouth, MA for ages 7 to 14, Monday to Friday 9 AM to 5 PM, with waterfront sports on Great Herring Pond, an indoor heated pool, field sports, rocketry, marine science and arts & crafts. A separate Little Guppies program (ages 4 to 6, 9 AM to 3 PM) is for younger children, who must be fully toilet trained.', NULL, NULL, 350, 575, 575, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, 'Waterfront on Great Herring Pond with tubing, wakeboarding, waterskiing, sailing, kayaking, a large water trampoline and a 15-foot iceberg, plus a large indoor heated pool. Little Guppies have swim lessons in the indoor pool. The pages do not describe swim testing or lifeguard ratios.', NULL, NULL, 2026, '3758a249-8010-5493-a427-473d3334e7ae', 'camp-bournedale-plymouth', ST_GeogFromText('SRID=4326;POINT(-70.6673 41.9584)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://campbournedale.com/about-the-camp/summer-day-camp/','https://campbournedale.com/camp_dates_rates/','https://campbournedale.com/littles_campers/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Brookside', 'Boys & Girls Clubs of Metro South', 'https://www.bgcmetrosouth.org/campbrookside', 'https://operations.daxko.com/Online/5285/ProgramsV2/Search.mvc?keywords=&program_id=&expanded=categories%2Clocations&coming_soon=False&category_ids=CAT347&all_categories=false&location_ids=B240&all_locations=false&date_ranges%5B0%5D.start=&date_ranges%5B0%5D.end=&birth_dates=', NULL, '(508) 584-5209', '233 Warren Avenue', 'Brockton', 'MA', '02301', 'Boston, MA', 'day', NULL, NULL, NULL, NULL, 5, 12, NULL, NULL, 'An indoor summer day camp for ages 5-12 at the Brockton Clubhouse, held Monday-Friday from 9:00 AM to 4:00 PM, with a different theme each week. Children must be Club members (or register as members) to attend.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'fa0430e0-f272-5165-ac67-52ad4fbb1461', 'camp-brookside-brockton', ST_GeogFromText('SRID=4326;POINT(-71.0184 42.0834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.bgcmetrosouth.org/campbrookside']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Christina', 'Old Colony YMCA', 'https://www.oldcolonyymca.org/child-care-camps/camps/camp-christina', 'https://oldcolonyymca.my.site.com/s/registration?program=Camp%20Christina', NULL, '781-341-2016', '445 Central Street', 'Stoughton', 'MA', '02072', 'Boston, MA', 'day', ARRAY['sports','nature','arts']::text[], NULL, ARRAY['Ropes course (high and low)','Swimming / swim lessons','Archery','Arts and crafts','Sports','Outdoor adventure','Environmental awareness','Fishing in the pond','Splash park']::text[], NULL, NULL, NULL, NULL, NULL, 'A YMCA summer day camp in Stoughton, MA, with an outdoor pool and splash park, a high and low ropes course, archery, arts and crafts, sports and nature activities. Campers bring a bag lunch each day, and bus routes are available for a fee.', NULL, NULL, 345, NULL, 345, 'week', TRUE, TRUE, FALSE, NULL, NULL, NULL, 'Campers use the indoor and outdoor pools and the splash park during each session. They take a short version of a YMCA swim lesson and also get free swim time. Certified lifeguards and trained swim instructors watch the swimming areas.', NULL, NULL, 2026, 'f1d6fafc-c323-5a70-8aea-31aa1425c7e3', 'camp-christina-stoughton', ST_GeogFromText('SRID=4326;POINT(-71.1023 42.1251)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.oldcolonyymca.org/child-care-camps/camps/camp-christina','https://www.oldcolonyymca.org/sites/default/files/2026-05/FamilyHandbook_CampChristina_SummerCamp_2026.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Clearbrook', 'MetroWest YMCA', 'https://www.metrowestymca.org/camp/camp-clearbrook', 'https://ymcametrowest.sgasoftware.com/Sales/Product?MemberID=0&CurrentFamilyID=0&ProductID=&UnitID=&DT=GroupedList&DS=0&CheckEligibility=True&Age=-1&DL=10&Gender=B&BranchID=110&ProductTypeID=600&IncludeWaitList=True&StartDateFrom=&StartDateTo=&BeginTime=&EndTime=', 'jhyman@metrowestymca.org', '(508) 879-4420', '120 Parker Road', 'Framingham', 'MA', '01702', 'Boston, MA', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['Swim lessons','Recreational swimming','Arts & crafts','Social-emotional learning (SEL) activities','Traditional camp games','Sports','Gaga ball','Kickball','Tennis','Field games','Splash pad','Family Fun Nights']::text[], NULL, NULL, NULL, 1, 6, 'A part-day YMCA camp (9:00 AM–2:00 PM) at Clearbrook Swim Club in Framingham for kids entering grades 1–6. Families can pick 2, 3 or 5 days a week. Days include swim lessons, free swim, arts and crafts, sports, camp games and social-emotional learning activities.', NULL, NULL, 144, 357, 357, 'week', TRUE, NULL, TRUE, TRUE, 'You pay a non-refundable $50 deposit per week, per child. Deposits can be moved to other camps before April 1 but not after. The deadline to cancel or transfer is May 31. After that there are no refunds, credits or transfers. Changes must be requested in writing by email. A credit or refund (minus the deposit) may be given for an illness or injury lasting 3 or more days if you send a doctor''s note before the session ends.', 'The YMCA aims to include all children and asks families to share any needs ahead of time so staff can plan. It says it is not a therapeutic or special needs organization and cannot provide specialized levels of support. Contact the Director of Inclusion, Laina Abolfazli: (508) 876-6094, labolfazli@metrowestymca.org.', 'The site has a large outdoor pool and a splash pad. Campers get daily swim lessons and a recreational swim. They take a swim evaluation on the first day ("Test. Evaluate. Protect."; new campers are tested on Mondays, with retests on Fridays or on request) and get a necklace showing which parts of the pool they may use. Red-neckband swimmers must wear a Coast Guard-approved flotation device during open swim.', NULL, NULL, 2026, 'db1d9b2c-25d7-517b-9da7-cfddc6fb9abf', 'camp-clearbrook-framingham', ST_GeogFromText('SRID=4326;POINT(-71.4162 42.2793)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.metrowestymca.org/camp/camp-clearbrook']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Evergreen', 'Loscutoff family', 'https://www.campevergreen.com/', 'https://www.campevergreen.com/registration.html', 'office@campevergreen.com', '978-475-2502', '166 Jenkins Road', 'Andover', 'MA', '01810', 'Boston, MA', 'day', ARRAY['nature','sports']::text[], NULL, ARRAY['swimming','canoeing','hiking','football','woodshop']::text[], NULL, 5, 14, NULL, NULL, 'A day camp in Harold Parker State Forest in Andover, MA, for ages 5 to 14, with lakes, ponds and hiking trails. Activities include swimming, canoeing, football and woodshop, and the camp also runs a spring vacation week.', NULL, NULL, 649, 713, NULL, 'week', TRUE, TRUE, FALSE, NULL, 'A 25% per-week registration fee is included in tuition and is non-refundable. Tuition is due in full by May 1 and is non-refundable once paid. Cancellations must be in writing before May 1 for any refund; camp credit only for documented medical withdrawals. 5% early-bird discount before January 31.', NULL, 'The camp has an in-ground pool with a diving board, an above-ground pool and a boating pond. Only deep-end swimmers may go on canoe trips. The pages checked do not say how swim levels are tested or about lifeguards.', NULL, NULL, 2026, 'cb9fd735-204a-548e-a5af-c52b459d3e73', 'camp-evergreen-andover', ST_GeogFromText('SRID=4326;POINT(-71.137 42.6584)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://irp.cdn-website.com/ed7bd1aa/DESKTOP/pdf/calendar%202026_1_.pdf','https://www.campevergreen.com/','https://www.campevergreen.com/about_us.html','https://www.campevergreen.com/facilities.html','https://www.campevergreen.com/faqandofficialpolicies.html','https://www.campevergreen.com/tuition.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp OCP (OCP Summer Program)', 'MetroWest YMCA', 'https://www.metrowestymca.org/camp/camp-ocp', 'https://ymcametrowest.sgasoftware.com/Sales/Product?MemberID=0&CurrentFamilyID=0&ProductID=&UnitID=&DT=GroupedList&DS=0&CheckEligibility=True&Age=-1&DL=10&Gender=B&BranchID=310&ProductTypeID=600&IncludeWaitList=True&StartDateFrom=&StartDateTo=&BeginTime=&EndTime=', 'wmitchell@metrowestymca.org', '(508) 435-9345', '280 Old Connecticut Path', 'Framingham', 'MA', '01701', 'Boston, MA', 'day', ARRAY['academic','STEM','sports','arts']::text[], NULL, ARRAY['Swim lessons','Free swim','Field trips','Special guests','Arts and crafts','Teambuilding','Field games','STEM activities','Social-emotional learning','English language arts','Global learning','Family Fun Nights']::text[], NULL, NULL, NULL, 1, 8, 'A summer day program at the MetroWest YMCA in Framingham for kids entering grades 1-8. It focuses on preventing summer learning loss through English language arts, global learning, STEM and social-emotional activities, with swim most days and weekly field trips or visiting guests.', NULL, NULL, 208, 519, 519, 'week', TRUE, NULL, TRUE, TRUE, 'You pay a non-refundable $50 deposit per week, per child, when you register. Extended care is paid in full at registration. Deposits can be moved to another camp program before April 1 but not after. The deadline for cancellations and transfers is May 31, and after that there are no refunds, credits or transfers. All changes must be sent in writing by email. If a child misses camp because of an illness or injury lasting 3 days or more, the Y may give a credit or a refund (minus the deposit) if you send a doctor''s note before the session ends. There are no refunds or pro-rating for missed days.', 'The Y tries to accommodate children who need extra support and asks families to tell them about any needs ahead of time. However, it says it is "not a therapeutic or special needs organization." The Director of Inclusion is Laina Abolfazli: (508) 876-6094, labolfazli@metrowestymca.org.', 'Swim lessons and free swim are included, but there is no swim on Mondays. Campers take a swim evaluation on the first day ("Test. Evaluate. Protect."), and new campers are tested on Mondays. Kids who test at the red-neckband level must wear a Coast Guard-approved flotation device during open swim. Campers can be retested on Fridays or on request.', NULL, NULL, 2027, '4ad889a7-bf34-56ce-ae80-9540192c5edc', 'camp-ocp-ocp-summer-program-framingham', ST_GeogFromText('SRID=4326;POINT(-71.4162 42.2793)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.metrowestymca.org/camp/camp-ocp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Satucket', 'Old Colony YMCA', 'https://www.oldcolonyymca.org/child-care-camps/camps/camp-satucket', 'https://oldcolonyymca.my.site.com/s/registration?program=Camp%20Satucket', NULL, '508-378-3913', '635 Plymouth St', 'East Bridgewater', 'MA', '02333', 'Boston, MA', 'day', ARRAY['sports','nature','arts','STEM']::text[], NULL, ARRAY['Low and high ropes course','Zip line','Swimming (indoor and outdoor pool)','Swim lessons','Archery','Arts and crafts','Sports','Outdoor adventure','Environmental awareness','Fishing in the pond','Science','Theme days','Family fun nights']::text[], NULL, NULL, NULL, NULL, NULL, 'A YMCA day camp in East Bridgewater with low and high ropes courses, a zip line, swimming and swim lessons, archery, sports, science, arts and crafts, and nature activities. Each week has a theme, and there are family fun nights.', NULL, NULL, 345, NULL, 345, 'week', NULL, TRUE, FALSE, TRUE, NULL, NULL, 'Campers use both the indoor and outdoor pool. Certified lifeguards and trained swim instructors watch the swim areas. Activities include free swim, aquatic games, and some water and boat safety. A YMCA swim lesson is included in camp at no extra cost.', NULL, NULL, 2026, '55f06bc6-eb50-5414-9b6c-081fdd02e501', 'camp-satucket-east-bridgewater', ST_GeogFromText('SRID=4326;POINT(-70.9422 42.0371)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.oldcolonyymca.org/child-care-camps/camps/camp-satucket']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Three Rivers', 'Concord Recreation Department', 'http://summercamp.concordma.gov/251/Camp-Three-Rivers', 'https://concordrec.myrec.com/info/activities/default.aspx?CategoryID=1547&type=', 'concordrec@concordma.gov', '978-287-1050', '90 Stow Street (Emerson Field, Hunt Recreation Center)', 'Concord', 'MA', '01742', 'Boston, MA', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['swimming','art','sports','nature/science','music/drama','archery','field trips','visiting artists','themed weeks','CIT leadership workshops']::text[], NULL, NULL, NULL, 0, 10, 'A town-run summer day camp in Concord, MA, at Emerson Field, for children entering kindergarten through 8th grade, with a counselor-in-training (CIT) program for grades 9–10. Activities include swimming, art, sports, nature/science, music/drama and archery, plus weekly field trips. Older groups go on more trips each week.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, NULL, 'A 50% deposit is due at registration in February and is non-refundable; the other 50% is due May 1. Cancelling before May 1 costs a $35 fee. After May 1, a 50% refund of the final payment (less $35) is possible if June weeks are cancelled by May 8, July weeks by June 1 and August weeks by July 1. Transfers cost $35.', NULL, 'Campers swim at the outdoor Emerson Pool, closed to the public during camp and staffed by certified water safety instructors and lifeguards. Free swim only, no lessons. Campers take a swim test to use the deep end.', NULL, NULL, 2026, 'd0268c68-08e8-533e-9ece-524a51bb86a4', 'camp-three-rivers-concord', ST_GeogFromText('SRID=4326;POINT(-71.3489 42.4604)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['http://summercamp.concordma.gov/251/Camp-Three-Rivers','http://summercamp.concordma.gov/DocumentCenter/View/4460/Summer-Camp-and-Kaleidoscope-Cancellation-Policy','http://summercamp.concordma.gov/DocumentCenter/View/4479/Camp-Three-Rivers-Parent-Packet-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Club Adventure Summer Camp', 'Watertown Boys & Girls Club', 'https://watertownbgc.org/wbgc-programs/summer/', 'https://online.traxsolutions.com/watertown/main#/activities/groups/75', 'info@watertownbgc.org', '617.926.0968', '25 Whites Avenue', 'Watertown', 'MA', '02472', 'Boston, MA', 'day', ARRAY['general']::text[], NULL, ARRAY['Gym games','Outdoor games','Swim lessons (three times per week)','Free swim','Arts & crafts','STEM projects','Team building','Sports','Trivia','Field trips (Tree Top Adventures, Boston Adventure, XtremeCraze, Water Wizz)','Optional age-group mini-trips (extra cost)']::text[], NULL, 7, 12, NULL, NULL, 'Weekly day camp at the Watertown Boys & Girls Club for ages 7-12, running 8:00 AM-4:00 PM with optional extended day until 5:30 PM. Days mix gym and outdoor games, swim lessons and free swim, STEM projects, arts and crafts and team building, and four weeks include a full-camp field trip. Campers need an active WBGC membership ($25) to register.', NULL, NULL, 120, 330, 300, 'week', TRUE, NULL, FALSE, TRUE, 'A $75 non-refundable deposit per child per week is required if not paying in full at registration. Balances are due June 1 for June/July weeks and July 1 for August weeks. A cancellation made less than one week ahead forfeits the whole week''s fee, and campers suspended for behavior get no refund. The $25 membership fee is non-refundable.', 'The Club cannot provide 1-to-1 care or supervision; families of children with specialized care or supervision needs are asked to contact the Club before enrolling.', 'Swim lessons three times per week and a daily free swim period at the Club pool, per the sample schedule. Swimmers bring their own goggles. The brochure gives no detail on swim testing.', NULL, NULL, 2026, '6c61d0bb-b6b8-5848-95cd-f130d3f3d954', 'club-adventure-summer-camp-watertown', ST_GeogFromText('SRID=4326;POINT(-71.1828 42.3709)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://watertownbgc.org/wbgc-programs/summer/','https://watertownbgc.org/wp-content/uploads/2026/03/2026-Club-Adventure-brochure-3.17.26.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Connections Summer Expeditions', 'Cathleen Stone Island Outward Bound', 'https://cathleenstoneisland.org/programs/connections/expeditions', NULL, 'JCorcione@cathleenstoneisland.org', '617-830-5131', NULL, 'Boston', 'MA', '02127', 'Boston, MA', 'sleepaway', ARRAY['nature']::text[], NULL, ARRAY['Backpacking','Sea kayaking','Camping','Climbing','High and low ropes courses','Camp craft and wilderness skills','Geology and ecology exploration','Environmental stewardship']::text[], NULL, NULL, NULL, 7, 8, 'Free 5- or 7-day overnight expeditions (backpacking/climbing or sea kayaking/camping) on Cathleen Stone Island and in Boston Harbor for rising 7th and 8th graders enrolled in Boston Public Schools. Students cook, set up shelters, and learn wilderness skills, teamwork and environmental stewardship.', NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, 'Kayaking expeditions paddle Boston Harbor in two-person sea kayaks. Instruction covers paddling, capsize and rescue procedures, weather forecasting and navigation. No kayaking or outdoor experience needed.', NULL, NULL, 2026, 'd8f16b64-30c5-52b7-9094-1214a35e53fa', 'connections-summer-expeditions-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://cathleenstoneisland.org/lib/file/manager/Programs/2026%20CSIOBS%20Cnx%20Exp%20Q&A.pdf','https://cathleenstoneisland.org/programs/connections/expeditions']::text[], '2026-11-13', '2026-11-13', TRUE),
('Creative Camp', 'Levitate Camps (Levitate Brand)', 'https://levitatecamps.com/creative-camp/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=1560&campCode=DD3', 'info@levitatecamps.com', NULL, '1871 Ocean St.', 'Marshfield', 'MA', '02050', 'Boston, MA', 'day', ARRAY['arts','nature','performing_arts']::text[], NULL, ARRAY['Art projects in a range of mediums','Music','Nature walks off campus','Plein air painting','Photography (polaroid)','Wildflower identification and bouquet making','Learning about bees and pollinator plants','Growing and preparing healthy snacks']::text[], NULL, 5, 10, NULL, NULL, 'A half-day music, arts and conservation camp for ages 5–10, held Monday to Thursday mornings at the Levitate Backyard in Marshfield, MA. Kids are grouped by age, go on walking trips into nature, and do daily workshops with local artists, farmers, photographers and chefs. The curriculum changes each week.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, 'The 10% deposit is non-refundable. Cancel 60+ days before the start for a 90% refund, or 30–59 days before for a 50% refund. No refund within 30 days of the start, during a session, or for missed days. All fees are refunded if camp is cancelled for public health reasons. You can switch sessions for free if space allows.', NULL, NULL, NULL, NULL, 2027, 'abbb6054-82c6-566a-8f44-93ce34af9b9f', 'creative-camp-marshfield', ST_GeogFromText('SRID=4326;POINT(-70.7056 42.0918)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://levitatecamps.com/creative-camp/','https://levitatecamps.com/faq/']::text[], '2026-11-13', '2026-11-13', TRUE),
('CSW Summer Day Camp', 'The Cambridge School of Weston', 'https://cswsummer.org/', 'https://www.homeroom.com/sites/the-cambridge-school-of-weston-weston/camp', 'summercamp@csw.org', '781-642-8605', '45 Georgian Road', 'Weston', 'MA', '02493', 'Boston, MA', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['swimming','recreational sports','arts and crafts']::text[], NULL, 4, 14, NULL, NULL, 'A summer day camp on the campus of The Cambridge School of Weston for ages 4-14, run in two-week sessions from 9 a.m. to 4 p.m. Activities, led by counselors, include daily swim lessons and free swim in the campus pool, recreational sports, and arts and crafts, both indoors and outdoors. Lunch and snacks are provided.', NULL, NULL, 1500, 1700, NULL, 'session', TRUE, NULL, TRUE, NULL, 'A $250 non-refundable deposit per session is due at registration. Deposits are not refunded after March 1, 2027. Other payments (less deposits) are refundable or transferable until May 1, 2027 with written notice. $100 per session early-bird discount before December 31.', NULL, 'Campers swim twice a day in CSW''s outdoor pool (built 2025, 2.75 to 5 feet deep): lessons in the morning and free swim in the afternoon. Certified lifeguards are led by an Aquatics Director. A swim test (two widths and 60 seconds treading water) is needed for the deep end.', NULL, NULL, 2027, 'b9e78656-2f5b-5b30-a451-70eb1431ad64', 'csw-summer-day-camp-weston', ST_GeogFromText('SRID=4326;POINT(-71.3034 42.3668)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://cswsummer.org/','https://cswsummer.org/dates-and-rates/','https://cswsummer.org/discover-csw-summer/','https://cswsummer.org/discover-csw-summer/aquatics-program/','https://cswsummer.org/registration/','https://www.csw.org/community/summer-and-enrichment']::text[], '2026-11-13', '2026-11-13', TRUE),
('Derby Summer Programs', 'Derby Academy', 'https://www.derbyacademy.org/summer2026/programs-and-tuition', 'https://derbyacademysummer.campbrainregistration.com/', 'summer@derbyacademy.org', '781-749-0746', '56 Burditt Avenue', 'Hingham', 'MA', '02043', 'Boston, MA', 'day', ARRAY['arts','performing_arts','STEM','technology','sports','nature']::text[], NULL, ARRAY['art','nature','games','outdoor play','theater','dance','culinary','basketball','soccer','rowing','sailing','golf','LEGO Robotics','3-D printing','AI-focused labs']::text[], NULL, 4, 15, NULL, NULL, 'Half-day summer programs (9:00 AM–12:00 PM) at Derby Academy in Hingham for ages 4–15, in four tracks: Camp Derby, Arts, STEM and Sports. Families can pay extra for an Extended Day through 4:00 PM that includes lunch, the noontime show, a daily choice period and two more classes.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '2be53731-b636-525c-be0f-6074ee82a49a', 'derby-summer-programs-hingham', ST_GeogFromText('SRID=4326;POINT(-70.8898 42.2418)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.derbyacademy.org/summer2026/programs-and-tuition','https://www.derbyacademy.org/summer2026/programs-and-tuition/camp-derby','https://www.derbyacademy.org/summer2026/programs-and-tuition/summer-arts','https://www.derbyacademy.org/summer2026/tuition-and-financial-aid']::text[], '2026-11-13', '2026-11-13', TRUE),
('DHSP Summer Camps and Programs (K-8)', 'City of Cambridge Department of Human Service Programs (DHSP)', 'https://www.cambridgema.gov/services/summercampsandprograms', NULL, 'askdhsp@cambridgema.gov', '617-349-6200', '51 Inman St.', 'Cambridge', 'MA', '02139', 'Boston, MA', 'day', ARRAY['STEM','arts','sports']::text[], NULL, ARRAY['math','science','art','physical activity','cultural exploration','social emotional learning','field trips','swimming','swim instruction (K-5)','waterplay']::text[], NULL, NULL, NULL, 0, 8, 'City-run full-day summer camps (8:30 a.m. to 5:30 p.m.) for Cambridge residents and City employees'' children in Kindergarten through 8th grade, including Community Schools Summer Camps, the King Open Extended Day Summer Program, and Cambridge Youth Programs Pre-Teen / Middle School Summer Programs. Places are filled through a single lottery, and tuition is based on family size and income.', NULL, NULL, 60, 600, NULL, 'session', NULL, FALSE, TRUE, TRUE, 'A non-refundable tuition deposit is due in June. Other refund terms are not stated. To drop a session, contact DHSP.', 'Children with IEPs or 504 Plans are encouraged to apply, and having one does not affect lottery chances. DHSP''s Inclusion Initiative assesses each child and arranges extra supports where needed. Camp Rainbow, a separate program, serves Cambridge residents with disabilities ages 6-22 and provides transportation.', 'Campers swim at Cambridge pools staffed by Red Cross-certified lifeguards. Children in K-5 get swim instruction and learn pool safety. There is also waterplay at playgrounds near the camp sites.', NULL, NULL, 2026, '8eb5cf28-af1e-521b-8ddd-e553332ead4a', 'dhsp-summer-camps-and-programs-k-8-cambridge', ST_GeogFromText('SRID=4326;POINT(-71.1097 42.3736)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.cambridgema.gov/-/media/Files/DHSP/Summer/SummerTuition.pdf','https://www.cambridgema.gov/services/summercampsandprograms']::text[], '2026-11-13', '2026-11-13', TRUE),
('Energy Center Camp (Ages 4-6)', 'Weymouth Club', 'https://www.weymouthclub.com/camps/energy-center-camp-ages-4-6/', NULL, 'lmankus@weymouthclub.com', '(781) 682-5833', '75 Finnell Drive', 'Weymouth', 'MA', '02188', 'Boston, MA', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['Tennis','Free swim','Table games','Group games','Arts & crafts','Gym time','Free play','Private Energy Center time']::text[], NULL, 4, 6, NULL, NULL, 'A day camp at the Weymouth Club for children ages 4 to 6, running 9:00 a.m. to 2:00 p.m. Activities include tennis, free swim, games, arts and crafts and gym time, with a theme each week.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'No refunds or transfers once the club accepts a registration, for any reason (withdrawal, dismissal, missed days). Payment is due in full when you register.', NULL, 'The daily schedule includes free swim. Children should wear a bathing suit to camp every day and bring a towel. Swim supervision and swim testing are not described.', NULL, NULL, 2027, '598295de-a5a0-551a-85fc-74bb9175987c', 'energy-center-camp-ages-4-6-weymouth', ST_GeogFromText('SRID=4326;POINT(-70.9395 42.2209)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.weymouthclub.com/camps/energy-center-camp-ages-4-6/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Everwood Day Camp', NULL, 'https://everwooddaycamp.com/', 'https://everwooddaycamp.com/enroll/', 'info@everwooddaycamp.com', '781-694-5829', '125 Lakeview Street', 'Sharon', 'MA', '02067', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts','outdoor','adventure','nature']::text[], ARRAY['Daily swim lessons','Free swim','Waterfront (kayaking, canoeing, stand-up paddleboarding, fishing)','Athletics/sports','Arts and STEAM','Outdoor adventure (high ropes, archery)','Special events','Electives']::text[], NULL, 4, 15, NULL, NULL, 'A traditional coed day camp on Lake Massapoag in Sharon, MA for children about 4 to 15, running four 2-week sessions from June 21 to August 13, 2027, plus an optional add-on Post Week. Activities include swim instruction, waterfront, sports, arts, outdoor adventure, special events and electives, and tuition includes daily swim lessons.', NULL, NULL, 1995, 7640, NULL, NULL, TRUE, TRUE, FALSE, TRUE, 'Before Feb 1, 2027: all tuition and deposits are fully refundable. After Feb 1, 2027: a $150 per week cancellation fee applies to each cancelled week. March 30, 2027 is the last day to reduce weeks for a refund (minus the fee). After the April 1, 2027 balance due date there are no refunds; money paid is credited to the 2028 season, minus $150 per week. No make-up days or credits for missed days.', NULL, 'Daily instructional swim (American Red Cross levels) is required for campers entering Pre-K to 4th grade, in teaching pools for Pre-K to 3rd grade and at Lake Massapoag for 4th grade; it is an elective for 5th-10th grade. All campers have a daily free swim and are assessed when they start camp. Waterfront activities on the lake may include kayaking, canoeing, paddleboarding and fishing.', TRUE, 'https://everwooddaycamp.com/about/faqs/', 2027, '44b245cd-22d4-5109-a820-f4da079248f5', 'everwood-day-camp-sharon', ST_GeogFromText('SRID=4326;POINT(-71.1773 42.1237)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://everwooddaycamp.com/about/faqs/','https://everwooddaycamp.com/dates-enrollment/','https://everwooddaycamp.com/dates-enrollment/financial-assistance/']::text[], '2026-11-13', '2026-11-13', TRUE),
('FaySummer Classic Day Camp', 'Fay School', 'https://www.faysummer.org/day-programs/classic-day-camp-age-3-grade-6', 'https://www.faysummer.org/rates-and-registration', 'summer@fayschool.org', '508.490.8371', '48 Main Street', 'Southborough', 'MA', '01772', 'Boston, MA', 'day', ARRAY['sports','arts','nature']::text[], NULL, ARRAY['Archery','Arts & Crafts','Circus Arts','Dance','Fishing','Music','Nature','Orienteering','Outdoor Adventures','Ropes Course','Science','Soccer','Sports','Tennis','Visual Arts','Wood Shop','Swimming']::text[], NULL, 3, NULL, NULL, 6, 'A general day camp at Fay School in Southborough for children age 3 through entering grade 6, 9:00 AM to 4:00 PM, in a launch week and four two-week sessions. Campers are grouped by grade and do sports, arts and crafts, a ropes/challenge course, and pool time, with younger groups on a more structured schedule. Discoverers (preschool to kindergarten) can attend half days.', NULL, NULL, 395, 1220, 610, 'session', TRUE, NULL, FALSE, TRUE, 'A non-refundable deposit is due at registration and is deducted from session fees. Cancelling before the payment due date gives a full refund minus the deposit; no refunds after the payment due date. Full refund if FaySummer cancels a program.', NULL, 'All campers get time in the camp''s pools. Discoverers (preschool to kindergarten) have swim lessons as part of their daily activities.', NULL, NULL, 2026, '349bd729-7220-5984-8b29-5121f3eda39a', 'faysummer-classic-day-camp-southborough', ST_GeogFromText('SRID=4326;POINT(-71.5245 42.3057)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.faysummer.org/day-programs/classic-day-camp-age-3-grade-6','https://www.faysummer.org/rates-and-registration']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hingham Maritime Center', 'Hingham Maritime Center', 'https://www.hinghammaritime.org', NULL, 'contact@hinghammaritime.org', '(781) 741-5225', '32 Summer Street', 'Hingham', 'MA', '02043', 'Boston, MA', 'specialty', ARRAY['sailing']::text[], ARRAY['sports','nature']::text[], ARRAY['Sailing (Opti and 420)','Sail racing','Rowing','Paddleboarding','Marine science and beach exploration (Little Mariners)','Marine-themed arts and crafts']::text[], NULL, 5, NULL, NULL, NULL, 'Youth summer programs on Hingham Harbor run by the Hingham Maritime Center: Little Mariners marine-science weeks for ages 5–7, sailing for ages 7 and up (Beginner, Intermediate, Venture, Opti Race, 420), and rowing for grades 7–12. Sessions run one to four weeks, led by experienced instructors with safety launches.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'Sailing and rowing require competent swimmers (rowers must be confident swimming underwater and watch the USRowing safety video). Sessions on Hingham Harbor are supported by safety launches. Little Mariners is mainly land-based.', NULL, NULL, 2026, '64a8c9b3-8e8d-5e93-8e67-e5a66e247c96', 'hingham-maritime-center-hingham', ST_GeogFromText('SRID=4326;POINT(-70.8898 42.2418)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.hinghammaritime.org/little-mariners','https://www.hinghammaritime.org/programs','https://www.hinghammaritime.org/scholarship','https://www.hinghammaritime.org/youth-rowing','https://www.hinghammaritime.org/youth-sailing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Holly Hill Farm Summer Programs', 'Friends of Holly Hill Farm', 'https://hollyhillfarm.org/summer-programs-2026', 'https://hollyhillfarmprogramregistration.org', 'programs@hollyhillfarm.org', '781-383-6565', '236 Jerusalem Road', 'Cohasset', 'MA', '02025', 'Boston, MA', 'day', ARRAY['nature','arts']::text[], NULL, ARRAY['Farm animal care','Organic gardening and harvesting','Nature exploration and hikes','Species identification (BioBlitz)','Art inspired by nature','Cooking','Outdoor survival skills','Shelter building','Wood carving','Living history','Counselor-in-Training leadership']::text[], NULL, 3, 15, NULL, NULL, 'Half-day and full-day summer programs on a working certified organic farm in Cohasset, MA, for children ages 3.5-14 plus a Counselor-in-Training program for ages 12-15. Children care for farm animals, garden, explore woods, marsh and pond habitats, and do art, cooking and outdoor skills, in groups by age.', NULL, NULL, 212, 603, 511, 'week', TRUE, NULL, FALSE, TRUE, 'Cancellations must be in writing. More than 3 weeks before the session start: refund minus a $100 fee per child per week ($15 for CIT). Less than 3 weeks before: no refund, unless the spot is refilled (then refund minus $100). Session changes count as cancellations, except swaps made within 72 hours of registering and by Feb 15, which cost $50. Switching between half and full day is free.', 'Garden Goats (ages 3.5-5) campers must be reliably potty-trained (no pull-ups). Staff can give only EpiPens and inhalers, no other medication. Requests to place a child outside their age group go to the Education Director, Wendy Prentiss (wendy@hollyhillfarm.org).', 'No swimming is mentioned. Campers explore the farm''s Ice Pond, ponds and marsh habitats.', NULL, NULL, 2026, '1276cf19-c6f1-5664-8d1e-58f132f6b101', 'holly-hill-farm-summer-programs-cohasset', ST_GeogFromText('SRID=4326;POINT(-70.8037 42.2418)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://hollyhillfarm.org/summer-programs-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('iSTEAM Robotics (Summer Shore)', 'Shore Country Day School', 'https://www.shoreschool.org/summer-shore/isteam-robotics', 'https://app.enrollsy.com/r/q3J4p1xW2ND6MUEdVaZQZ', 'jnorris@shoreschool.org', '(978) 927-1700', '545 Cabot Street', 'Beverly', 'MA', '01915', 'Boston, MA', 'specialty', ARRAY['STEM','technology']::text[], NULL, ARRAY['Robotics','Animal robotics / life science','VEX Go building','Hands-on engineering projects']::text[], NULL, 5, 11, NULL, NULL, 'A half-day, week-long robotics program at Shore Country Day School in Beverly, MA. It has a morning animal-robotics class for ages 5-7 and an afternoon VEX Go building class for ages 7-11.', NULL, NULL, 565, 585, NULL, NULL, NULL, NULL, NULL, NULL, 'Any cancellation costs $100. No refunds after May 31, 2026. You can pay in full online when you register, or use a monthly payment plan, which requires a camp fee deposit at registration.', NULL, NULL, NULL, NULL, 2026, 'a03fea30-563a-5cbe-b697-bbe251b5db63', 'isteam-robotics-summer-shore-beverly', ST_GeogFromText('SRID=4326;POINT(-70.88 42.5584)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.shoreschool.org/summer-shore/isteam-robotics']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kidstock! Creative Theater SUMMERSTAGE', 'Kidstock! Creative Theater', 'https://kidstocktheater.com/summer-2027/', 'https://kidstocktheater.com/registration-portal/', 'admin@kidstocktheater.com', '781-729-5543', '50 Cross St', 'Winchester', 'MA', '01890', 'Boston, MA', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Creative drama','Music and movement','Dance','Art projects','Movie-making (JingleVision)','Outdoor recreation','Friday presentations']::text[], NULL, 4, NULL, NULL, NULL, 'Kidstock!''s SUMMERSTAGE theater day program in Winchester, MA for Pre-K (age 4+) through Grade 6, 9 AM–4:30 PM. Full show weeks ($650) end with a Friday presentation; individual-day weeks ($150 per day) mix art, music, drama and dance with no final show. Extended day runs 8 AM–6 PM for an added fee.', NULL, NULL, 520, 650, 650, 'week', TRUE, NULL, FALSE, TRUE, 'Transfers to another week are free when space allows (you pay any tuition difference). Withdrawals must be emailed by noon on the Friday before your week. Withdraw 30+ days before that Friday: 100% tuition back minus the registration fee and a $50 cancellation fee per child per week. Within 29 days: 50% back. After that Friday: no refunds or credits. The $35 family registration fee is nonrefundable.', 'The program is nut-free, and staff check what''s in lunch bags. Inhalers, EpiPens and any other medication must be handed to the office.', NULL, NULL, NULL, 2027, 'b1eac234-94e7-57d9-8a58-e081533f5e40', 'kidstock-creative-theater-summerstage-winchester', ST_GeogFromText('SRID=4326;POINT(-71.137 42.4523)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=50+Cross+St&city=Winchester&state=MA&benchmark=Public_AR_Current&format=json','https://kidstocktheater.com/summer-2027/','https://kidstocktheater.com/summer-tuition-policies/']::text[], '2026-11-13', '2026-11-13', TRUE),
('LexRec Summer Day Camp', 'Town of Lexington Recreation & Community Programs (LexRec)', 'https://www.lexingtonma.gov/2503/LexRec-Summer-Day-Camp', 'https://lexrecma.myrec.com/info/activities/program_details.aspx?ProgramID=30941', 'recdept@lexingtonma.gov', '(781) 698-4800', '80 Worthen Road (Center Recreation Complex)', 'Lexington', 'MA', '02421', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['swimming','sports','arts']::text[], ARRAY['Swim lessons (Red Cross Learn to Swim)','Free swim at Town Pool','Arts and crafts','Games','Recreational sports','Imaginative play','Group challenges','Community outings and local trips (Upper Camp)','Leader in Training program (grade 9+)']::text[], NULL, NULL, NULL, 0, 8, 'A town-run, outdoor-based day camp at the Center Recreation Complex in Lexington for children entering grades K–8, split into age groups (Primary K–1, Lower 2–3, Middle 4–5, Upper 6–8). Campers in grades K–5 get swim lessons Monday–Thursday mornings, and Upper Camp (6–8) goes on community trips and off-site outings.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The camp describes itself as inclusive and links to an "Inclusion Services at Camp" resource. The Leader in Training program encourages applicants of all abilities to apply. Its eligibility rules include being able to handle personal care on their own and manage their own behavior with minimal staff help.', 'Campers use the Lexington Town Pool. Grades K–5 have 30-minute Red Cross Learn to Swim lessons Monday–Thursday mornings with Red Cross Lifeguard-certified instructors, and the pool is open to the public during these lessons. Upper Camp does not take lessons. Free swim is Monday, Wednesday and Friday afternoons. Parents choose a wristband level: red means the wading pool or splash pad only (2 ft); yellow means the Garrity Pool (4.5 ft) with a lifejacket; green means a camper who passed the deep-end test can use all pools (13 ft) without a lifejacket. Swim tests are free at the pool before camp starts. USCG Type II and III lifejackets are provided.', NULL, NULL, 2026, 'b2dfcf89-44bd-5f9b-9946-69fef676a5c6', 'lexrec-summer-day-camp-lexington', ST_GeogFromText('SRID=4326;POINT(-71.2245 42.4473)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://lexingtonma.gov/1081/Town-Aquatics','https://lexrecma.myrec.com/info/activities/program_details.aspx?ProgramID=30941','https://www.lexingtonma.gov/2503/LexRec-Summer-Day-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('MFA Boston Kids Studio Art Classes (Summer Studio Art Classes)', 'Museum of Fine Arts Boston', 'https://www.mfa.org/programs/studio-art-classes/kids', NULL, NULL, '617-369-3295', '465 Huntington Avenue', 'Boston', 'MA', '02115', 'Boston, MA', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['drawing','painting','sculpture','collage','printmaking','gallery visits']::text[], NULL, 5, 11, NULL, NULL, 'Full-day, in-person art classes at the Museum of Fine Arts Boston in summer, with groups for ages 5–7, 6–8, 8–10 and 9–11 and a new theme each week. Kids look at the museum''s collection, then draw, paint, sculpt, make collages and print. The museum also runs weekend classes during the school year and classes during school vacation weeks.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 'All ticket sales are final. Refunds are given only if the MFA cancels a class for low enrollment. No refunds or make-up classes for student absences or for classes cancelled for bad weather.', 'The museum says its classes have more rules and expectations than other youth programs. They suit only students who can stay engaged in classroom-based art making. There is no active play or outdoor time.', NULL, NULL, NULL, 2027, 'e15de38d-b1e9-5ffc-bb80-adbbc8f4c250', 'mfa-boston-kids-studio-art-classes-summer-studio-art-classes-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.mfa.org/programs/studio-art-classes/information-and-policies','https://www.mfa.org/programs/studio-art-classes/kids']::text[], '2026-11-13', '2026-11-13', TRUE),
('NARA Summer Camp', 'Athena, for the Town of Acton Recreation Department', 'https://actonma.gov/332/NARA-Summer-Camp', NULL, NULL, '978-929-6600', '25 Ledge Rock Way (NARA Park)', 'Acton', 'MA', '01720', 'Boston, MA', 'day', ARRAY['general']::text[], NULL, ARRAY['swimming','games','field trips','creative activities','outdoor activities']::text[], NULL, NULL, NULL, 0, 6, 'A summer camp at NARA Park in Acton, MA, run for the town Recreation Department, for children entering grades K–6. Activities include swimming, games, creative projects and field trips.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, 'The camp is nut-free. All physicals and immunization records must be uploaded to CampDoc.com. Paper copies are not accepted. Physicals must be from the last 18 months.', 'Swimming is part of the program at NARA Park, which has a swimming pond (NARA Beach). The camp page gives no details about swim tests or lifeguards.', NULL, NULL, 2026, 'e8f2e15f-1ff8-547b-94f1-c0bb98373f5d', 'nara-summer-camp-acton', ST_GeogFromText('SRID=4326;POINT(-71.4328 42.4851)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://actonma.gov/312/NARA-Park','https://actonma.gov/332/NARA-Summer-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Newton Community Education Summer Camp', 'Newton Community Education (Newton Public Schools)', 'https://newtoncommunityed.org/summercamp/', 'https://newtoncommunityed.org/summercamp/', 'nce-staff@newton.k12.ma.us', '617-559-6999', '457 Walnut Street', 'Newton', 'MA', '02460', 'Boston, MA', 'day', ARRAY['STEM','arts','sports','performing_arts']::text[], NULL, ARRAY['3D printing','Minecraft and coding','Circuits and engineering','Filmmaking','Arts and crafts','Zentangle drawing','Chess','Dungeons & Dragons','Tennis','Soccer','Volleyball','Cheer','Gym games','Musical theater (5-week Willy Wonka Jr.)','Counselor-in-Training']::text[], NULL, NULL, NULL, 0, 12, 'Summer camps run by Newton Community Education, part of Newton Public Schools, at Newton North High School and Horace Mann Elementary School. Families pick weekly half-day (9 AM to 12 PM) or full-day (to 3:30 PM) camps for kids entering kindergarten through high school, from 3D printing and filmmaking to tennis and chess, plus a 5-week theater camp and a CIT program.', NULL, NULL, 280, 650, NULL, 'week', TRUE, NULL, NULL, TRUE, 'A $10 non-refundable registration fee per session. Withdraw from a summer camp by June 1 for a refund minus a $50 cancellation fee per camp per student; no refunds after June 1. Transfers to another NCE summer class may be possible for a fee.', NULL, NULL, NULL, NULL, 2027, '744f8ea4-93d4-57fc-be6e-2c6fbdb7bdfb', 'newton-community-education-newton', ST_GeogFromText('SRID=4326;POINT(-71.2092 42.337)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://newtoncommunityed.org','https://newtoncommunityed.org/about-us/policies/','https://newtoncommunityed.org/summercamp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('North River Nature Camp', 'Mass Audubon', 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river/camp', NULL, 'northrivercamp@massaudubon.org', '781-355-6109', '2000 Main Street', 'Marshfield', 'MA', '02050', 'Boston, MA', 'day', ARRAY['nature']::text[], NULL, ARRAY['Exploratory hikes','Wildlife and habitat study','Crafts','Games','Water games','Nature exploration','Free play','Specialty weeks for ages 12-14 (solar/STEM projects, wilderness skills, fossils)']::text[], NULL, NULL, 14, NULL, NULL, 'A Mass Audubon nature day camp at the 225-acre North River Wildlife Sanctuary in Marshfield for children ages 4.5–14, Monday–Friday 9:00 am–3:00 pm. Campers in small age groups explore weekly nature themes through hikes, hands-on activities, games and crafts; ages 12–14 take specialty theme weeks.', NULL, NULL, 87, 579, NULL, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, TRUE, 'https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river/camp/about-camp', 2027, '1fda0307-5853-59dc-b6e6-79cee518b060', 'north-river-nature-camp-marshfield', ST_GeogFromText('SRID=4326;POINT(-70.7056 42.0918)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.census.gov/geographies/reference-files/time-series/geo/relationship-files.2020.html','https://www.massaudubon.org/content/download/81602/file/NRNC%202027%20Program%20Themes.pdf?inLanguage=eng-US&version=1','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river/camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river/camp/about-camp','https://www.massaudubon.org/places-to-explore/wildlife-sanctuaries/north-river/camp/programs-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Pequossette Summer Recreation Program', 'Watertown Recreation (City of Watertown, MA)', 'https://www.watertown-ma.gov/pequossette-summer-recreation-program', 'https://www.rec.us/organizations/watertown?activityIDs=aaaae974-8534-41aa-9a33-0638f464f216', 'Recreation@watertown-ma.gov', '617-972-6494', '123 Lowell Avenue', 'Watertown', 'MA', '02472', 'Boston, MA', 'day', NULL, NULL, ARRAY['Field trips (Franklin Park Zoo, Canobie Lake Park, Museum of Science, Urban Air/APEX)','Color Wars','Camp Cup','Talent show','Family cookout']::text[], NULL, NULL, NULL, 0, 8, 'A city-run summer day camp for children entering kindergarten through 8th grade, held at Lowell Elementary School. Campers are grouped by grade, and the summer includes weekly field trips and special events such as Color Wars.', NULL, NULL, 200, 295, 250, 'week', TRUE, NULL, NULL, NULL, 'If you cancel more than 7 days before a session starts, you get a refund or household credit minus a cancellation fee per child, per week: $75 for residents, $88.50 for non-residents. If you cancel 7 days or less before the start, or after the session begins, there is no refund unless there is a documented medical withdrawal.', NULL, NULL, NULL, NULL, 2026, '06ab0a65-edf7-5991-9493-815aa826bd26', 'pequossette-summer-recreation-program-watertown', ST_GeogFromText('SRID=4326;POINT(-71.1828 42.3709)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.census.gov/geographies/reference-files/time-series/geo/relationship-files.2020.html','https://www.watertown-ma.gov/asset/efaac5a5-0d20-4235-85bc-79db6ddf0fc5','https://www.watertown-ma.gov/pequossette-summer-recreation-program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Running Brook Camps Day Camp', 'Chapel Hill - Chauncy Hall School', 'https://www.runningbrook.org/day-camp/day-camp-ps-grade-6', 'https://runningbrook.campintouch.com/ui/forms/application/camper/App', 'runningbrookcamp@chch.org', '781-314-0994', '785 Beaver St.', 'Waltham', 'MA', '02452', 'Boston, MA', 'day', ARRAY['arts','sports','STEM','nature','performing_arts']::text[], NULL, ARRAY['Arts & Crafts','Camp Games','Core Value Challenge','Drama','Gym Games','Music','Nature','Yoga','Archery','Challenge Course','Creative Movement','Creation Station','STEM','Electives']::text[], NULL, NULL, NULL, NULL, 6, 'Co-ed day camp at Chapel Hill-Chauncy Hall School in Waltham for children from age 3.5 through completed 6th grade, run in four two-week sessions from June 28 to August 20, 2027. Activities include arts and crafts, drama, gym games, and nature, with archery, a challenge course, and STEM for older campers. Snack and lunch are provided.', NULL, NULL, 1795, 1845, NULL, 'session', TRUE, TRUE, TRUE, TRUE, 'A $50 registration fee per child and a $300 deposit per two-week session are due at registration; full payment and forms are due March 31, 2027. Until March 17, 2027 (Commitment Day) one session can be dropped for an account credit; dropping more is allowed only if there is a waitlist, otherwise the full balance is owed.', NULL, NULL, TRUE, 'https://www.runningbrook.org/who-we-are/accreditation', 2027, '1f03be5e-6d27-5161-859f-51cc2e1dfa78', 'running-brook-camps-day-camp-waltham', ST_GeogFromText('SRID=4326;POINT(-71.2356 42.3765)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.runningbrook.org/day-camp/day-camp-ps-grade-6','https://www.runningbrook.org/financial-aid','https://www.runningbrook.org/how-to-register','https://www.runningbrook.org/tuition-information','https://www.runningbrook.org/who-we-are/accreditation']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Arts & Music', 'Community Music Center of Boston', 'https://cmcb.org/programs/summerarts-music/', 'https://cmcb.asapconnected.com/#CourseGroupID=55655', 'registration@cmcb.org', '617-482-7494 ext. 54', '34 Warren Ave.', 'Boston', 'MA', '02116', 'Boston, MA', 'day', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Music','Musical instruments','Performance','Composing','Songwriting','Arts','Concert']::text[], NULL, 5, 11, NULL, NULL, 'A full-day music and arts program in Boston for ages 5–11. It runs Monday–Friday, 9am–5pm, in four one-week sessions in July. Each week follows a different musical theme, and families can sign up for one week or all four.', NULL, NULL, 162.5, 650, 650, 'week', NULL, NULL, NULL, TRUE, 'All participants pay a one-time $50 registration fee that cannot be refunded. The page does not give refund terms for tuition.', NULL, NULL, NULL, NULL, 2026, 'd5c81990-a761-54d4-92e7-1a2fe5d84f05', 'summer-arts-and-music-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://cmcb.org/contact-us/','https://cmcb.org/programs/summerarts-music/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Arts at Derby Academy', 'Derby Academy', 'https://www.derbyacademy.org/summer2026/programs-and-tuition/summer-arts', 'http://derbyacademysummer.campbrainregistration.com/', 'summer@derbyacademy.org', '781-749-0746', '56 Burditt Avenue', 'Hingham', 'MA', '02043', 'Boston, MA', 'specialty', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['Acting/drama','Musical theater','Tech theater (lighting, sound, sets, props)','Dance','Visual arts','Culinary arts/baking','Float building']::text[], NULL, 8, 15, NULL, NULL, 'Half-day (9:00 AM–12:00 PM) arts camps for ages 8–15 at Derby Academy in Hingham, covering theater, tech theater, visual arts, culinary arts and dance, in one- to three-week sessions. Each session ends with a showcase or gallery. An Extended Day option runs to 4:00 PM and includes lunch.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '76231546-08e8-56c6-8c2f-400005de19e5', 'summer-arts-at-derby-academy-hingham', ST_GeogFromText('SRID=4326;POINT(-70.8898 42.2418)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.derbyacademy.org/summer2026/programs-and-tuition/summer-arts','https://www.derbyacademy.org/summer2026/tuition-and-financial-aid']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer at Inly', 'Inly School', 'https://summeratinly.com/', 'https://www.homeroom.com/sites/inly-school-scituate/camp/summer-at-inly-2026#Summer-at-Inly-2026', NULL, '(781) 545-5544', '46 Watch Hill Drive', 'Scituate', 'MA', '02066', 'Boston, MA', 'day', ARRAY['sports','arts','performing_arts','STEM']::text[], NULL, ARRAY['Art & creative projects','Science exploration','Sports & team games','Nature adventures','Archery & water games','Climbing tower & adventure course']::text[], NULL, 3, 14, NULL, NULL, 'Summer day camp on the Inly School campus in Scituate, MA, offering full-day and extended-day camps, specialty camps and preschool programs for ages 3 to 14. Runs for ten weeks from mid-June to late August.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, 'A $100 non-refundable deposit is due per camper, per week at registration. If a waitlist spot opens, the camper is enrolled and charged the deposit, and the family has 24 hours to cancel for a full refund.', 'The site mentions an on-site nurse and an ''Allergy Aware'' camp. A parent testimonial says nursing staff looked after a child''s extra medical needs. No formal special-needs program is described.', NULL, NULL, NULL, 2026, '58bd9ceb-dc5d-52d7-a6f3-a281a6d68b8a', 'summer-at-inly-scituate', ST_GeogFromText('SRID=4326;POINT(-70.7259 42.1959)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://inlyschool.myschoolapp.com/ftpimages/47/download/download_11212369.pdf','https://summeratinly.com/','https://summeratinly.com/extended-day/','https://summeratinly.com/inly-day-camp/','https://summeratinly.com/register/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer at Park', 'The Park School', 'https://www.summeratpark.org/', 'https://summeratpark.campbrainregistration.com', 'summerprograms@parkschool.org', '617-274-6025', '171 Goddard Avenue', 'Brookline', 'MA', '02445', 'Boston, MA', 'day', ARRAY['arts','STEM','sports','nature']::text[], NULL, ARRAY['Art','Science','Cooking','Leadership','Outdoor adventures','Sports','General day camp','Off-campus trips around Boston']::text[], NULL, 4, 15, 0, 10, 'An ACA-accredited day camp for kids PreK through 10th grade (ages 4-15) on The Park School''s 34-acre campus in Brookline, with over 35 general and specialty programs including art, science, cooking, leadership, outdoor adventures, sports and general day camps. It offers one- and two-week sessions, extended day and a shuttle bus from Brookline Village, and some programs visit places in and around Boston.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, NULL, TRUE, NULL, NULL, NULL, TRUE, 'https://www.summeratpark.org/', 2027, '7cb54608-0b60-5864-8133-10633f38a310', 'summer-at-park-brookline', ST_GeogFromText('SRID=4326;POINT(-71.1212 42.3318)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.parkschool.org/community/summer-programs','https://www.summeratpark.org/','https://www.summeratpark.org/extended-day','https://www.summeratpark.org/financial-assistance-application','https://www.summeratpark.org/transportation']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer at Shady Hill School', 'Shady Hill School', 'https://www.shs.org/shs-life/auxiliary-and-summer-programs/summer-programs', 'https://summeratshady.campbrainregistration.com/', 'alida.salins@shs.org', '617.520.5260', '178 Coolidge Hill', 'Cambridge', 'MA', '02138', 'Boston, MA', 'day', ARRAY['arts','STEM','sports']::text[], NULL, ARRAY['Arts','STEM','Physical education','Recess on 11-acre campus','Bounce house','Water slide inflatables','Optional water play','Camp songs','Active movement games','Activity choices','Optional field trips','Leaders-in-Training program (rising grades VIII-IX)']::text[], NULL, 4, 14, NULL, 7, 'A six-week summer day camp at Shady Hill School in Cambridge for children ages 4 to 14, open to the public. Children are grouped by grade and each session has a theme, with arts, STEM and PE activities designed by Shady Hill teachers.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, NULL, NULL, 'Refunds minus deposits are available until May 15, 2026; after that tuition is not refundable, with case-by-case exceptions by the Director of Auxiliary Programs. No refunds for missed days, or for a child withdrawn for safety reasons.', 'Families are invited to call the Auxiliary Programs Office before registering to discuss a child''s needs; the program says it is not a medical or therapeutic program. Children must be toilet trained.', 'No swimming: the school has no swimming facilities. Campers have daily water play on an inflatable water slide and other water activities.', NULL, NULL, 2026, '7081aafd-3682-5876-bf95-9a47664ee70c', 'summer-at-shady-hill-school-cambridge', ST_GeogFromText('SRID=4326;POINT(-71.1097 42.3736)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.shs.org/shs-life/auxiliary-and-summer-programs/summer-programs','https://www.shs.org/shs-life/auxiliary-and-summer-programs/summer-programs/faq','https://www.shs.org/shs-life/auxiliary-and-summer-programs/summer-programs/registration','https://www.shs.org/shs-life/auxiliary-and-summer-programs/summer-programs/schedule-26']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Fenn', 'The Fenn School', 'https://www.summerfenn.org', 'https://summerfenn.campbrainregistration.com/', 'CampOffice@fenn.org', '978-318-3614', '516 Monument Street', 'Concord', 'MA', '01742', 'Boston, MA', 'day', ARRAY['general','outdoor','adventure']::text[], NULL, ARRAY['Electives','Outdoor adventure (Expedition Camps)','Off-site day trips (Day Tripper Camps)','Specialty camps','Climbing wall','After-camp swim lessons','Red Cross Lifeguard and WSI certification']::text[], NULL, 4, NULL, 0, 10, 'Summer Fenn is a day camp in Concord, MA. Its Base Camp is a general day camp for children entering grades K-10, and SF Junior is a full-day program for 4- and 5-year-olds. It also runs specialty, outdoor expedition and off-site day-trip camps. Camp runs 9:00am-3:45pm, mostly in two-week sessions.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, TRUE, TRUE, TRUE, '2026 policy: tuition is fully refundable until March 31, less a $100 per week, per child deposit; after March 31 a 25% refund until 2 weeks before the program starts; no refunds within 2 weeks of the start. Cancellations must be emailed in writing.', NULL, 'The Fenn School campus has a 30'' x 75'' heated swimming pool. Swim lessons are offered after camp at an extra charge, and Red Cross Lifeguard and Water Safety Instructor (WSI) certification courses are also offered.', NULL, NULL, 2027, '087bf7f9-b5df-591f-8270-ec6e6e089c17', 'summer-fenn-concord', ST_GeogFromText('SRID=4326;POINT(-71.3489 42.4604)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.summerfenn.org','https://www.summerfenn.org/camp-rates','https://www.summerfenn.org/facilities','https://www.summerfenn.org/transportation']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Fun Program', 'Medford Community Schools (Medford Public Schools)', 'https://www.mps02155.org/extracurricular/medford-community-schools/summer-fun-program', NULL, 'apetrelis@medford.k12.ma.us', NULL, '37 Hicks Avenue (Missituk School)', 'Medford', 'MA', '02155', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['sports','arts','swimming']::text[], ARRAY['Sports','Games','Arts & Crafts','Movies','Swimming (outdoor pool)','DJ dance party (Fridays)','Basketball','Indoor gym','In-house field trips']::text[], NULL, NULL, NULL, 1, 8, 'A summer day program run by Medford Community Schools for kids going into Grades 1–8. It is held at the Missituk School and includes sports, games, arts and crafts, movies and swimming. Staff are Medford Public Schools teachers plus college and high school students.', NULL, NULL, 250, 300, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'For IEPs, 504 plans or behavior plans, contact Director Anthony Petrelis (apetrelis@medford.k12.ma.us) to arrange accommodations. Children not enrolled in Medford Public Schools must send a recent physical exam and immunization records to District Health Services (jsilva@medford.k12.ma.us) at least 3 business days before their first day.', 'There is an outdoor swimming pool on site. Campers bring a bathing suit, a towel and sandals (for the pool only). Lifeguard and swim-test details are not stated.', NULL, NULL, 2026, '71f7fec1-8b3f-572b-84b6-41a1af66ee7e', 'summer-fun-program-medford', ST_GeogFromText('SRID=4326;POINT(-71.1062 42.4184)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=Missituk+School%2C+37+Hicks+Avenue&city=Medford&state=MA&benchmark=Public_AR_Current&format=json','https://www.mps02155.org/extracurricular/medford-community-schools/summer-fun-program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Horsemanship Program', 'Dana Hall School (Karen Stives ''68 Equestrian Center)', 'https://www.danahall.org/community-programs/equestrian-summer-program', NULL, NULL, '781.235.3010', '45 Dana Road', 'Wellesley', 'MA', '02482', 'Boston, MA', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Horseback riding (hunt-seat equitation)','Unmounted horsemanship lessons','Grooming and tacking','Barn chores','Horse-related arts and crafts','Gymkhana mounted games','Final Friday exhibition']::text[], NULL, 7, 15, NULL, NULL, 'A half-day horseback riding camp at Dana Hall''s equestrian center, focused on hunt-seat equitation, safety and horse care. Riders of all levels are welcome, including first-timers. Camp runs Monday to Friday, 8:30 a.m. to 1 p.m.', NULL, NULL, 800, 1600, 800, 'week', NULL, NULL, FALSE, NULL, 'A $200 nonrefundable deposit is due February 1. The remaining balance is due April 15 and is also nonrefundable.', NULL, NULL, NULL, NULL, 2026, '5d0fe3a7-d56d-5065-99b5-c1a3528b59be', 'summer-horsemanship-program-wellesley', ST_GeogFromText('SRID=4326;POINT(-71.2923 42.2968)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.danahall.org/community-programs/equestrian-summer-program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Program for Children', 'The Eliot School of Fine & Applied Arts', 'https://eliotschool.org/summer-program-for-children', 'https://eliotschool.org/summer-program-for-children', 'vacationprograms@eliotschool.org', '617-553-1387', '24 Eliot Street (Jamaica Plain)', 'Boston', 'MA', '02130', 'Boston, MA', 'day', ARRAY['arts']::text[], NULL, ARRAY['Woodworking','Fiber arts','Sewing','Mixed media','Visual arts (Art Zone)','Outdoor free play','Friday Student Showcase']::text[], NULL, 6, 12, NULL, NULL, 'A weekly arts day camp for ages 6-12 at the Eliot School Schoolhouse in Jamaica Plain, Boston. Children take visual arts, mixed media, sewing and fiber arts, and woodworking classes in half-day or full-day weeks, in classes capped at 12, with lunch and play outdoors in the Schoolyard and a Friday Student Showcase.', NULL, NULL, 290, 585, 585, 'week', TRUE, NULL, NULL, TRUE, 'Withdraw by contacting the Education & Engagement Coordinator. Full refund through May 5, 2027, 50% refund through June 2, 2027, no refunds from June 3. A $20 processing fee applies to all refunds. Registrations made within two weeks of the start date, or after June 3, get no refund. Exceptions may be arranged for serious illness, major injury, or a death in the family.', NULL, NULL, NULL, NULL, 2027, 'a25c277d-9e43-5e53-91fa-0fac8ffa8fd6', 'summer-program-for-children-boston', ST_GeogFromText('SRID=4326;POINT(-71.0589 42.3601)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://eliotschool.org/about/contact-us','https://eliotschool.org/summer-program-for-children']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Shore Day Camp', 'Shore Country Day School', 'https://www.shoreschool.org/summer-shore/day-camp', 'https://app.enrollsy.com/r/q3J4p1xW2ND6MUEdVaZQZ', 'jnorris@shoreschool.org', '(978) 927-1700, ext. 256', '545 Cabot Street', 'Beverly', 'MA', '01915', 'Boston, MA', 'day', ARRAY['general']::text[], ARRAY['STEM','arts','sports','performing_arts']::text[], ARRAY['STEM activities','arts and crafts','rock climbing','theater','sports/outdoor games','water activities','music','Spanish','writing','reading']::text[], NULL, 3, 12, NULL, NULL, 'A weekly day camp at Shore Country Day School in Beverly, MA, for ages 3-12 and open to the public. Activities include STEM, arts and crafts, rock climbing, theater, sports, water games, music and Spanish. Ages 3-4 attend a separate program led by a Pre-K teacher.', NULL, NULL, 275, 585, 550, 'week', TRUE, NULL, FALSE, NULL, 'There is a $100 fee for any cancellation. No refunds after May 31, 2026.', 'Children ages 3-4 must be independent in the bathroom. Nap time is built into the ages 3-4 schedule.', 'Monday, Wednesday and Friday are Water Days with water games and activities on the school''s fields. Campers bring a bathing suit, water shoes and a towel. No pool or swim instruction is mentioned.', NULL, NULL, 2026, '974f6203-48cc-5eb1-b25d-3c54dbf1962b', 'summer-shore-day-camp-beverly', ST_GeogFromText('SRID=4326;POINT(-70.88 42.5584)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.shoreschool.org/summer-shore/day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer @ SSC (South Shore Conservatory Summer Programs)', 'South Shore Conservatory', 'https://summer.sscmusic.org/', NULL, NULL, '781-749-7565', 'One Conservatory Drive', 'Hingham', 'MA', '02043', 'Boston, MA', 'specialty', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Arts-integrated themed weeks (Conservatory Kids)','Cooking and kitchen science','Outdoor nature and STEAM projects','Dance (ballet, hip hop, jazz, creative movement)','Piano','Voice/song','Rock band','Art','Musical theater']::text[], NULL, 3, 18, NULL, NULL, 'South Shore Conservatory''s summer arts programs at its Hingham campus (and Duxbury for Summer Dance): week-long morning and full-day camps for young children (Conservatory Kids, Outdoor Explorers, Cooking With Creativity, Dance Discovery) and music weeks for older students (Summer Piano, Summer of Song, Rock Band Jam), each with a showcase or concert at the end of the week.', NULL, NULL, 350, 625, NULL, 'session', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'd9c9800b-41c8-5f8f-9e36-3c68df1034b9', 'summer-ssc-south-shore-conservatory-summer-programs', ST_GeogFromText('SRID=4326;POINT(-70.8898 42.2418)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://sscmusic.org/tuition-assistance/','https://summer.sscmusic.org/','https://summer.sscmusic.org/conservatory-kids/','https://summer.sscmusic.org/summer-dance/','https://summer.sscmusic.org/summer-piano/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Tennis Academy (Ages 11-18)', 'Weymouth Club', 'https://www.weymouthclub.com/camps/tennis-academy-ages-11-18/', NULL, 'TFACamp@weymouthclub.com', '781-337-4600', '75 Finnell Drive', 'Weymouth', 'MA', '02188', 'Boston, MA', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Tennis live ball hitting','Stroke and game drills','Match play singles and doubles','Weekly ladder','Fitness for tennis','Mental peak performance training','Strategy and tactics','Nutrition and hydration','Tennis games','Free swim (elective)']::text[], NULL, 11, 18, NULL, NULL, 'A tennis day camp for ages 11-18 at the Weymouth Club, run by USPTR/USPTA pros, from 9:00 a.m. to 3:00 p.m. Each day includes live-ball hitting, drills, match play with a weekly ladder, fitness, and an elective such as tennis games or free swim.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, NULL, NULL, 'Free swim is offered as one of the 2:15-3:00 electives. The page does not say anything about swim testing or lifeguards.', NULL, NULL, 2027, '449d2fe7-5cd0-5941-ae0f-f5f223773a47', 'tennis-academy-ages-11-18-weymouth', ST_GeogFromText('SRID=4326;POINT(-70.9395 42.2209)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.weymouthclub.com/camps/tennis-academy-ages-11-18/','https://www.weymouthclub.com/camps/tfa-camp-traditional-track-ages-6-13/']::text[], '2026-11-13', '2026-11-13', TRUE),
('TFA Camp: Traditional Track', 'Weymouth Club', 'https://www.weymouthclub.com/camps/tfa-camp-traditional-track-ages-6-13/', NULL, 'tfacamp@weymouthclub.com', '781-337-4600', '75 Finnell Drive', 'Weymouth', 'MA', '02188', 'Boston, MA', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['Tennis lessons','Tennis/ladder matches','Fitness and gym games','Arts and crafts','Swimming lessons','Free swim','Weekly themes','Daily awards']::text[], NULL, 6, 13, NULL, NULL, 'A day camp at the Weymouth Club for ages 6-13, with campers grouped by age. Each day includes tennis lessons, fitness and gym games, arts and crafts, and free swim, with swim lessons twice a week. It runs every summer week and on many school-vacation days.', NULL, NULL, 375, 569, 569, 'week', TRUE, NULL, FALSE, NULL, 'There are no refunds. All withdrawals or cancellations must be emailed to TFACamp@weymouthclub.com.', NULL, 'Indoor club pool (Aquatics Center). Swim lessons twice a week plus daily free swim. Bring a bathing suit and towel every day.', NULL, NULL, 2027, '08e3fc08-f4bb-5e71-8ad4-e897745e0c0f', 'tfa-camp-traditional-track-weymouth', ST_GeogFromText('SRID=4326;POINT(-70.9395 42.2209)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.weymouthclub.com/camps/tfa-camp-traditional-track-ages-6-13/']::text[], '2026-11-13', '2026-11-13', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('Warrior Surf Camp', 'Levitate', 'https://levitatecamps.com/warrior-surf-camp/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=1560&campCode=DD3', 'info@levitatecamps.com', NULL, '325 Standish St', 'Marshfield', 'MA', '02050', 'Boston, MA', 'specialty', ARRAY['sports']::text[], ARRAY['outdoor','swimming']::text[], ARRAY['Surfing','Beach games','Beach cleanups','Ocean activities']::text[], NULL, 7, 12, NULL, NULL, 'A week-long surf day camp at Rexhame Beach in Marshfield, MA, for ages 7–12. Campers surf every day when conditions allow and do beach games and beach cleanups while waiting for waves. Sessions run 4 hours, and the start time depends on the tide.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The 10% deposit is non-refundable. Cancel 60 or more days before the session starts for a 90% refund, or 30–59 days before for a 50% refund. There are no refunds within 30 days of the session, during it, or for missed days. Everything is refunded if the camp cancels for public health reasons. You can switch sessions free of charge if space allows.', NULL, 'Campers surf daily in the ocean at Rexhame Beach, staying out as long as conditions allow. Session times are set by the tide.', NULL, NULL, 2027, 'a01a72be-64fe-5123-9d3b-f95d7f35ee73', 'warrior-surf-camp-marshfield', ST_GeogFromText('SRID=4326;POINT(-70.7056 42.0918)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://levitatecamps.com/warrior-surf-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Waterman''s Camp', 'Levitate', 'https://levitatecamps.com/watermans-camp/', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=1560&campCode=DD3', 'info@levitatecamps.com', NULL, '325 Standish St', 'Marshfield', 'MA', '02050', 'Boston, MA', 'specialty', ARRAY['sports','nature']::text[], NULL, ARRAY['Surfing','Paddleboarding','Ocean navigation / water safety skills']::text[], NULL, 13, 15, NULL, NULL, 'A small-group ocean skills program for ages 13–15 at Rexhame Beach in Marshfield. Campers learn to surf, paddleboard and handle tricky conditions, 4 hours a day for a week, at tide-dependent times.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '10% deposit is non-refundable. Cancel 60+ days before start for a 90% refund; 30–59 days before for 50%; no refund within 30 days or during the session, and none for missed days, late arrivals or early pickups. Full refund if camp is canceled for public health reasons. You can switch sessions for free if space allows.', NULL, 'Held on the ocean at Rexhame Beach. Campers surf and paddleboard, and session times change with the tide. Swim ability requirements and lifeguard staffing are not stated.', NULL, NULL, 2027, '6fd7f9fd-a91d-5697-b2c5-eb7f92020522', 'waterman-s-camp-marshfield', ST_GeogFromText('SRID=4326;POINT(-70.7056 42.0918)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://levitatecamps.com/watermans-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wellesley Youth Commission Summer Exploration Programs', 'Wellesley Youth Commission', 'https://wellesleyma.gov/525/Summer-Programs', 'https://forms.gle/RcsaKe4or3PCWBop9', NULL, '781-431-1019', '525 Washington Street', 'Wellesley', 'MA', '02482', 'Boston, MA', 'specialty', ARRAY['nature','STEM','academic']::text[], NULL, ARRAY['fire rescue training','knot tying','water rescue','fishing','wilderness survival skills','drone experimentation','kayaking','swimming','shoreline restoration','crime scene investigation','field trips']::text[], NULL, NULL, NULL, 6, 8, 'Free week-long day programs run by the Wellesley Youth Commission for Wellesley resident youth and Wellesley Public Schools students entering grades 6–8. Each is hosted by a town department: the Fire Department (Fire Rescuers), the Natural Resources Commission and Wellesley Conservation Council (Eco Summer), or the Police Department (Youth Academy). Each has 13 spots, filled by lottery; campers may attend only one program per summer.', NULL, NULL, 0, 0, 0, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'Eco Summer Program includes kayaking and swimming. Participants must pass a swim test to take part in water activities.', NULL, NULL, 2026, '8e20d941-06f5-5cc1-8956-68cc2de804aa', 'wellesley-youth-commission-summer-exploration-programs-wellesley', ST_GeogFromText('SRID=4326;POINT(-71.2923 42.2968)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://wellesleyma.gov/525/Summer-Programs']::text[], '2026-11-13', '2026-11-13', TRUE),
('Y STEAM Summer Program', 'MetroWest YMCA', 'https://www.metrowestymca.org/camp/y-steam-camp', 'https://ymcametrowest.sgasoftware.com/Sales/Product?MemberID=0&CurrentFamilyID=0&ProductID=&UnitID=&DT=GroupedList&DS=0&CheckEligibility=True&Age=-1&DL=10&Gender=B&BranchID=310&ProductTypeID=600&IncludeWaitList=True&StartDateFrom=&StartDateTo=&BeginTime=&EndTime=', 'zsullivan@metrowestymca.org', '(508) 435-9345', '90 Oak Street', 'Natick', 'MA', '01760', 'Boston, MA', 'specialty', ARRAY['STEM','arts']::text[], NULL, ARRAY['Science experiments','Engineering challenges','LEGO SPIKE','Turing Tumbles','Coding','Hydraulics','Art','Swimming','Swim lessons','Sports & games','Songs','Family Fun Nights']::text[], NULL, NULL, NULL, 1, 6, 'A STEAM-focused day program for children entering grades 1-6, held at East School in Natick. Days run 9:00 AM to 4:00 PM and include hands-on science, technology, engineering, art and math projects, plus daily swim, sports and games.', NULL, NULL, 415, 519, 519, 'week', TRUE, NULL, FALSE, TRUE, 'A $50 per week, per child deposit is due at registration and is not refundable. Deposits can be moved to other camp programs before April 1 but not after. The cancellation and transfer deadline is May 31; after that there are no refunds, credits or transfers. Extended care is paid in full at registration. A credit or refund (minus the deposit) may be given for an illness or injury lasting 3 or more days if you send a doctor''s note before the session ends. All changes must be made in writing by email.', 'The MetroWest YMCA tries to make its programs accessible and asks families to share any needs in advance. It says it is not a therapeutic or special needs organization. Director of Inclusion: Laina Abolfazli, (508) 876-6094, labolfazli@metrowestymca.org. Children with chronic medical conditions or allergies need an Individual Health Care Plan.', 'Campers travel to Clearbrook Pool to swim each day. Every child takes a swim test on the first day of each session. Red-neckband swimmers must wear a Coast Guard-approved flotation device during open swim. YMCA swim lessons and recreational swim are included.', NULL, NULL, 2026, '11bbb243-cae3-58d9-896b-e0825af32641', 'y-steam-summer-program-natick', ST_GeogFromText('SRID=4326;POINT(-71.3495 42.2834)'), FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.metrowestymca.org/camp/y-steam-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Aim High Academy Summer Day Camps', 'Aim High Academy', 'https://www.aimhighacademy.com/camps-summer.aspx', NULL, 'info@aimhighacademy.com', '(401) 886-7827', '3355 South County Trail', 'East Greenwich', 'RI', '02818', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['arts & crafts','games','gymnastics','adventure play','water play']::text[], NULL, 3, 10, 1, 5, 'Summer day camps at Aim High Academy in East Greenwich for ages 3 to 10: Camp Little Star for preschoolers (3 to 5) and Camp Rising Star for rising 1st to 5th graders. Weekly themes mix indoor and outdoor activities, including arts & crafts, games, gymnastics, adventure play and water play, with a theme-based Fun Friday and pizza lunch each Friday.', 'both', NULL, 100, 375, 375, 'week', TRUE, NULL, FALSE, NULL, '$150 non-refundable deposit per session at registration; balances due May 1 (June camps), June 1 (July camps) and July 1 (August camps). No refunds or credits without a medical note; $25 fee to change the schedule. $25 registration fee for non-members.', NULL, 'Water play only: preschoolers wear bathing suits daily; school-age campers bring a bathing suit for water play (water slides on Fun Fridays).', NULL, NULL, 2026, '64fc4d3b-5f59-54ff-9302-e02d79875eef', 'aim-high-academy-summer-day-camps-east-greenwich', ST_GeogFromText('SRID=4326;POINT(-71.4601 41.6601)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.aimhighacademy.com/camps-summer.aspx','https://www.aimhighacademy.com/camps.aspx','https://www.aimhighacademy.com/docs/2026-SummerDayCamp-LittleStarFlyer.pdf','https://www.aimhighacademy.com/docs/2026-SummerDayCamp-RisingStarFlyer.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('ALM Sports Summer Camp Swansea', 'ALM Sports LLC', 'https://almsports.com/pages/summer-camp-swansea', 'https://www.emailmeform.com/builder/form/EKl5C77j190AWyhdMibH', 'admin@almsports.com', '1-800-388-7962', '207 Swansea Mall Dr', 'Swansea', 'MA', '02777', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['Trampoline jumping','Board games','Enrichment','Sports','Field trips','Swimming / splash pad (optional)','Movies']::text[], NULL, 5, 15, NULL, NULL, 'A weekday summer day camp for boys and girls aged 5-15, run by ALM Sports at the Get Air Trampoline Park in Swansea, MA. Days include jumping sessions, enrichment, sports and weekly field trips, with full-day (8am-6pm) and half-day options.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'All fees are non-refundable unless ALM does not provide the service. There is a one-time $50 family registration fee, which is also non-refundable.', 'Page says the camp is for "All Abilities". It gives no details on what support is available.', 'Swimming / splash pad is offered every week and is optional. The page doesn''t say where it happens or how it is supervised.', NULL, NULL, 2026, '74fd75ad-4752-5232-a84c-6ebad3f16ce0', 'alm-sports-summer-camp-swansea-swansea', ST_GeogFromText('SRID=4326;POINT(-71.1898 41.7484)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://almsports.com/pages/summer-camp-swansea']::text[], '2026-11-13', '2026-11-13', TRUE),
('Arnold''s Gymnastics Academy Summer Camp', 'Arnold''s Gymnastics Academy', 'https://www.arnoldsgymnastics.com/camps', 'https://www.arnoldsgymnastics.com/portal/summer-camp', 'agaoffice@arnoldsgymnastics.com', '(508) 339-6843', '249 Oakland St', 'Mansfield', 'MA', '02048', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['Gymnastics instruction','Ninja instruction','Obstacle courses','Outdoor games','Crafts']::text[], NULL, 3, NULL, NULL, NULL, 'A summer day camp at a gymnastics gym in Mansfield, MA, with half-day (ages 3+) and full-day (ages 4+) options. Each day includes an obstacle course, gymnastics and ninja instruction, snack, crafts and games, and the afternoon is mostly athletic instruction.', NULL, NULL, 215, 395, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'f9e366c6-3668-5905-8109-d8a23a8182b1', 'arnold-s-gymnastics-academy-summer-camp-mansfield', ST_GeogFromText('SRID=4326;POINT(-71.219 42.0334)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.arnoldsgymnastics.com/camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Artists'' Exchange Summer Camps', 'Gateways to Change, Inc.', 'https://www.artists-exchange.org/summer-camps', NULL, 'info@artists-exchange.org', '(401) 490-9475', '50 Rolfe Square', 'Cranston', 'RI', '02910', 'Providence, RI', 'day', ARRAY['arts','performing_arts','technology']::text[], NULL, ARRAY['drawing','painting','3D construction','clay hand building','wheel throwing','sculpting','pottery firing','stop-motion animation','claymation','theater','singing','dance']::text[], NULL, 6, 14, NULL, NULL, 'Weekly arts day camps (9am-3pm) in Cranston, RI, run by a non-profit community arts center. Options include art, little art, ceramics/clay, digital media/stop-motion animation, and theater & dance camps for ages 6-14.', NULL, NULL, 292, 365, 365, 'week', TRUE, NULL, NULL, TRUE, 'Camps canceled by Artists'' Exchange are fully refunded; single days lost to weather or COVID quarantine are credited. Families who cancel at least two weeks before camp get a refund minus a $50 non-refundable fee. The fee is waived if they transfer to another camp or keep the money as a credit. Cancellations made less than two weeks before camp are not refunded.', NULL, NULL, NULL, NULL, 2026, '16c7a0ab-8242-503d-adfc-1ee70ead6338', 'artists-exchange-summer-camps-cranston', ST_GeogFromText('SRID=4326;POINT(-71.4373 41.7798)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.artists-exchange.org/summer-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Arts Camps at Camp Finberg (Theater In The Woods & Art Camp)', 'Attleboro Norton YMCA', 'https://www.attleboroymca.org/art-camp', NULL, 'campadmin@attleboroymca.org', '(508) 222-7292', '295 West Main Street', 'Norton', 'MA', '02766', 'Providence, RI', 'specialty', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['drama games','theater production','painting','drawing','collage','nature-inspired art']::text[], NULL, NULL, NULL, 2, 5, 'Week-long arts camps at the YMCA''s Camp Finberg for grades 2-5. Theater In The Woods uses drama games and ends with a production at the end of the week. Art Camp covers painting, drawing and collage, with nature worked into the art.', NULL, NULL, 300, 360, NULL, 'week', TRUE, TRUE, NULL, TRUE, 'Specialty camps take a $100 non-refundable deposit per week at registration. If you cancel a week, the deposit goes toward any other camp balance or is forfeited if there is none. Cancellations need two weeks'' notice, and after May 31 changes cost $25.', NULL, NULL, NULL, NULL, 2026, '7fa03a97-b1ac-5eb8-8cfa-8103a04ebe66', 'arts-camps-at-camp-finberg-theater-in-the-woods-and-art-camp-norton', ST_GeogFromText('SRID=4326;POINT(-71.187 41.9668)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.attleboroymca.org/art-camp','https://www.attleboroymca.org/camps/camp-finberg','https://www.attleboroymca.org/sites/default/files/2025-12/2026-Camp-Finberg-Payments-and-Policies.pdf','https://www.attleboroymca.org/sites/default/files/2026-04/YCampGuide.2026.FINAL_.v2.pdf%20%28Booklet%20%28US%20Letter%29%29%20%281%29.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Brittany Harris Gymnastics Camps', 'Brown University Women''s Gymnastics coaching staff', 'https://www.brittanyharrisgymnasticscamps.com/', 'https://register.ryzer.com/camp.cfm?id=327444', 'brittanyharris.ent@gmail.com', NULL, 'Ocean State School of Gymnastics, 3 New England Way', 'Lincoln', 'RI', '02865', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Gymnastics']::text[], 'girls', 7, 18, NULL, NULL, 'Two-day commuter gymnastics camps for girls ages 7 to 18, from beginning levels to elite, hosted by the Brown University Women''s Gymnastics coaching staff with current Brown gymnasts, held at Ocean State School of Gymnastics in Lincoln, RI.', 'indoor', NULL, 323, 419, NULL, 'session', NULL, NULL, FALSE, NULL, 'No refund unless Registration Protection is bought at registration; $70 administrative fee on all cancellations; no cancellation refunds within 7 days of camp.', NULL, NULL, NULL, NULL, 2026, 'a66a17b8-b787-5b71-93ff-3ffb65fa9311', 'brittany-harris-gymnastics-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.brittanyharrisgymnasticscamps.com/','https://www.brittanyharrisgymnasticscamps.com/august-bears-gymnastics-summer.cfm','https://www.brittanyharrisgymnasticscamps.com/july-bears-gymnastics-summer.cfm']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Agawam', 'Agawam Hunt', 'https://www.agawamhunt.org/camp', 'https://www.agawamhunt.org/camp-registration', NULL, '401.434.0980', '15 Roger Williams Avenue', 'Rumford', 'RI', '02916', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['tennis','squash','pickleball','golf','swimming pool','crafts','karaoke','beaded jewelry making','wiffleball']::text[], NULL, NULL, NULL, 1, 6, 'A day camp at the Agawam Hunt club for grades 1–6, running 9:00 a.m. to 3:00 p.m. Each day campers spend an hour each at the racquets courts (tennis, squash, pickleball), the golf course, the pool and the lawn, and lunch is included.', NULL, NULL, 290, 465, 465, 'week', TRUE, NULL, TRUE, NULL, NULL, NULL, 'The club has a pool, and campers get pool time and pool games each day. The page does not mention swim instruction, swim tests or lifeguards.', NULL, NULL, 2026, '11c844a0-2358-5e53-b39a-11534bced19c', 'camp-agawam-rumford', ST_GeogFromText('SRID=4326;POINT(-71.3567 41.8445)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.agawamhunt.org/camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Finberg', 'Attleboro Norton YMCA', 'https://www.attleboroymca.org/camps/camp-finberg', NULL, 'campadmin@attleboroymca.org', '(508) 222-7292', '295 West Main Street', 'Norton', 'MA', '02766', 'Providence, RI', 'day', ARRAY['general','outdoor','sports']::text[], ARRAY['arts','STEM','swimming']::text[], ARRAY['recreational swim','splash pad','archery','ropes challenge course','STEM','arts','sports and active games','hikes and nature','theater','soccer','flag football','basketball']::text[], NULL, NULL, NULL, 2, 8, 'YMCA summer day camp in Norton, MA, with camp hours 8:30am-4:00pm and optional before care (from 7:00am) and after care (until 5:30pm). Families can register for 2, 3, or 5 days per week; specialty camps are 5-day only.', NULL, NULL, 285, 360, 345, 'week', TRUE, TRUE, NULL, TRUE, 'To cancel a week, notify the Camp Registrar at least two weeks ahead, before that week''s payment is drafted. After May 31 a $25 change fee applies to any change (weeks, camps, added care). Deposits move to other weeks. A $25 Camp Improvement Fee is non-refundable; Specialty Camps take a $100 non-refundable deposit.', 'Children with developmental and behavioral needs are integrated into regular groups of 10. No 1:1 support, but staff check in and give extra support; ABAs may accompany campers after a background check.', 'Outdoor eight-lane pool with a three-foot entry area and a zero-depth splash pad; recreational swim on most days, supervised by lifeguards and counselors, with a swim check before swimming without flotation or in deeper water. Express Swim Lessons cost extra.', NULL, NULL, 2026, '5702e8d2-398a-5243-af91-3f8d09646bef', 'camp-finberg-norton', ST_GeogFromText('SRID=4326;POINT(-71.187 41.9668)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.attleboroymca.org/camps/camp-finberg','https://www.attleboroymca.org/sites/default/files/2025-12/2026-Camp-Finberg-Payments-and-Policies.pdf','https://www.attleboroymca.org/sites/default/files/2026-04/YCampGuide.2026.FINAL_.v2.pdf%20%28Booklet%20%28US%20Letter%29%29%20%281%29.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Frederick Douglass', 'YMCA Southcoast', 'https://ymcasouthcoast.org/location/camp-frederick-douglass/', 'https://operations.daxko.com/online/2096/ProgramsV2/Home.mvc', 'kjackson-lee@ymcasc.org', '(508) 997-0734 x 127', '25 South Water Street', 'New Bedford', 'MA', '02740', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['sports','performing_arts','swimming']::text[], ARRAY['gym games','outdoor games','swimming','archery','drama','enrichment activities','field trips','museum visits','local history projects']::text[], NULL, NULL, NULL, NULL, NULL, 'A YMCA day camp at the New Bedford YMCA, open weekdays from 7:30 AM to 5:30 PM. Campers do gym and outdoor games, swimming, archery and drama, and learn about Frederick Douglass and his time in New Bedford through projects, field trips and museum visits.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, TRUE, '$50 non-refundable deposit per session per child at registration; tuition due in full 6/1 (Sessions A-C), 7/1 (D-F) and 8/1 (G-J). Withdrawal needs four weeks'' written notice for a refund less the deposit; refunds after camp starts only for illness or injury with a doctor''s note. $25 fee for approved session changes.', NULL, NULL, NULL, NULL, 2026, 'a4483d96-d455-565f-8f4e-5d0a75383ee3', 'camp-frederick-douglass-new-bedford', ST_GeogFromText('SRID=4326;POINT(-70.9379 41.6613)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://ymcasouthcoast.org/location/camp-frederick-douglass/','https://ymcasouthcoast.org/programs/child-care-camps/summer-day-camp/','https://ymcasouthcoast.org/wp-content/uploads/2026/04/2026_CampRegistration_Fill.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Jack', 'People Incorporated', 'https://peopleincfr.org/services/diabetes-association-inc/camp-jack/', 'https://campjack.funjoin.app/sign-in', NULL, '(508) 679-5233', '127 North Main Street', 'Assonet', 'MA', '02702', 'Providence, RI', 'day', ARRAY['special_needs','general']::text[], ARRAY['swimming','sports','arts','nature']::text[], ARRAY['Diabetes management education','Swimming (two outdoor pools)','Sports and athletic fields','Arts and crafts','Nature explorations','Archery','Team building','Theme weeks','Counselor in Training program (ages 14-15)']::text[], NULL, 5, 14, NULL, NULL, 'The Jack Rua Camp for Children with Diabetes: a day camp for kids with type 1 diabetes ages 5-14, their siblings and friends, held for six weeks in July and August at Camp Welch in Assonet, MA. Nurses are on site, and activities, snacks and meals are planned around diabetes management.', 'outdoor', NULL, 230, 230, 230, 'week', NULL, TRUE, FALSE, TRUE, NULL, 'For campers with type 1 diabetes, their siblings/relatives and close friends. A lead RN, an RN and an LPN are on site; blood glucose checks at snack and lunch times; staff trained in type 1 diabetes management.', NULL, TRUE, 'https://peopleincfr.org/wp-content/uploads/Camp-Jack-Brochure-2-1.pdf', 2026, '8d44c93c-d39b-5398-8736-210ece4b411a', 'camp-jack', ST_GeogFromText('SRID=4326;POINT(-71.067 41.7962)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=127+North+Main+Street&city=Assonet&state=MA&benchmark=Public_AR_Current&format=json','https://peopleincfr.org/services/diabetes-association-inc/camp-jack/','https://peopleincfr.org/wp-content/uploads/2026-Camper-Handbook-1.pdf','https://peopleincfr.org/wp-content/uploads/Camp-Jack-Brochure-2-1.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Kaleidoscope', NULL, 'https://kaleidoscopepvd.org/camp.html', 'https://kaleidoscopepvd.cheddarup.com', 'contact@kaleidoscopepvd.org', NULL, '131 Washington Street (AS220 Community Studios)', 'Providence', 'RI', '02903', 'Providence, RI', 'day', ARRAY['STEM','arts','technology']::text[], NULL, ARRAY['open shop','electronics','cardboard crafts','art-making','computer programming','science projects','outdoor games','free play','self-directed projects']::text[], NULL, 6, 12, NULL, NULL, 'A child-centered summer day camp for ages 6-12 at AS220 Community Studios in Providence, RI, running 8:30 am to 3:30 pm. Campers pick from optional staff-led activities such as open shop, electronics, cardboard crafts, art, programming and science projects, or work on their own projects and design their own camp day.', NULL, NULL, 350, 350, 350, 'week', NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '91abea31-45ce-5d5f-bd8d-f2fcc66760f8', 'camp-kaleidoscope', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=131+Washington+Street&city=Providence&state=RI&benchmark=Public_AR_Current&format=json','https://kaleidoscopepvd.org/about.html','https://kaleidoscopepvd.org/camp.html','https://kaleidoscopepvd.org/index.html','https://kaleidoscopepvd.org/philosophy.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Metacomet', 'YMCA Southcoast', 'https://ymcasouthcoast.org/location/camp-metacomet/', 'https://operations.daxko.com/online/2096/ProgramsV2/Home.mvc', 'mhebert@ymcasc.org', '(508) 993-3361 x 10', '276 Gulf Road', 'Dartmouth', 'MA', '02748', 'Providence, RI', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['archery','sports','adventure challenge','rock climbing','arts and crafts','swimming','team-oriented games','Craft Lovers Camp (specialty)','Farm to Table (specialty)','Drama (specialty)','cooking','engineering']::text[], NULL, 4, 14, NULL, NULL, 'YMCA Southcoast summer day camp on 58 acres in Dartmouth, MA, open weekdays 9:00 AM to 4:00 PM with an outdoor pool. Activities include archery, sports, rock climbing, arts and crafts and swimming, plus specialty weeks for ages 9-14.', NULL, NULL, 315, 405, NULL, 'session', TRUE, TRUE, FALSE, TRUE, 'A $50 non-refundable deposit per session is due at registration and goes toward the camp fee. Withdrawing needs four weeks'' written notice, and tuition minus the deposit is refunded. After a session starts, refunds only for illness or injury with a doctor''s note. Session changes cost $25 and need two weeks'' notice.', NULL, 'Camp has an outdoor pool; swimming is one of the traditional activities.', NULL, NULL, 2026, '9334e261-1932-5832-a6e3-97d7f25b990d', 'camp-metacomet-dartmouth', ST_GeogFromText('SRID=4326;POINT(-70.9582 41.5665)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://ymcasouthcoast.org/location/camp-metacomet/','https://ymcasouthcoast.org/wp-content/uploads/2026/04/2026_CampRegistration_Fill.pdf','https://ymcasouthcoast.org/wp-content/uploads/2026/04/Camp-Handbook-2026-final.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Phoenix', NULL, 'https://www.campphoenixonline.com/', 'https://www.campphoenixonline.com/registration-pricing', NULL, '(401) 570-7817', '2214 Providence Pike', 'North Smithfield', 'RI', '02896', 'Providence, RI', 'day', ARRAY['general','outdoor']::text[], NULL, ARRAY['Unplugged outdoor activities','Weekly themed activities']::text[], NULL, NULL, NULL, 0, 7, 'A summer day camp for children in kindergarten through 7th grade in North Smithfield, RI. Activities are unplugged and outdoors, kids choose their own activities, and each week has a theme.', NULL, NULL, NULL, NULL, 220, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'a543d995-f8d2-5b0c-8b27-c7da2043e1fe', 'camp-phoenix-north-smithfield', ST_GeogFromText('SRID=4326;POINT(-71.5495 41.9665)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=2214+Providence+Pike&city=North+Smithfield&state=RI&benchmark=Public_AR_Current&format=json','https://www.campphoenixonline.com/','https://www.campphoenixonline.com/registration-pricing']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp WANNAGOAGAIN!', 'The Autism Project', 'https://theautismproject.org/parents-families/programs-resources/summer-camp', 'https://theautismproject.org/parents-families/programs-resources/summer-camp/camper-registration', 'Catherine.Young@brownhealth.org', '401-785-2666 ext. 76787', 'Buck Hill Scout Reservation, 422 Croff Rd', 'Pascoag', 'RI', '02859', 'Providence, RI', 'day', ARRAY['special_needs','nature']::text[], NULL, ARRAY['Swimming','Boating','Arts and crafts','Nature walks','Sensory-based activities','Social skills activities']::text[], NULL, 5, NULL, NULL, NULL, 'A week-long day camp at Buck Hill Scout Reservation in Pascoag, RI for children, teens, and young adults with autism and related social-emotional or communication challenges, with visual supports, a low camper-to-counselor ratio, and 1:1 support when needed. The third week is for adult campers (18+).', NULL, NULL, 550, 550, NULL, 'week', NULL, TRUE, NULL, TRUE, '$550 for the week includes a $75 non-refundable registration fee; the fee is returned if a waitlisted child is not placed.', 'For campers with autism and related social-emotional or communication challenges. Supports include visual supports, a low camper-to-counselor ratio, 1:1 support when needed, structured teaching methods, sensory-based activities, relaxation techniques for self-regulation, and daily living routines. The camp director decides which week each camper attends after reviewing the application.', 'Camp facilities include a lake. Activities include swimming and boating. The page gives no details on swim supervision or swim tests.', NULL, NULL, 2026, 'b1cbaad6-9368-5364-95e7-b809c098f45d', 'camp-wannagoagain-pascoag', ST_GeogFromText('SRID=4326;POINT(-71.7012 41.9554)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://theautismproject.org/parents-families/programs-resources/summer-camp','https://theautismproject.org/parents-families/programs-resources/summer-camp/camp-faqs','https://theautismproject.org/parents-families/programs-resources/summer-camp/camp-faqs-1','https://theautismproject.org/parents-families/programs-resources/summer-camp/camper-registration']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Whitin', 'Whitin Community Center', 'https://www.whitincommunitycenter.com/our-community/camp-whitin/', 'https://operations.daxko.com/Online/5309/ProgramsV2/Home.mvc', 'campwhitin@ourgym.org', '508-234-8184', '60 Main Street', 'Whitinsville', 'MA', '01588', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['Sports','Activity camps','Swimming','Outdoor activities in Whitin Park','Crafts and games (extended care)']::text[], NULL, 4, 13, NULL, NULL, 'Weekly co-ed day camps run by the Whitin Community Center in Whitinsville, MA, for ages 4-13. Children ages 7-13 choose a sport or activity camp with daily swimming in the WCC pool, and children ages 4-6 attend Mini camps. Camp runs 9:00am-3:00pm, Monday-Friday, with time outdoors in the 7.5-acre Whitin Park.', NULL, NULL, 231, 335, NULL, 'week', TRUE, NULL, FALSE, TRUE, 'A $50 non-refundable deposit per camp week holds a space. Cancel by May 1 for a full refund minus the $50 deposit per week and a $25 processing fee; after that, a 75% refund (minus the same) only for a documented medical reason with at least 1 day''s notice. Deposits are never refunded.', NULL, 'Campers ages 7-13 can swim daily in the WCC Competition Pool. Mini camps (ages 4-6) do not swim.', NULL, NULL, 2026, 'd44bb9c9-1950-5bf4-8af1-7e798b355d89', 'camp-whitin-whitinsville', ST_GeogFromText('SRID=4326;POINT(-71.6662 42.1112)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.whitincommunitycenter.com/our-community/camp-whitin/','https://www.whitincommunitycenter.com/wp-content/uploads/2026/03/CampWhitin2026FINAL.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp Woonasquatucket', 'Woonasquatucket River Watershed Council (WRWC)', 'https://wrwc.org/what-we-do/education/camp-woonasquatucket/', 'https://www.eventbrite.com/cc/camp-woonasquatucket-2026-4813273', 'camp@wrwc.org', '401.861.9046', '5 Waterview Drive', 'Smithfield', 'RI', '02917', 'Providence, RI', 'day', ARRAY['nature','STEM']::text[], ARRAY['outdoor']::text[], ARRAY['Hiking forests and wetlands','Wildlife observation, animal tracking and bird watching','Science experiments','Bug study','Upcycled nature crafts','Aquatic life and conservation projects','Environmental stewardship']::text[], NULL, 7, 13, NULL, NULL, 'An environmental education day camp (Mon-Fri, 9 AM-3 PM) at the Leo Bouchard Conservation Center in Smithfield, RI, for ages 8-13 (now also age 7). Campers hike forests and wetlands, watch wildlife and birds, do science experiments, study bugs, make upcycled nature crafts and take part in conservation projects.', 'outdoor', NULL, 400, 400, 400, 'week', NULL, NULL, NULL, TRUE, 'Full payment due at registration. Cancellations at least 10 days before the session are refunded minus a $50 processing fee; no refunds within 10 days. Full refund if a session is canceled for low enrollment. 50% off for the second child.', NULL, 'The center has a canoe/kayak launch and campers ''splash into aquatic life''. The page does not say whether there is swimming, boating or lifeguard supervision.', NULL, NULL, 2026, '0f940b01-d7b3-5255-b0d1-c9e379a5b01b', 'camp-woonasquatucket-smithfield', ST_GeogFromText('SRID=4326;POINT(-71.5495 41.922)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://wrwc.org/what-we-do/education/camp-woonasquatucket/']::text[], '2026-11-13', '2026-11-13', TRUE),
('CCF Summer Programs', 'Connecting for Children & Families', 'https://www.ccfcenter.org/summer-camps', NULL, 'info@ccfcenter.org', '(401) 766-3384', '46 Hope Street', 'Woonsocket', 'RI', '02895', 'Providence, RI', 'day', ARRAY['academic']::text[], ARRAY['STEM','arts']::text[], ARRAY['Math, literacy and science','Social/emotional activities','Music and movement','Arts and crafts','Games','Physical activity','Water play','Theater','Animal science','Engineering','Financial education','Career exploration','Service learning','Underwater ROV building (SeaPerch, grades 6-8)']::text[], NULL, NULL, NULL, 0, 8, 'Summer learning camps by grade from Connecting for Children & Families, a Woonsocket non-profit: Camp Discovery (incoming K-2) and Chillin'' & Skillin'' (grades 3-5) mix theme-based math, literacy and science with arts, games and play; Get Connected (grades 6-8) is a 4-week career exploration camp.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '633656f5-4190-5b74-a1b1-1191207f2c53', 'ccf-summer-programs-woonsocket', ST_GeogFromText('SRID=4326;POINT(-71.5148 42.0026)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.ccfcenter.org/summer-camps','https://www.ccfcenter.org/summer-camps/grades-6-thru-8','https://www.ccfcenter.org/summer-camps/grades-k-5']::text[], '2026-11-13', '2026-11-13', TRUE),
('Creative Corner Art Studio – Summer Art Club', 'Creative Corner Art Studio', 'https://www.creativecornerartstudiofranklin.com/services-4', NULL, 'amy.creativecornerartstudio@gmail.com', NULL, '21 E Central St', 'Franklin', 'MA', '02038', 'Providence, RI', 'day', ARRAY['arts']::text[], NULL, ARRAY['Painting (canvas, watercolor, acrylic, oil pastel)','Pottery & clay','Mixed media & sculpture','Wood, fabric and jewelry-making','LEGO builds','Movie production & performing arts (two-week session)','Outdoor sketching']::text[], NULL, 5, 11, NULL, NULL, 'Weekly summer art clubs for ages 5-11 at Creative Corner Art Studio in downtown Franklin, MA. Each week has a theme, with painting, pottery and clay, mixed media, jewelry and LEGO builds; a two-week session in July makes a short film with Franklin High School students. Half day 8:30-12:00 or full day 8:30-3:30, with a Friday art share for families.', NULL, NULL, 300, 400, 300, 'week', TRUE, NULL, FALSE, NULL, 'No refunds on studio events, services or products. You can get a credit instead, good for up to one year from purchase, toward any studio event, class or studio-branded merchandise. This does not cover artwork by local or third-party artists.', NULL, NULL, NULL, NULL, 2026, '9b2997df-ae94-5e6d-8733-a18dd7768163', 'creative-corner-art-studio-summer-art-club-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.creativecornerartstudiofranklin.com/','https://www.creativecornerartstudiofranklin.com/services-4']::text[], '2026-11-13', '2026-11-13', TRUE),
('DARE to Dream Summer Day Program', 'DARE to Dream Summer Day Program', 'https://www.daretodreamsummer.com/', 'https://dare-to-dream-summer-camp.jumbula.com/', 'daretodreamsummer@gmail.com', NULL, 'Sweatt Recreational Complex, Randall Road', 'Wrentham', 'MA', '02093', 'Providence, RI', 'day', NULL, NULL, ARRAY['field activities','arts and crafts','safety demonstrations and presentations','field trips (Southwick Zoo, Sweatt Beach, Water Wizz, PINZ)','minor league baseball games (Brockton Rox / Worcester Bravehearts)']::text[], NULL, NULL, NULL, 3, 6, 'A one-week summer day program in Massachusetts for children in grades 3–6 that teaches personal safety, social media awareness and healthy decision-making. Days mix field activities, arts and crafts, safety demonstrations and field trips, usually from 9am to 2pm.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Field trips include Sweatt Beach and Water Wizz (water park). The page gives no details on swim supervision or swim tests.', NULL, NULL, 2026, '63130167-3795-5950-901d-15ebd30c96a0', 'dare-to-dream-summer-day-program-wrentham', ST_GeogFromText('SRID=4326;POINT(-71.3281 42.0668)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.daretodreamsummer.com/','https://www.daretodreamsummer.com/grades-56']::text[], '2026-11-13', '2026-11-13', TRUE),
('Extraordinary Kids Therapy Therapeutic Summer Camp', 'Extraordinary Kids Therapy', 'https://www.extraordinarykidstherapy.net/camps-and-groups', NULL, 'frontdesk@extraordinarykidstherapy.net', '401-203-5444', '389 Putnam Pike', 'Glocester', 'RI', '02814', 'Providence, RI', 'day', ARRAY['special_needs']::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A therapeutic summer day camp run by Extraordinary Kids Therapy, a pediatric therapy practice in Chepachet (Glocester), RI, for children of all abilities. Full-day and half-day options; each week has a theme (Farm Week, Shark Week, Zoo Camp and more) that guides therapy, activities and special events. Full day is capped at 20 children per week.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Apply by email; once staff accept the application you pay a $50 non-refundable deposit for each week you register. No other refund terms are stated.', 'This is a therapeutic camp run by a pediatric therapy practice. Weekly themes "guide our treatment, activity planning, and special events," and the camp describes itself as an inclusive environment for children of all abilities.', NULL, NULL, NULL, 2026, 'd4e42a41-c134-524e-b13b-9f40d722678a', 'extraordinary-kids-therapy-therapeutic-summer-camp', ST_GeogFromText('SRID=4326;POINT(-71.687 41.889)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.extraordinarykidstherapy.net/camps-and-groups','https://www.extraordinarykidstherapy.net/contact']::text[], '2026-11-13', '2026-11-13', TRUE),
('FHF Farm Explorers Camp', 'Faith Hill Farm', 'https://www.faithhillfarmri.com/fhf-summer-camp', 'https://docs.google.com/forms/d/e/1FAIpQLSdsiXJ-3VqITOxz-BETqznpAsr2fsIxaquePm60qdniRe8Xqw/viewform', 'faithhillfarmcamp@gmail.com', '(401) 524-1788', '2056 Division Rd', 'East Greenwich', 'RI', '02818', 'Providence, RI', 'day', ARRAY['nature','outdoor','arts']::text[], NULL, ARRAY['Horse grooming and leading','Weekly pony rides','Mini horses, therapy goats and donkeys','Animal care','Habitat and wildlife exploration','Team building','Field games','Arts and crafts','Water play']::text[], NULL, 6, 12, NULL, NULL, 'Outdoor farm and nature day camp at Faith Hill Farm for ages 6-12. Campers groom and lead horses, get weekly pony rides, care for goats, donkeys and mini horses, and do crafts and field games. Formal riding lessons are not included.', NULL, NULL, 350, 375, 375, 'week', NULL, NULL, NULL, NULL, 'Full refund minus the $15 registration fee if you cancel 14 or more days before your camp week. If you cancel 8-13 days before, you get a 50% refund (minus $15) or full credit toward another week. Within 7 days, you get credit toward another week only. No refunds or credits for no-shows or missed days.', NULL, 'The schedule mentions "water play" as an afternoon activity. No swimming or waterfront is described.', NULL, NULL, 2026, '02dde10a-078d-5a37-9d67-c10a007a6024', 'fhf-farm-explorers-camp-east-greenwich', ST_GeogFromText('SRID=4326;POINT(-71.4601 41.6601)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.faithhillfarmri.com/','https://www.faithhillfarmri.com/fhf-summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Fore Court Summer Tennis Camp', 'Fore Court', 'https://www.forecourtri.com/kids/summer-camp', NULL, 'info@forecourtri.com', '401.333.4480', '44 Cray Street', 'Cumberland', 'RI', '02864', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Tennis','Stroke technique','Footwork','Point play','Match play preparation']::text[], NULL, 5, 17, NULL, NULL, 'A half-day tennis camp (9 AM–12 PM) at Fore Court in Cumberland, RI, for beginner and intermediate juniors ages 5–17. Courts are capped at 4 juniors each. There is also a separate afternoon training camp for advanced, match-ready juniors.', NULL, NULL, 260, 280, 280, 'week', NULL, NULL, NULL, NULL, 'Camps are non-refundable. Full payment is due when you register, and any previous balances must be paid first.', NULL, NULL, NULL, NULL, 2027, '06996049-9064-5f18-9ec9-d012aac03ced', 'fore-court-summer-tennis-camp-cumberland', ST_GeogFromText('SRID=4326;POINT(-71.4328 41.9668)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.forecourtri.com/kids/summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Franklin Country Day Camp', NULL, 'https://www.franklincountrydaycamp.com/', NULL, 'fcdc@franklincountrydaycamp.com', '508-570-8317', '1221 Pond Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'day', ARRAY['sports','arts','nature','performing_arts']::text[], NULL, ARRAY['Adventure','Archery','Arts & Crafts','Boating','Ceramics','Creative Music','Games','Pioneering','Special Days','Swimming','Theater Arts','Video','Woodlore','Woodworking']::text[], NULL, 4, 12, NULL, 6, 'A day camp on 250 acres in Franklin, MA, with forest trails, fields, a stream, a pond and two pools, for children from entering kindergarten through grade 6. Camp runs 9 a.m. to 4 p.m. in two-week sessions, with archery, boating, Red Cross swimming, arts and crafts, ceramics, music, theater, woodworking and woodlore, and no cell phones or gaming devices.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, 'The camp has two inground swimming pools for its Red Cross swim program; Jr. Camp swimming lessons are taught by Red Cross accredited instructors. There is also a pond and a natural stream, and boating is an activity.', NULL, NULL, 2027, '700ceb2d-9994-574e-aa36-678d4b887087', 'franklin-country-day-camp-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.franklincountrydaycamp.com/','https://www.franklincountrydaycamp.com/about/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Franklin Recreation Department Summer Camp', 'Franklin Recreation Department (Town of Franklin)', 'https://franklinma.gov/1158/Summer-Camp', 'https://franklinma.myrec.com/info/activities/program_details.aspx?ProgramID=29874', 'summercamp@franklinma.gov', NULL, '740 King Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'day', NULL, NULL, ARRAY['outdoor activities','field trips','arts & crafts','gaga ball','playgrounds']::text[], NULL, NULL, NULL, NULL, NULL, 'A town-run day camp at King Street Memorial Park. It runs 8:30am to 3:30pm and includes outdoor activities, arts & crafts, gaga ball, playgrounds and a weekly Wednesday field trip that is covered by the camp fee.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '8d83f5c5-cb9c-5156-870a-ad59821c8a40', 'franklin-recreation-department-summer-camp-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://franklinma.gov/1158/Summer-Camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Friends Academy Summer Programs', 'Friends Academy', 'https://www.friendsacademy1810.org/summer/', 'https://friendsacademysummerprograms.campbrainregistration.com/', 'summerfriends@friendsacademy1810.org', '(508) 999-1356', '1088 Tucker Rd.', 'North Dartmouth', 'MA', '02747', 'Providence, RI', 'day', ARRAY['sports','arts','STEM','nature','technology','academic','special_needs']::text[], NULL, ARRAY['art','crafts','games','design','sewing','nature','science','coding','reading and writing','outdoor skills','soccer','basketball','fencing','running','math','structured literacy']::text[], NULL, 3, 16, NULL, 9, 'Day camps for ages 3-16 on Friends Academy''s 65-acre campus in North Dartmouth, with more than 40 full-day and half-day options: the general Summer Friends camp, creative, enrichment and sports camps, a counselor-in-training program, and academic camps for students with language-based learning differences.', NULL, NULL, 300, 1215, 450, 'week', TRUE, NULL, FALSE, NULL, 'Deposits are non-refundable ($125 half-day, $200 full-day, $425 SBP/CIT). If you cancel before Friday, May 29, you get back everything except the deposit. After May 29, you pay the full cost. Camps canceled for low enrollment are fully refunded. Medical cancellations with a doctor''s note get a partial refund. Changing to a different week costs $25. Changing within the same week is free.', 'Sally Borden Program (SBP) Academic Camps: 6-week summer courses in math, writing and structured literacy for grades 1-8 with language-based learning differences and/or vulnerabilities, taught by educators trained in Orton-Gillingham.', NULL, NULL, NULL, 2026, '468aea3f-6b81-5673-9eea-e27bec42b824', 'friends-academy-summer-programs-north-dartmouth', ST_GeogFromText('SRID=4326;POINT(-70.9582 41.5665)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.friendsacademy1810.org/summer/','https://www.friendsacademy1810.org/summer/summer-friends-day-camp-dartmouth-ma/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Hall of Fame Tennis Camp', 'International Tennis Hall of Fame', 'https://www.tennisfame.com/club/junior', 'https://tennisfame.wufoo.com/forms/2026-hall-of-fame-summer-tennis-camp/', 'newport@tennisfame.com', '401-849-4777', '194 Bellevue Avenue', 'Newport', 'RI', '02840', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Tennis']::text[], NULL, 8, 16, NULL, NULL, 'A half-day junior tennis camp for ages 8-16 at the International Tennis Hall of Fame in Newport. It runs Monday to Friday, 8:30-11:30 am, in weekly sessions with at most 4 players per court.', NULL, NULL, 450, 600, 600, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '49736619-96e8-5aff-b57f-39370de678b8', 'hall-of-fame-tennis-camp-newport', ST_GeogFromText('SRID=4326;POINT(-71.3128 41.4901)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://www.tennisfame.com/club/junior']::text[], '2026-11-13', '2026-11-13', TRUE),
('Jamestown Sea Adventure Camp', 'Conanicut Island Sailing Foundation (CISF)', 'https://www.jamestownsailing.org', 'https://seaadventurecamp.campbrainregistration.com/', 'Contact@JamestownSailing.org', '401-855-6643', '1050 Fort Getty Road', 'Jamestown', 'RI', '02835', 'Providence, RI', 'day', ARRAY['sailing']::text[], ARRAY['nature']::text[], ARRAY['Sailing','Salt marsh exploration','Rocky shore exploration','Touch tanks','Marine science','Crabbing','Arts and crafts','Swimming']::text[], NULL, 4, 16, NULL, NULL, 'One-week sessions at Fort Getty in Jamestown for kids ages 4 to 16, mixing sailing on Hobie Waves and skiffs with marine science on the salt marsh, rocky shore and touch tanks. Half-day groups for younger children, full days (9am to 4pm) for ages 8-16, plus Strictly Sailin'' and a Leadership Program. No sailing experience needed.', 'outdoor', NULL, 215, 430, NULL, 'week', NULL, NULL, NULL, TRUE, '$40 per child administrative fee on all cancellations; before June 1 the balance is refunded, after June 1 only if the spot is filled. Changes must be emailed to Contact@JamestownSailing.org.', NULL, 'Camp is outdoors at Fort Getty under a tent near the boat ramp. Life jackets are provided for sailing; an informal swim check (short swim with life jacket) may be done before sailing. Explorers (4-6) are land-based and do not swim or sail.', NULL, NULL, 2026, 'bba697b8-1691-5696-b2d2-a1d67c4d4458', 'jamestown-sea-adventure-camp-jamestown', ST_GeogFromText('SRID=4326;POINT(-71.3673 41.4968)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.jamestownsailing.org','https://www.jamestownsailing.org/camp-overview/','https://www.jamestownsailing.org/camp-pricing/','https://www.jamestownsailing.org/camp-schedule/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kent County''s Best Summer Camp and After School', 'Cellucci''s Martial Arts LLC', 'https://kentcountysummercamp.com/', 'https://kentcountysummercamp.com/lead-collection-form', NULL, '(401) 822-7780', '555 Quaker Lane', 'West Warwick', 'RI', '02893', 'Providence, RI', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['Indoor sports','Outdoor sports','Games','Educational lessons','Arts and crafts','Guest speakers','Water slides','Bounce houses','Martial arts','Dance','Team sports','Leadership training']::text[], NULL, NULL, NULL, 0, 5, 'A summer camp for children in kindergarten through 5th grade in West Warwick, RI, run by Cellucci''s Martial Arts LLC. Each week includes indoor and outdoor sports, educational lessons, and arts and crafts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '47966d99-5b7e-5227-98b1-93cfb14cd8c2', 'kent-county-s-best-summer-camp-and-after-school-west-warwick', ST_GeogFromText('SRID=4326;POINT(-71.5218 41.6968)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://kentcountysummercamp.com/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Kingston''s Camp', NULL, 'https://www.kingstonscamp.com/kingstons-camp-home', 'https://app.campdoc.com/!/dn/login?r=kingstonscamp', 'info@kingstonscamp.com', '401-783-8620', '2795 Ministerial Road', 'West Kingston', 'RI', '02892', 'Providence, RI', 'day', ARRAY['general','outdoor']::text[], ARRAY['swimming','leadership']::text[], ARRAY['Swimming and daily swim lessons','Boating','Arts & crafts','Field games','Sports','Outdoor skills','Environmental stewardship','Leadership (Middle School Gopher Program)']::text[], NULL, 4, 14, 0, 9, 'A small, independently run, all-outdoor, unplugged day camp in West Kingston, RI for ages 4 to 14, with daily swim lessons, boating, arts and crafts and field games. The Main Program serves entering K-6th grade; the Middle School Gopher Program (grades 7-9) is a leadership program. Weekly sessions, 9am to 3pm.', 'outdoor', NULL, 205, 350, NULL, 'week', TRUE, NULL, FALSE, TRUE, '$30 annual registration fee and $30/week deposit are non-refundable; program fees fully refundable until June 1; no refunds for missed days, weather closures, pond closures or withdrawal.', 'Welcomes campers who can thrive in a group-based, active environment; reasonable accommodations offered when possible; families are asked to contact the camp before registering.', 'Swimming in Larkin''s Pond (a natural pond monitored for bacteria; occasionally closed). Daily swim lessons, shallow and deep areas, swim competency test before deep water, lifeguard-supervised waterfront.', TRUE, 'https://www.kingstonscamp.com/kc-parent-resources', 2026, 'fdf2f56b-eaa4-53ab-a4d0-e38a9df35e0b', 'kingston-s-camp-west-kingston', ST_GeogFromText('SRID=4326;POINT(-71.5612 41.4826)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=2795+Ministerial+Road&city=West+Kingston&state=RI&benchmark=Public_AR_Current&format=json','https://www.kingstonscamp.com/kc-camp-registration-pricing','https://www.kingstonscamp.com/kc-parent-resources','https://www.kingstonscamp.com/kc-program-info-resources','https://www.kingstonscamp.com/kingstons-camp-home']::text[], '2026-11-13', '2026-11-13', TRUE),
('La Salle Academy Summer Camps', 'La Salle Academy', 'https://www.lasalle-academy.org/campus-life/summer-camps', 'https://lsa.simpletix.com/', 'apoirier@lasalle-academy.org', '401-351-7750 ext. 152', '612 Academy Avenue', 'Providence', 'RI', '02908', 'Providence, RI', 'day', ARRAY['sports','performing_arts','STEM','academic']::text[], NULL, ARRAY['Tennis','Soccer','Basketball','Volleyball','Musical theater','Robotics','STEM','ELA and math enrichment','Field trips','SAT prep']::text[], NULL, NULL, NULL, 3, 12, 'La Salle Academy, a Catholic high school in Providence, runs a set of separate half-day and full-day summer camps on its campus. They cover sports (tennis, basketball, volleyball, soccer), musical theater, robotics/STEM, academic enrichment and SAT prep for students in about grades 3-12.', NULL, NULL, 200, 500, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'fd8e3f3d-ff8c-5fae-b70c-fffb43ad3358', 'la-salle-academy-summer-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.lasalle-academy.org/campus-life/summer-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Liddle Tots II Teen Summer Camp', 'Liddle Tots II Teen', 'https://www.liddletots2teen.com/', NULL, 'info@liddletots2teen.com', '(401) 781-1870', '1160 Post Rd', 'Warwick', 'RI', '02888', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['Sports','Cooking','Arts & drama','Team games','Crafts','Science','Weekly themes','Field trips','Olympic games','Trivia competitions','Cheerleading and football teams','CIT (Counselor in Training) program']::text[], NULL, NULL, NULL, NULL, NULL, 'A summer day camp run by Liddle Tots II Teen, a DCYF-licensed childcare center in Warwick, RI. Programs for each age group mix sports, cooking, arts and drama, team games, crafts and science, with weekly themes and field trips. Camp runs Monday to Friday, 7 AM to 5:30 PM.', NULL, NULL, 260, 260, 260, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '6829d432-6cff-52c3-9ac6-7f84c33cc0bb', 'liddle-tots-ii-teen-summer-camp-warwick', ST_GeogFromText('SRID=4326;POINT(-71.4162 41.7001)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.liddletots2teen.com/','https://www.liddletots2teen.com/summer-camp','https://www.liddletots2teen.com/tuition-rates']::text[], '2026-11-13', '2026-11-13', TRUE),
('MACH 1 Soccer Camps', 'MACH 1 Futbol Club', 'http://mach1fc.com/camps', NULL, 'info@mach1fc.com', NULL, '621 Pound Hill Rd', 'North Smithfield', 'RI', '02896', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Soccer skills training','Small-sided games','Individual and small group tactics','Position-specific training (defending, attacking, transitioning)']::text[], NULL, NULL, NULL, NULL, NULL, 'Indoor, air-conditioned soccer day camps run by MACH 1 Futbol Club at Wide World of Indoor Sports in North Smithfield, RI. Younger players (U6-U8) attend a half day (9:00-12:00); older players (U7-U11 and U12-U14) attend a full day (9:00-3:30) of skills and tactics training. Early drop-off and late pickup cost extra.', NULL, NULL, 179, 279, 279, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, 'd4983cff-561f-5cf2-b391-1147a15c2af2', 'mach-1-soccer-camps-north-smithfield', ST_GeogFromText('SRID=4326;POINT(-71.5495 41.9665)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['http://mach1fc.com/camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Mandell-Boisclair Justice Camp (RWU School of Law Social Justice Camp)', 'Roger Williams University School of Law', 'https://www.rwu.edu/summer-camps/rwu-school-law-social-justice-camp', NULL, NULL, '1-800-458-7144', '1 Empire Street', 'Providence', 'RI', '02903', 'Providence, RI', 'specialty', ARRAY['academic']::text[], NULL, ARRAY['Learning about the justice system','Mock arguments at the RI State House','Meeting attorneys, judges and community leaders','Studying democracy, elections and voting rights','Voter registration drive','Meeting candidates for local and state office']::text[], NULL, NULL, NULL, 6, 9, 'A one-week day program for middle schoolers about social justice and the law, run at RWU''s downtown Providence campus with a visit to the Bristol campus. Campers learn from practicing attorneys, Rhode Island judges and community leaders.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '29f8a4e9-444a-5a9d-bc23-afeac5efdc19', 'mandell-boisclair-justice-camp-rwu-school-of-law-social-justice-camp-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.rwu.edu/summer-camps/rwu-school-law-social-justice-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Marine Biology Camp', 'Roger Williams University, Department of Biology, Marine Biology and Environmental Science', 'https://www.rwu.edu/academics/marine-biology-camp', 'https://www.rwu.edu/academics/marine-biology-camp', 'mbiocamp@rwu.edu', '401-254-3814', '1 Old Ferry Road', 'Bristol', 'RI', '02809', 'Providence, RI', 'specialty', ARRAY['STEM','nature','academic']::text[], NULL, ARRAY['Oceanographic sampling','Sea kayaking','Snorkeling','Whale watching boat trip','Marine organism identification','Plankton sampling','Laboratory experiments','Aquaculture','Guest seminars']::text[], NULL, NULL, NULL, 11, 12, 'A one-week overnight marine biology program for rising high school juniors and seniors at Roger Williams University in Bristol, RI. Campers live in a waterside residence hall and do daily field and lab work, including snorkeling, sea kayaking, plankton sampling and a whale-watching trip off Cape Cod, plus guest lectures by RWU scientists. Enrollment is limited to 18 per session.', NULL, NULL, 2195, 2195, NULL, 'session', NULL, FALSE, TRUE, TRUE, 'A $500 deposit is due with the application and can be refunded through April 1. The remaining $1,695 is due by May 10. The page does not say what happens if you cancel after the balance is paid.', NULL, 'Campers are in or on the water every day: snorkeling along barrier beaches and tidal pools, sea kayaking, and boat trips. Snorkel gear is practiced in the pool on arrival day. RWU lends snorkel gear, or campers can bring their own. The camp says it is not a good fit for students who are uneasy around the water. Swim test requirements are not stated.', NULL, NULL, 2027, '7073dccd-f7b1-5869-9db9-1edd052645dc', 'marine-biology-camp-bristol', ST_GeogFromText('SRID=4326;POINT(-71.2673 41.6771)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.rwu.edu/academics/marine-biology-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Moses Brown Performing and Visual Arts Camps', 'Moses Brown School (Moses Brown Auxiliary Services)', 'https://www.camps.mosesbrown.org/arts', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=222&campCode=MBS', 'mbplus@mosesbrown.org', '401-831-7350 (x150 or x295)', '250 Lloyd Ave', 'Providence', 'RI', '02906', 'Providence, RI', 'specialty', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['Fashion design','Art portfolio preparation','Visual art exploration','Theatre','String orchestra','Strings instruction']::text[], NULL, 8, 18, 3, 12, 'A set of week-long arts day programs at Moses Brown School in Providence: fashion design, art portfolio prep, art exploration, theatre, and string orchestra/strings camp. Most run 8:30am-3:00pm. Ages and grades vary by program and together cover about ages 8-18.', NULL, NULL, 250, 950, 475, 'week', TRUE, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, 2026, '19a1149f-6535-5e86-9b43-382bc8afbeb7', 'moses-brown-performing-and-visual-arts-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=250+Lloyd+Ave&city=Providence&state=RI&benchmark=Public_AR_Current&format=json','https://www.camps.mosesbrown.org/','https://www.camps.mosesbrown.org/arts','https://www.camps.mosesbrown.org/faanddiscounts','https://www.camps.mosesbrown.org/lunch','https://www.camps.mosesbrown.org/summerextendedaay']::text[], '2026-11-13', '2026-11-13', TRUE),
('Moses Brown Sports Camps', 'Moses Brown School (Moses Brown Auxiliary Services)', 'https://www.camps.mosesbrown.org/sportscamps', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=222&campCode=MBS', 'mbplus@mosesbrown.org', '401-831-7350 (x150 or x295)', '250 Lloyd Ave', 'Providence', 'RI', '02906', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['Baseball','Boys lacrosse','Girls lacrosse','Field hockey','Flag football','Basketball','Soccer','Softball','Squash','Tennis','Track and field','Volleyball']::text[], NULL, 4, 18, 1, 12, 'Weekly sports day camps at Moses Brown School in Providence, covering baseball, lacrosse, field hockey, flag football, basketball, soccer, softball, squash, tennis, track and field, and volleyball. Most programs are half-day mornings (8:30 a.m.-12:00 p.m.). Soccer and basketball also offer full days until 3:00 p.m.', NULL, NULL, 156, 345, NULL, NULL, TRUE, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, NULL, 2026, 'f7f5ea14-f84a-502f-a68d-d7524bfa2547', 'moses-brown-sports-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=250+Lloyd+Ave&city=Providence&state=RI&benchmark=Public_AR_Current&format=json','https://www.camps.mosesbrown.org/faanddiscounts','https://www.camps.mosesbrown.org/lunch','https://www.camps.mosesbrown.org/sportscamps','https://www.camps.mosesbrown.org/summerextendedaay']::text[], '2026-11-13', '2026-11-13', TRUE),
('Moses Brown STEM and Specialty Camps', 'Moses Brown School (Moses Brown Auxiliary Services)', 'https://www.camps.mosesbrown.org/stemandspecialty', 'https://www.ultracamp.com/clientlogin.aspx?idCamp=222&campCode=MBS', 'mbplus@mosesbrown.org', '401-831-7350 (x150 or x295)', '250 Lloyd Ave', 'Providence', 'RI', '02906', 'Providence, RI', 'day', ARRAY['STEM','technology','academic']::text[], NULL, ARRAY['Marine biology','Artificial intelligence','Astronomy and spaceflight','Forensic science','Architecture','Investing and economics','Medicine (Club Med)','Culinary','Chess','Taylor Swift-themed camp (Swiftie Summer)','Marvelous Discoveries Club']::text[], NULL, 5, NULL, 2, 12, 'A set of weeklong STEM and specialty day camps at Moses Brown School in Providence, including marine biology, AI, astronomy, forensic science, architecture, chess, culinary and more. Most programs run full days from 8:30 a.m. to 3:00 p.m., and each one has its own grade or age range.', NULL, NULL, 295, 1300, 475, 'week', TRUE, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, '2f539032-6fbb-5031-b995-507efe60943e', 'moses-brown-stem-and-specialty-camps-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=250+Lloyd+Ave&city=Providence&state=RI&benchmark=Public_AR_Current&format=json','https://www.camps.mosesbrown.org/stemandspecialty']::text[], '2026-11-13', '2026-11-13', TRUE),
('Newport Children''s Theatre Summer Theatre Camps', 'Newport Children''s Theatre', 'https://www.newportchildrenstheatre.org/summer-camps', NULL, 'office@newportchildrenstheatre.org', NULL, '1341 West Main St.', 'Middletown', 'RI', '02842', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theatre production','Play production','Acting and improvisation games','Writing monologues, scenes and sketches','Auditions and performances']::text[], NULL, 8, 18, NULL, NULL, 'Newport Children''s Theatre runs summer theatre camps for ages 8-18 at its studio in Middletown, RI: a one-week Performance Potpourri camp for ages 8-12 (acting, improv, writing scenes) and two-week camps that put on a musical and a play with public performances. 2026 shows were Newsies Jr. and The Three Musketeers.', NULL, NULL, 275, 700, NULL, 'session', NULL, NULL, FALSE, TRUE, 'Full payment (or a third-party payment plan) at registration; early-bird prices through April 15. Refunds carry a $50 fee: full refund more than 30 days before start, 50% at 14-30 days, none under 14 days. No refund for missed days or dismissal.', NULL, NULL, NULL, NULL, 2026, '6157e21e-c403-5501-8804-e2cb841e9ff7', 'newport-children-s-theatre-summer-theatre-camps-middletown', ST_GeogFromText('SRID=4326;POINT(-71.2924 41.5137)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=1341+West+Main+St.&city=Middletown&state=RI&benchmark=Public_AR_Current&format=json','https://www.newportchildrenstheatre.org/financial-policy','https://www.newportchildrenstheatre.org/newsies','https://www.newportchildrenstheatre.org/potpourri','https://www.newportchildrenstheatre.org/summer-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Newport Equestrian Academy Summer Camp', 'Newport Equestrian Academy', 'https://www.newportequestrian.com/summer', 'https://newportequestrian.ecpro.us/login', 'ridenewport@gmail.com', '401-837-4188', '287 Third Beach Rd', 'Middletown', 'RI', '02842', 'Providence, RI', 'specialty', ARRAY['sports','nature']::text[], NULL, ARRAY['Horseback riding','Horse care','Weekly horse show']::text[], NULL, 6, NULL, NULL, NULL, 'A horseback riding day camp, 8:30am to 2:00pm, for ages 6 and up. Campers ride once or twice a day and learn to care for horses. Beginners and advanced riders are both welcome, and there is a horse show for families every Friday.', NULL, NULL, 475, 475, 475, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '427b5286-e99e-5f41-84f4-16e1730ce5dc', 'newport-equestrian-academy-summer-camp-middletown', ST_GeogFromText('SRID=4326;POINT(-71.2924 41.5137)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://www.newportequestrian.com/summer']::text[], '2026-11-13', '2026-11-13', TRUE),
('Next Stop BROADWAY® & ENCORE!', 'Providence Performing Arts Center', 'https://www.ppacri.org/outreach/next-stop-broadway', NULL, 'nsb@ppacri.org', '(401) 421-2787', '220 Weybosset St', 'Providence', 'RI', '02903', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theatre','Singing','Choreography/dance','Acting','Final performance/showcase']::text[], NULL, 10, 17, NULL, NULL, 'A five-day, full-day musical theatre program held on the stage of the Providence Performing Arts Center. Each week ends with a Friday performance for families. Next Stop BROADWAY® is open to ages 10-17 and needs no audition. ENCORE! is an advanced week for experienced performers, who must apply to get in.', NULL, NULL, 525, 590, 565, 'week', NULL, NULL, FALSE, TRUE, NULL, NULL, NULL, NULL, NULL, 2027, '07e6c4da-dbf2-5b97-9c90-3e1cdd4fab8a', 'next-stop-broadway-and-encore-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.ppacri.org/outreach/next-stop-broadway']::text[], '2026-11-13', '2026-11-13', TRUE),
('One on One Basketball Summer Hoops Camps (Rhode Island)', 'One On One Basketball, Inc', 'https://providence.1on1basketball.com/programs?type=1', 'http://camps.mosesbrown.org/', 'frank@1on1basketball.com', '401-639-0814', '250 Lloyd Ave', 'Providence', 'RI', '02906', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Basketball']::text[], NULL, 5, 15, NULL, NULL, 'Weeklong basketball day camps run by One on One Basketball (camp director Coach Frank Luca) at Moses Brown School in Providence, plus an August week at the South Kingstown Recreational Center. Ages 5-15, full day or half day (morning or afternoon), shooting, defense and court-awareness stations, scrimmages and skills competitions, 9 to 1 camper-to-coach ratio. No prior experience needed.', NULL, NULL, 115, 345, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'e3d251f6-0346-530c-a736-47e19d1eab6e', 'one-on-one-basketball-summer-hoops-camps-rhode-island-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://providence.1on1basketball.com/programs?type=1','https://www.camps.mosesbrown.org/items-2/one-on-one-basketball']::text[], '2026-11-13', '2026-11-13', TRUE),
('Pennfield Summer Program', 'The Pennfield School', 'https://www.pennfield.org/summer-program/', 'https://www.homeroom.com/sites/the-pennfield-school-portsmouth/summer-camp/all', 'summer@pennfield.org', '401-849-4646', '110 Sandy Point Avenue', 'Portsmouth', 'RI', '02871', 'Providence, RI', 'day', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Themed summer camps at The Pennfield School''s 19-acre campus in Portsmouth, RI. They mix recreation with educational content and are led by educators and camp instructors.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'c797ffa2-4179-58ed-a320-09f557bf5669', 'pennfield-summer-program-portsmouth', ST_GeogFromText('SRID=4326;POINT(-71.2503 41.602)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.pennfield.org/summer-program/']::text[], '2026-11-13', '2026-11-13', TRUE),
('PLL Rhode Island Overnight Lacrosse Camp 2026', 'Premier Lacrosse League (PLL Play)', 'https://premierlacrosseleague.com/rhode-island-overnight-camp-2026', 'https://pllyouth.leagueapps.com/events/4807002-pll-overnight-2026-rhode-island', 'treh@premierlacrosseleague.com', NULL, 'Roger Williams University, 1 Old Ferry Rd', 'Bristol', 'RI', '02809', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Lacrosse','Team building']::text[], NULL, 8, 17, NULL, NULL, 'A four-day lacrosse camp at Roger Williams University, coached by PLL pros Kyle Jackson and Zach Geddes. You can choose an overnight option with room and board or a day camp option. All skill levels are welcome.', NULL, NULL, 549, 695, NULL, NULL, NULL, NULL, TRUE, NULL, 'Full refund, minus the transaction processing fee, if you cancel within 72 hours of registering, as long as you registered more than 14 days before the event. After 72 hours there is no refund or credit for any reason, including medical, injury or illness cancellations.', 'The camp says it can help with allergies and specific dietary needs if you contact it by email.', NULL, NULL, NULL, 2026, 'c42745df-dc9a-5d7e-9034-1a65d95ae207', 'pll-rhode-island-overnight-lacrosse-camp-2026-bristol', ST_GeogFromText('SRID=4326;POINT(-71.2673 41.6771)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://premierlacrosseleague.com/rhode-island-overnight-camp-2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Project FashionWorks Summer Classes', 'Project FashionWorks', 'https://projectfashionworks.com/collections/frontpage', NULL, 'elana@projectfashionworks.com', NULL, 'Temple Emanu-El, 99 Taft Ave.', 'Providence', 'RI', '02906', 'Providence, RI', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['Fashion design','Fashion merchandising','Fashion sketching','Mood and sketch boards','Portfolio development','Newspaper dress fashion show (tweens)']::text[], NULL, 8, 19, NULL, NULL, 'Week-long fashion design workshops (Monday to Friday, 10 to 3) taught by designer and educator Elana Carello at Temple Emanu-El in Providence: a Tween class for ages 8-12 and a Teen class for ages 13-19, covering design vocabulary, sketching fashion figures, markers, color and fabric, mood boards and college portfolio work. All experience levels welcome.', 'indoor', NULL, 425, 425, NULL, 'session', NULL, NULL, NULL, TRUE, 'Tuition fully refundable if requested in writing by email 45 days before the first class; no refunds after that, or if a participant is dismissed.', NULL, NULL, NULL, NULL, 2026, 'a04f34b7-3563-5177-a752-1d3056cb7f6f', 'project-fashionworks-summer-classes', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://projectfashionworks.com/collections/frontpage','https://projectfashionworks.com/collections/frontpage/products/tween-fashion-design-class-for-designers-8-12','https://projectfashionworks.com/pages/faqs','https://projectfashionworks.com/policies/refund-policy']::text[], '2026-11-13', '2026-11-13', TRUE),
('Rhode Island Fencing Academy & Club (RIFAC) Summer Camps', 'Rhode Island Fencing Academy & Club', 'https://rifac.com/summer-camps/', 'https://rifac.com/enroll/', NULL, '401-434-2404', '14 Almeida Avenue', 'East Providence', 'RI', '02914', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Fencing']::text[], NULL, 8, 18, NULL, NULL, 'Summer fencing camps at the Rhode Island Fencing Academy & Club in East Providence: full-day camps (9am-4pm, ages 9-15), half-day camps (ages 8-14, including a new Fencing + Russian Math camp with the Russian School of Mathematics) and High Performance camps for advanced foil and epee fencers up to age 18. Beginners get all equipment.', 'indoor', NULL, 295, 470, NULL, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'baece74b-d901-5ed7-9f42-ee5ebbde147d', 'rhode-island-fencing-academy-and-club-rifac-summer-camps-east-providence', ST_GeogFromText('SRID=4326;POINT(-71.3701 41.8137)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://rifac.com/','https://rifac.com/summer-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('RI Magic Summer Hoops Camp', 'Rhode Island Magic', 'https://www.rhodeislandmagic.com/copy-of-summer-camp-2026', 'https://docs.google.com/forms/d/e/1FAIpQLSdq1Gp-u976bFf7KDtJCJm1vDFPPBXS0X-SMrXPtrMmHR0SaA/viewform', 'rhodeislandmagic@gmail.com', '401-864-2629', 'Mount Saint Charles Academy, 800 Logee St.', 'Woonsocket', 'RI', '02895', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Basketball','Skill stations','Games, contests, relays and competitions']::text[], 'coed', NULL, NULL, 3, 9, 'A four-day basketball day camp, 9am-3pm, for boys and girls entering grades 3 through 9, held at Mount Saint Charles Academy in Woonsocket. Players are grouped by grade and skill level and learn fundamentals through skill stations, games and competitions. All experience levels are welcome.', NULL, NULL, 275, 275, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '472a49de-7565-55d4-bed1-f55f3528b734', 'ri-magic-summer-hoops-camp-woonsocket', ST_GeogFromText('SRID=4326;POINT(-71.5148 42.0026)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=Mount+Saint+Charles+Academy%2C+800+Logee+St.&city=Woonsocket&state=RI&benchmark=Public_AR_Current&format=json','https://www.rhodeislandmagic.com/copy-of-summer-camp-2026']::text[], '2026-11-13', '2026-11-13', TRUE)
INSERT INTO camps (name, operator_name, website_url, registration_url, email, phone, street_address, city, state, zip, region, camp_type, primary_categories, secondary_categories, activities, gender_policy, age_min, age_max, grade_min, grade_max, description_short, indoor_outdoor, religious_affiliation, price_min, price_max, price_per_week, price_per, extended_care, transportation, meals_included, financial_aid, refund_policy_summary, special_needs_notes, swim_waterfront_notes, aca_accredited, aca_source_url, season_year, id, slug, location, is_day_camp, is_sleepaway, is_specialty, stem_focus, arts_focus, sports_focus, nature_focus, verification_status, sources, last_reviewed_date, last_updated_date, is_active) VALUES
('RISD Art Camp (Youth Full-Day Camps)', 'Rhode Island School of Design Continuing Education (RISD CE)', 'https://ce.risd.edu/youth-full-day-camps/', NULL, 'risdce@risd.edu', '401 454-6200', NULL, 'Barrington', 'RI', '02806', 'Providence, RI', 'day', ARRAY['arts']::text[], NULL, ARRAY['2D art','3D art','Collaborative group art projects','Nature walks on the beach and in the woods','Outdoor recreation','Friday art show']::text[], NULL, 6, 12, NULL, NULL, 'A week-long, full-day art camp for ages 6–8 and 9–12 at Tillinghast Place in Barrington, RI. Mornings are guided 2D and 3D art lessons, and the day also includes nature walks, outdoor recreation and a Friday art show for families.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, 'If a camper needs accommodation for physical, emotional, mental or social needs, families should contact the CE main office before registering so the camp can check whether it can meet those needs. Non-emergency medications cannot be given at camp. Emergency medications must come in their original labeled packaging with a doctor-signed action plan.', 'Campers visit the beachfront but do not swim in the water.', NULL, NULL, 2026, '414e6b6e-e913-50a0-8182-7c8cf2573f95', 'risd-art-camp-youth-full-day-camps-barrington', ST_GeogFromText('SRID=4326;POINT(-71.309 41.7412)'), TRUE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://ce.risd.edu/youth-full-day-camps/','https://www.census.gov/geographies/reference-files/time-series/geo/relationship-files.2020.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Rock Spot Climbing Youth Adventure Programs (Lincoln, RI)', 'Rock Spot Climbing', 'https://rockspotclimbing.com/youthadventure/', 'https://climber.hellocapitan.com/rockspot/schedule/events/97/?day=2026-06-22&categories=62', 'Questions@rockspotclimbing.com', '401-727-1704', '100 Higginson Ave', 'Lincoln', 'RI', '02865', 'Providence, RI', 'specialty', ARRAY['sports']::text[], ARRAY['adventure','outdoor']::text[], ARRAY['Indoor rock climbing','Outdoor rock climbing']::text[], NULL, 6, NULL, NULL, NULL, 'Week-long indoor and outdoor rock climbing programs for kids during summer and school vacations, booked through Rock Spot''s Lincoln, RI gym (Providence gym camps also run through Lincoln). Indoor programs are for ages 6 and up, outdoor programs for ages 10 and up. All equipment is provided and no climbing experience is needed.', 'both', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'f53d12a8-4f93-5b29-83fc-c3017b9c086b', 'rock-spot-climbing-school-vacation-and-summer-youth-adventure-programs', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://rockspotclimbing.com/locations/ri/lincoln/','https://rockspotclimbing.com/youthadventure/']::text[], '2026-11-13', '2026-11-13', TRUE),
('RWU''s Forensic Science Summer Camp', 'Roger Williams University', 'https://www.rwu.edu/summer-camps/forensic-science-summer-camp', 'https://connect.rwu.edu/register/?id=791809ee-3c91-47f7-b9cd-7f3b24141bb4', 'summer@rwu.edu', '1-800-458-7144', '1 Old Ferry Road', 'Bristol', 'RI', '02809', 'Providence, RI', 'specialty', ARRAY['STEM','academic']::text[], NULL, ARRAY['Fingerprint analysis','Footwear and tire impression evidence','Forensic chemistry / unknown substance analysis','Virtual reality crime scene processing','Bloodstain pattern analysis in VR','Recreation center','Sailing center','Kayaking']::text[], NULL, NULL, NULL, 10, 12, 'A one-week overnight forensic science camp at Roger Williams University for students entering or in grades 10–12. Students work with RWU forensic scientists on fingerprinting, footwear evidence, chemical analysis and crime scenes in virtual reality, and can use campus recreation and waterfront facilities.', NULL, NULL, 1995, 1995, NULL, 'session', NULL, NULL, TRUE, NULL, 'A $500 deposit is due at registration and is fully refundable before April 1. The remaining balance is due by May 1. (The camp page still prints these deadlines as April 1, 2026 and May 1, 2026; the 2027 registration form says only ''refundable before April 1''.)', NULL, 'Campers have access to the recreation center, sailing center, kayaks and the RWU waterfront. The page does not describe swim testing or supervision.', NULL, NULL, 2027, '6d9e13c5-7fb2-507b-ad82-9cd16e2c208b', 'rwu-s-forensic-science-summer-camp-bristol', ST_GeogFromText('SRID=4326;POINT(-71.2673 41.6771)'), FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://connect.rwu.edu/register/?id=791809ee-3c91-47f7-b9cd-7f3b24141bb4','https://www.rwu.edu/summer-camps/forensic-science-summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('SEA by the Bay: Summer Engineering Academy', 'Roger Williams University', 'https://www.rwu.edu/summer-camps/sea-bay', 'https://connect.rwu.edu/register/?id=9d947566-bf5c-4194-9623-7a2d4a9342d3', NULL, '1-800-458-7144', '1 Old Ferry Road', 'Bristol', 'RI', '02809', 'Providence, RI', 'sleepaway', ARRAY['STEM']::text[], NULL, ARRAY['Engineering design challenges','3D modeling','Electronics','Prototype building and testing','Boat tour','Coastal field trips','Team project showcase']::text[], NULL, NULL, NULL, 11, 12, 'A one-week residential engineering camp on Roger Williams University''s waterfront campus in Bristol for high school juniors and above. Teams design, build and test coastal-themed prototypes, learning 3D modeling and electronics with RWU engineering professors, with afternoon activities such as a boat tour and coastal field trips and a final team showcase. Cost includes tuition and room and board.', NULL, NULL, 1995, 1995, NULL, 'session', NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '9bf6f65f-528c-50f2-96f5-1c2db2b6db8a', 'sea-by-the-bay-summer-engineering-academy-bristol', ST_GeogFromText('SRID=4326;POINT(-71.2673 41.6771)'), FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.rwu.edu/summer-camps','https://www.rwu.edu/summer-camps/sea-bay']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Art Camps for Kids', 'Westport Art Group', 'https://www.westportartgroup.com/summer-art-camps', NULL, 'info@westportartgroup.com', '508-636-2114', '1740 Main Road', 'Westport Point', 'MA', '02791', 'Providence, RI', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['Art']::text[], NULL, 7, 11, NULL, NULL, 'A week-long art camp for children ages 7-11, run by the Westport Art Group at its building in Westport Point, MA. All materials are included, and each session takes up to 12 campers.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You pay the full fee when you register. If you withdraw at least 1 month before camp and the spot is filled from the waiting list, you get a full refund minus a $10 processing fee. If you cancel less than 1 month before, there is no refund unless the spot is filled from the waiting list, and then you get 75% back. If WAG cancels a camp, you get a full refund.', NULL, NULL, NULL, NULL, 2026, '8bf9e692-5265-5bb3-be19-d9004853987f', 'summer-art-camps-for-kids-westport-point', ST_GeogFromText('SRID=4326;POINT(-71.0867 41.5182)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.westportartgroup.com/summer-art-camps']::text[], '2026-11-13', '2026-11-13', TRUE),
('Johnston Recreation Summer Day Camp', 'Johnston Recreation Department', 'https://johnstonrec.com/day-camp', NULL, 'johnstonyouthsports@gmail.com', '401-272-3460', 'Johnston Memorial Park, 1583 Hartford Ave', 'Johnston', 'RI', '02919', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['sports','arts']::text[], ARRAY['group games','sports games','playground','arts and crafts','water play (sprinklers, splash pad, inflatable waterslide)','tennis','field trips (extra cost)']::text[], NULL, 6, 12, NULL, NULL, 'Johnston Recreation Department''s six-week summer day camp at Johnston Memorial Park for ages 6 to 12, Monday to Friday 8:30am to 4:30pm, with group games, sports, arts and crafts, playground time and afternoon water play, plus optional field trips 2 to 3 times a week at extra cost. Families can sign up for the whole summer, single weeks or single days.', 'outdoor', NULL, 75, 975, 250, 'week', NULL, NULL, NULL, NULL, '$100 per family due at registration to hold a spot; balance due by July 1. Once camp begins, no refunds without a doctor''s note (prorated). Field trips cost extra and are non-refundable without a doctor''s note.', NULL, 'No swimming listed; most afternoons have water play (sprinklers, splash pad, inflatable waterslide).', NULL, NULL, 2026, 'b7b14b5e-a77e-5f70-a17b-b36623790049', 'summer-day-camp', ST_GeogFromText('SRID=4326;POINT(-71.5068 41.8218)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://img1.wsimg.com/blobby/go/08eb0b44-c11a-49c3-be03-2310cc6926c6/downloads/9061d9ae-655a-40f5-8be6-31ddb1bc85b7/Camp%20Parent%20Packet%20-%202026.pdf?ver=1793887585123','https://johnstonrec.com/day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Elements (Nature Camp & Adventure Camp)', 'Elements Learning Collaborative', 'https://www.elementslearning.org/summer', NULL, 'info@elementslearning.org', '508-441-4660', '92 Allen''s Neck Rd.', 'South Dartmouth', 'MA', '02748', 'Providence, RI', 'day', ARRAY['nature','arts','STEM']::text[], NULL, ARRAY['Gardening and vegetable picking','Composting','Feeding livestock and chickens','Tree climbing','Hiking and survival skills','Foraging','Natural dyeing','Woodworking','Nature journaling and paper making','Sculpture with natural materials','Bird and insect study','Tree identification']::text[], NULL, 5, 13, NULL, NULL, 'Outdoor drop-off nature day camp at Round The Bend Farm in South Dartmouth, MA, running Tuesday to Thursday, 9am to 3pm. Nature Camp (ages 5-9) and Adventure Camp (ages 9-13) each have a different weekly theme, such as insects, foraging, woodworking or nature journals.', 'outdoor', NULL, 215, 270, 250, 'week', NULL, NULL, NULL, TRUE, 'A $50 deposit per session per child is due at registration. It is non-refundable and counts toward the total cost. The rest is due by June 12. If you cancel more than 4 weeks before the session starts, you get a refund minus the $50 deposit. If you cancel within 4 weeks of the start, there is no refund.', NULL, NULL, NULL, NULL, 2026, 'ecb716f5-3b6a-5324-9d2c-d7fe21f6e3b8', 'summer-elements-nature-camp-and-adventure-camp-south-dartmouth', ST_GeogFromText('SRID=4326;POINT(-70.9582 41.5665)'), TRUE, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, 'unverified', ARRAY['https://www.elementslearning.org/contact','https://www.elementslearning.org/summer']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Friends', 'Friends Academy', 'https://www.friendsacademy1810.org/summer/summer-friends-day-camp-dartmouth-ma/', 'https://friendsacademysummerprograms.campbrainregistration.com/', 'summerfriends@friendsacademy1810.org', '(508) 999-1356', '1088 Tucker Rd.', 'North Dartmouth', 'MA', '02747', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['sports','arts','nature','STEM']::text[], ARRAY['crafts','sports','music','water play','science experiments','nature exploration','Challenge Course','field trips','guest presentations']::text[], NULL, 3, 16, 0, 8, 'A general day camp on the Friends Academy campus in North Dartmouth, MA. Campers are grouped by grade and do crafts, sports, music, water play, science and nature activities, with a weekly theme and either a field trip or a guest presentation. There is a preschool program (Little Friends, ages 3-4) and a three-week Counselor in Training program for ages 14-16.', NULL, NULL, 300, 450, 450, 'week', TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '1fa112d6-7dc8-5df4-9dbc-f63bfa0ce644', 'summer-friends-north-dartmouth', ST_GeogFromText('SRID=4326;POINT(-70.9582 41.5665)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.friendsacademy1810.org/summer/','https://www.friendsacademy1810.org/summer/summer-friends-day-camp-dartmouth-ma/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Playground Camp', 'City of Cranston Parks and Recreation Department', 'https://www.cranstonri.gov/departments/parks-and-recreation/default.aspx', 'https://docs.google.com/forms/d/e/1FAIpQLSeP--Oygq7XdMcUP5Fg9tl_a_jwLryz3KnHpYbI9snwPeYvOA/viewform', 'cranstonparksandrecreation@cranstonri.org', '401-461-1000', '155 Gansett Avenue', 'Cranston', 'RI', '02910', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['swimming']::text[], ARRAY['Field trips (bowling, roller skating, Spring Lake, Top Golf)','Pool days at Budlong Pool','Performers (magicians, comedians, musicians)','Field days','Playground games']::text[], NULL, 6, 12, NULL, NULL, 'A 6-week city-run day program for Cranston residents ages 6-12, held rain or shine at four playground sites and built around field trips and activities. Campers bring their own lunch and must be picked up by 4:00pm.', NULL, NULL, 165, 175, 175, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '68289e76-f49d-5897-9e6e-fdb00dadfba4', 'summer-playground-camp-cranston', ST_GeogFromText('SRID=4326;POINT(-71.4373 41.7798)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://docs.google.com/spreadsheets/d/1Bciofwv45dXBb68f5rnoHzw9GYcxtHbpxRqw4V6Rkn4/edit?gid=1767944116','https://geocoding.geo.census.gov/geocoder/locations/address?street=155+Gansett+Avenue+%28Recreation+Office%2C+Peter+Pastore+Youth+Center%29&city=Cranston&state=RI&benchmark=Public_AR_Current&format=json','https://www.cranstonri.gov/departments/parks-and-recreation/default.aspx']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Playground Program (SPP)', 'North Attleborough Parks & Recreation', 'https://www.northattleborough.gov/252/Programs-by-Season', 'https://northattleboroughma.myrec.com/info/default.aspx', 'parkandrec@nattleboro.com', '508-699-0100 Ext. 2647', 'Community Field and Playground, 45 South Washington Street', 'North Attleborough', 'MA', '02760', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['Playground program']::text[], NULL, NULL, NULL, 1, 6, 'An 8-week town summer playground program at Community Field in North Attleborough, 9 am to 3:30 pm, for North Attleboro residents entering grades 1-6, limited to 250 full-time participants, with a 10-day drop-in option. SPP2 is a similar program for residents entering grades 7-8.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'efd2c9d9-d12a-533e-94aa-f146f5fdd153', 'summer-playground-program-spp-north-attleborough-2', ST_GeogFromText('SRID=4326;POINT(-71.3295 41.9834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://northattleboroughma.myrec.com/info/activities/program_details.aspx?ProgramID=30925','https://northattleboroughma.myrec.com/info/facilities/details.aspx?FacilityID=14701','https://www.northattleborough.gov/252/Programs-by-Season']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Sage', 'The Sage School', 'https://sageschool.org/program/summer-sage/', NULL, 'cgorea@sageschool.org', '(508) 543-9619', '171 Mechanic Street', 'Foxboro', 'MA', '02035', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, NULL, NULL, 3, NULL, NULL, 5, 'A summer program at The Sage School in Foxboro, MA, with weekly themes, for children ages 3–4 through Grade 5. Children who don''t attend Sage can enroll, and extended care is offered.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '435b9f31-31d1-59c1-9bb2-b853a38f94a1', 'summer-sage-foxboro', ST_GeogFromText('SRID=4326;POINT(-71.2458 42.0613)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://sageschool.org/program/summer-sage/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Studio', 'Mount Saint Charles Academy', 'https://mountsaintcharles.org/arts/summer-studio/', NULL, NULL, '401-769-0310', '800 Logee Street', 'Woonsocket', 'RI', '02895', 'Providence, RI', 'specialty', ARRAY['arts','performing_arts']::text[], NULL, ARRAY['dance','steel drums','architecture','Dungeons & Dragons','ceramics','LEGO design','creative writing','sculpture','digital art','drama']::text[], NULL, NULL, NULL, 4, 12, 'A one-week, hands-on arts program at Mount Saint Charles Academy for students in grades 4-12. Campers rotate through four studios per session, chosen from options such as dance, steel drums, architecture, D&D, ceramics, LEGO design, creative writing, sculpture, digital art and drama.', NULL, NULL, 250, 500, 250, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '591f3cc9-afbb-5061-9861-79d5ae3c7779', 'summer-studio-woonsocket', ST_GeogFromText('SRID=4326;POINT(-71.5148 42.0026)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://mountsaintcharles.org/arts/summer-studio/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Wild Adventure Programs', 'EARTH ltd', 'https://www.earthltd.org/wild-adventure-programs/summer/', NULL, 'earthltdsummerprogram@gmail.com', NULL, '67 Vineyard Street', 'Millville', 'MA', '01529', 'Providence, RI', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Animal encounters and interactions','Building enrichment for zoo animals','Behind-the-scenes animal care','Educational games','Art-based activities','Whale watch (High School Teen Zoology)']::text[], NULL, NULL, NULL, 0, 11, 'Week-long half-day and full-day zoo programs for grades K-11, run by EARTH ltd with Southwick''s Zoo. Licensed educators lead each week, which covers one animal theme through animal encounters, building enrichment for zoo animals, behind-the-scenes care, games and art.', 'outdoor', NULL, 188.58, 743.46, NULL, 'session', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'd6843e36-d803-50cd-9d06-bb7fd27a1856', 'summer-wild-adventure-programs-millville', ST_GeogFromText('SRID=4326;POINT(-71.5809 42.0279)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://www.earthltd.org/wild-adventure-programs/summer/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Youth Sailing Program', 'Community Boating Center, Inc.', 'https://www.communityboating.org/project/summer-youth-sailing-program/', 'https://campscui.active.com/orgs/CommunityBoatingCenter?season=3780946&sessionType=168801', 'cbc@communityboating.org', '(508) 992-6219', '1641 Padanaram Avenue', 'New Bedford', 'MA', '02740', 'Providence, RI', 'specialty', ARRAY['sailing']::text[], ARRAY['swimming']::text[], ARRAY['Sailing','Windsurfing','Swimming','Water safety','Games','Reading/literacy activities (Sea Squirts)']::text[], NULL, 5, 17, NULL, NULL, 'Summer sailing and windsurfing classes for ages 5-17 at Community Boating Center on Padanaram Avenue in New Bedford, held rain or shine: one-week Summer Youth Sailing (ages 7-17, 8:30-2:45), one-week Sea Squirts (ages 5-6, mornings, with sailing, games, swimming and a literacy activity) and two-week Windsurfing (ages 9-17). Up to two sessions per sailor; free breakfast and lunch; financial aid for those who qualify.', NULL, NULL, 250, 500, NULL, 'session', NULL, NULL, TRUE, TRUE, 'Cancel 30+ days before the course: refund less a 25% administrative fee; 15 to 29 days: less 50%; within 14 days: no refund.', NULL, 'On-the-water program held rain or shine; students should come prepared to get wet. Closed-toe shoes (water shoes or old sneakers) are mandatory; bring a bathing suit, towel and change of clothes. Sea Squirts (ages 5-6) mixes sailing, games and swimming, with a focus on water safety. Staff limit on-the-water activity when they judge conditions unsafe.', NULL, NULL, 2026, '8bac250c-5c6a-53de-86b1-2cf4cf4cc500', 'summer-youth-sailing-program-new-bedford', ST_GeogFromText('SRID=4326;POINT(-70.9379 41.6613)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.communityboating.org/project/summer-youth-sailing-program/','https://www.communityboating.org/wp-content/uploads/2026/02/SYSP-2026-Application-English.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Taste Buds Kitchen East Greenwich – Kids Summer Cooking Camps', 'Taste Buds Kitchen', 'https://tastebudskitchen.com/east-greenwich/kids-cooking-camps/', 'https://tastebudskitchen.com/east-greenwich/kids-cooking-camps/', NULL, '(401) 885-0535', '5600 Post Road, Unit #110', 'East Greenwich', 'RI', '02818', 'Providence, RI', 'specialty', NULL, NULL, ARRAY['Cooking','Baking','Knife skills','Kitchen games & challenges','Recipe reading','Food styling (teens)']::text[], NULL, 4, 17, NULL, NULL, 'Indoor cooking and baking day camp for ages 4-17. Each week runs Monday to Friday with a new theme, as 3-hour morning (ages 4-8) or afternoon (ages 9-13) sessions, and kids take home food samples.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, 'All sales are final and non-refundable. You can reschedule yourself up to 5 days before the start time, but not within 5 days. Optional Camp Protection, bought at booking, lets you cancel for any reason up to 5 hours before the first class and get a kitchen credit for the ticket amount (minus protection and processing fees). The credit is valid for 6 months.', 'All menus are nut-free. Camp menus have no gluten, dairy or egg substitutions, and the kitchen is not allergy-free. Kids with allergies may bring their own nut-free portion that needs no heating or preparation.', NULL, NULL, NULL, 2027, 'd50d2807-3409-5ab8-bd69-96abf22ef22a', 'taste-buds-kitchen-east-greenwich-kids-summer-cooking-camps-east-greenwich', ST_GeogFromText('SRID=4326;POINT(-71.4601 41.6601)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://tastebudskitchen.com/east-greenwich/kids-cooking-camps/']::text[], '2026-11-13', '2026-11-13', TRUE),
('The Adirondack Club Summer Camps', 'The Adirondack Club', 'https://www.adirondackclub.com/camps', NULL, 'memberservices@adirondackclub.com', '(508) 541-1400', '800 Chestnut Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'day', ARRAY['general']::text[], ARRAY['sports','arts','adventure','swimming']::text[], ARRAY['Sports','Arts','Adventure']::text[], NULL, 5, 14, NULL, NULL, 'Summer day camps at The Adirondack Club, a fitness and family club in Franklin, MA: Adventure Camp (ages 5-14 in four age groups), Arts Camp and Sports Camp, which families can mix and match. Camp runs 8:45am to 3:45pm with pre-camp from 7:30am and post-camp to 6pm, and uses the club''s pools, indoor space and outdoor play areas.', 'both', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, 'The club has a 6-lane lap pool and a large shallow-entry recreation pool for younger campers; campers bring a bathing suit and towel daily.', NULL, NULL, 2026, '93d2f88f-9321-536c-af76-5b2168c60b3c', 'the-adirondack-club-summer-camps', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.adirondackclub.com/adventure-camp','https://www.adirondackclub.com/camp-policies-and-forms','https://www.adirondackclub.com/camps','https://www.adirondackclub.com/contact-us']::text[], '2026-11-13', '2026-11-13', TRUE),
('Theater Camp in Lincoln Woods State Park', 'Studio Playground', 'https://www.studioplayground.org/summercamp', NULL, 'info@studioplayground.org', NULL, '2 Manchester Print Works Road', 'Lincoln', 'RI', '02865', 'Providence, RI', 'specialty', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Theater games','Acting and improvisation','Arts and crafts','Prop and costume making (Craft & Create)','Outdoor performance','Nature walks','Theme days (water day, costume day, camp olympics)']::text[], NULL, 5, 12, NULL, NULL, 'An outdoor theater day camp for ages 5-12 in Lincoln Woods State Park, 8:30am-3:30pm. Campers play theater games, rehearse, design props and costume pieces in the Craft & Create program, and each week ends with an outdoor performance. Two separate weeks in summer 2027.', 'outdoor', NULL, 395, 475, 475, 'week', FALSE, NULL, FALSE, TRUE, NULL, NULL, 'No swimming during camp. The park has a beach with lifeguards, and families can swim there after pickup (lifeguards are on duty until 6pm).', NULL, NULL, 2027, '7dca1335-c82b-5714-879d-1b84361acbdc', 'theater-camp-in-lincoln-woods-state-park-lincoln', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.studioplayground.org/summercamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('To The Pointe Summer Dance', 'To The Pointe Dance Studios', 'https://tothepointedancestudios.com/summerdance', 'https://tothepointedancestudios.com/summer-camps', 'contact@tothepointedancestudios.com', '401-942-5554', '800 Oaklawn Ave', 'Cranston', 'RI', '02920', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Dance (hip hop, jazz, ballet, pom)','Musical theatre','Themed crafts','Games','Friday showcase performance']::text[], NULL, 3, NULL, NULL, NULL, 'Weekly themed dance camps at To The Pointe Dance Studios in Cranston, RI, for ages 3 and up, grouped by age and taught by studio dance teachers. Campers learn routines (hip hop, jazz, ballet, pom), make themed crafts and perform a showcase for families on Friday. Half day 9am-12pm or full day 9am-3pm; no experience needed.', NULL, NULL, 229, 299, NULL, 'week', NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'c923fbdd-fa5d-5bf7-807e-267dd66dc597', 'to-the-pointe-summer-dance-cranston', ST_GeogFromText('SRID=4326;POINT(-71.4373 41.7798)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://tothepointedancestudios.com/locations-2-1','https://tothepointedancestudios.com/summer-camps','https://tothepointedancestudios.com/summerdance']::text[], '2026-11-13', '2026-11-13', TRUE),
('United We Row Youth Summer Rowing', 'Watuppa Rowing Center', 'https://www.watupparowingcenter.org/summer-rowing', NULL, 'Row@WatuppaRowingCenter.org', NULL, '994 Jefferson Street Extension', 'Fall River', 'MA', '02721', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Rowing']::text[], NULL, 12, NULL, 6, 12, 'Free youth rowing at the Watuppa Rowing Center in Fall River for students aged 12 and older in grades 6-12, sponsored by the United Way of Greater Fall River. Sessions run Monday to Friday, 8 am to 12 noon, and athletes can join any and as many sessions as they like.', NULL, NULL, 0, 0, 0, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2027, '6ca06b28-fa3d-5b4a-ab08-4c3f7fc48df6', 'united-we-row-youth-summer-rowing', ST_GeogFromText('SRID=4326;POINT(-71.155 41.7015)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=994+Jefferson+Street+Extension&city=Fall+River&state=MA&benchmark=Public_AR_Current&format=html','https://www.watupparowingcenter.org/contact','https://www.watupparowingcenter.org/summer-rowing']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp MacColl', 'YMCA of Pawtucket', 'https://ymcapawtucket.org/camps/camp-maccoll', 'https://ymcapawtucket.org/camps/activity-finder', 'maccoll@ymcapawt.org', '(401) 725-0773', '32 Breakneck Hill Rd', 'Lincoln', 'RI', '02865', 'Providence, RI', 'day', ARRAY['sports','arts','nature']::text[], ARRAY['swimming','adventure']::text[], ARRAY['archery','art','swimming','nature','sports','gaga ball','traverse wall','kangaroo jumper','Specialty camps (art, basketball, culinary, nature, ninja, pickleball, soccer, sports medley)','Immersive theme camps (Disney, Harry Potter, Pirates, Super Mario, Star Wars, Survivor)','Leaders in Training (ages 13-15)','Voyagers travel camp (ages 12-15)']::text[], NULL, 5, 15, NULL, NULL, 'A YMCA of Pawtucket day camp in Lincoln, RI for ages 5-15. Traditional camp groups campers by age (5-13) for archery, art, swimming, nature and sports; specialty and themed immersive weeks, a Leaders in Training program (13-15) and Voyagers travel camp (12-15) are also offered. Before and after care available.', NULL, NULL, 275, 295, 285, 'week', TRUE, NULL, NULL, NULL, '$25 non-refundable registration fee for all camps. Early-bird weekly rates through January 31.', NULL, NULL, NULL, NULL, 2026, 'f1fbbcc3-1ab0-5d22-bd9b-17d072671f13', 'ymca-camp-maccoll-lincoln', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://ymcapawtucket.org/camps/camp-maccoll','https://ymcapawtucket.org/camps/camp-maccoll-day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('YMCA Camp Westwood', 'YMCA of Pawtucket', 'https://ymcapawtucket.org/camps/camp-westwood', 'https://ymcapawtucket.campbrainregistration.com/', 'westwood@ymcapawt.org', '(401) 397-7779', '2093 Harkney Hill Road', 'Coventry', 'RI', '02816', 'Providence, RI', 'day', ARRAY['sports','nature']::text[], NULL, ARRAY['High ropes course','Canoeing','Kangaroo jumper','Waterfront/swimming','Sailing','Laser tag','Carpet ball','Soccer','Basketball','STEM','Team building','Playground','Gaga ball','Mini golf','Giant slingshot','Giant swing','Archery','Crafts']::text[], NULL, 4, 16, NULL, NULL, 'A YMCA camp on 87 lakefront acres in Coventry, RI. Campers are grouped by age and spend the day outdoors doing things like lake swimming, high ropes and crafts. Traditional, themed (immersive) and specialty programs are offered.', NULL, NULL, 260, 375, 355, 'week', TRUE, TRUE, TRUE, NULL, NULL, NULL, 'Lakefront camp with lake swimming, canoeing and sailing. The page does not describe swim tests or lifeguard supervision.', NULL, NULL, 2026, '9f3e3bce-a5a6-5113-ba27-0300838743a1', 'ymca-camp-westwood-coventry', ST_GeogFromText('SRID=4326;POINT(-71.6828 41.7001)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 'unverified', ARRAY['https://ymcapawtucket.org/camps/camp-westwood','https://ymcapawtucket.org/camps/camp-westwood/day-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('You Rock Summer Camp', 'You Rock School of Music', 'https://www.yourockschoolofmusic.com', 'https://yourockschoolofmusic.opus1.io/w/summercamp2026', 'info@yourockschoolofmusic.com', '401.481.4297', '1802 Broad Street', 'Cranston', 'RI', '02905', 'Providence, RI', 'specialty', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Band formation','Songwriting','Rehearsal','Live performance','Jam sessions','Guitar','Bass','Drums','Piano','Voice','Tie-dye','Games','Creative challenges']::text[], NULL, NULL, NULL, NULL, NULL, 'A week-long rock band camp at You Rock School of Music in Cranston, RI, for kids of all experience levels. Campers form bands, name them, write original songs, rehearse and perform live at a Friday show, with tie-dye, games and jam sessions along the way. 2026 camp was 6 hours a day at $489 per week.', NULL, NULL, 489, 489, 489, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'e214825f-8ef4-5005-8ee7-70f77c75a9b1', 'you-rock-summer-camp-cranston', ST_GeogFromText('SRID=4326;POINT(-71.4373 41.7798)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.yourockschoolofmusic.com/summer-camp2026','https://yourockschoolofmusic.opus1.io/w/summercamp2026']::text[], '2026-11-13', '2026-11-13', TRUE),
('Young Actors Summer Institute (YASI)', 'Trinity Repertory Company', 'https://www.trinityrep.com/education/yasi/', NULL, 'education@trinityrep.com', '(401) 521-1100', '201 Washington Street', 'Providence', 'RI', '02903', 'Providence, RI', 'specialty', ARRAY['performing_arts']::text[], NULL, ARRAY['Musical theater','Improv & comedy','Stage combat and stage make-up (YASI Fight & Make-Up)','One-act plays','Acting scene work']::text[], NULL, NULL, NULL, 1, 12, 'Trinity Rep''s Young Actors Summer Institute: one-week summer theater camps, each on a different topic (musical theater, improv and comedy, fight and make-up, one acts and more), for students from first grade through recent high school graduates, led by local artists and educators. Take one week or mix and match several.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, '$50 non-refundable deposit to hold a spot. Full refund (less deposit and registration fees) if cancelled at least one week before the first day; 50% of tuition for later cancellations before the first session; no refund once the camp begins.', NULL, NULL, NULL, NULL, 2027, '750ae656-453e-5c37-a5a7-1325c14d56b0', 'young-actors-summer-institute-yasi-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.trinityrep.com/class-cancellation-policy/','https://www.trinityrep.com/education/yasi/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Young Naturalist Summer Program', 'Lloyd Center for the Environment', 'https://lloydcenter.org/young-naturalist/', NULL, 'Summer@lloydcenter.org', NULL, '430 Potomska Road', 'Dartmouth', 'MA', '02748', 'Providence, RI', 'day', ARRAY['nature','STEM']::text[], NULL, ARRAY['Hands-on games','Crafts','Trail walks','Scavenger hunts','Salt water habitat exploration','Pond and stream exploration','Bird and winged creature study','STEAM projects (Fridays)']::text[], NULL, 6, 9, NULL, NULL, 'A weekly outdoor nature day program for children ages 6-9, running 9:30 am-2:30 pm. Each day has a theme (Under the Sea, In the Sky, Forest Frenzy, Ponds & Streams), and Fridays are STEAM projects.', NULL, NULL, 320, 450, 450, 'week', NULL, NULL, NULL, NULL, 'Refund or cancellation requests must be made in writing to Summer@lloydcenter.org by June 12, 2026. The $50 deposit paid at registration is non-refundable.', NULL, NULL, NULL, NULL, 2026, 'fd2a6bfd-0677-5d39-a840-12a3791d881f', 'young-naturalist-summer-program-dartmouth', ST_GeogFromText('SRID=4326;POINT(-70.9582 41.5665)'), TRUE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://lloydcenter.org/young-naturalist/']::text[], '2026-11-13', '2026-11-13', TRUE),
('ZooCrew at Buttonwood Park Zoo', 'Buttonwood Park Zoological Society', 'https://www.bpzoo.org/education-and-conservation/for-families/zoocrew/', 'https://bpzoo.ticketapp.org/portal/product/26/events', 'cdoremus@bpzoo.org', '508-991-4556', '425 Hawthorn Street', 'New Bedford', 'MA', '02740', 'Providence, RI', 'day', ARRAY['nature']::text[], ARRAY['STEM']::text[], ARRAY['Crafts','Games','Animal encounters','Nature Play recess','Citizen science projects']::text[], NULL, 4, 12, NULL, NULL, 'Summer ZooCrew is a week-long day camp at Buttonwood Park Zoo in New Bedford for ages 4 to 12 in four age groups, with a different animal or nature theme each week. Days run 9am to 4pm (half day 9 to noon for ages 4-5) with crafts, games, activities, animal encounters and recess in the Nature Play area. Lunch can be bought for $10 a day or packed.', 'outdoor', NULL, 175, 350, 350, 'week', NULL, NULL, FALSE, TRUE, 'Cancellations are accepted until the week before your child''s start date. After that there are no refunds, except for cancellations due to a Covid diagnosis.', NULL, NULL, NULL, NULL, 2026, 'b61d79e7-277b-5ed6-b355-9f1c8506985b', 'zoocrew-at-buttonwood-park-zoo-new-bedford', ST_GeogFromText('SRID=4326;POINT(-70.9379 41.6613)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, TRUE, 'unverified', ARRAY['https://bpzoo.ticketapp.org/portal/product/26/events','https://www.bpzoo.org/education-and-conservation/for-families/zoocrew/']::text[], '2026-11-13', '2026-11-13', TRUE),
('COZ Summer Camp', 'Bristol Warren Regional School District (Bristol Warren Family Resource Center, COZ Program)', 'https://www.bwrsd.org/families1/family-resource-center/coz-summer-camp', NULL, 'Amy.Bratsos@bwrsd.org', '(401) 245-1460 ext. 8076', 'Hugh Cole Elementary School, 50 Asylum Road', 'Warren', 'RI', '02885', 'Providence, RI', 'day', ARRAY['arts','sports','STEM','nature']::text[], NULL, ARRAY['art','music','science','sports','community service','fitness','gardening','reading']::text[], NULL, 5, NULL, 0, 6, 'A school-district day camp at Hugh Cole Elementary School in Warren, RI, for children entering kindergarten through grade six. Campers do art, music, science, sports, community service, fitness, gardening and reading. Families can sign up for one day, one week or the whole summer.', NULL, NULL, 47, 58, NULL, 'day', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '9d0397d7-23d0-5ab5-8ef3-060fabae6f1f', 'coz-summer-camp-warren', ST_GeogFromText('SRID=4326;POINT(-71.2823 41.7301)'), TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, 'unverified', ARRAY['https://www.bwrsd.org/families1/family-resource-center/contact-us','https://www.bwrsd.org/families1/family-resource-center/coz-summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Episcopal Conference Center (ECC) Summer Camp', 'Episcopal Diocese of Rhode Island', 'https://www.eccri.org/', NULL, 'ally@eccri.org', '(401) 568-4055', '872 Reservoir Road', 'Pascoag', 'RI', '02859', 'Providence, RI', 'sleepaway', ARRAY['faith']::text[], NULL, ARRAY['singing','swimming','campfires','dancing']::text[], NULL, NULL, NULL, NULL, NULL, 'Episcopal church summer camp and retreat center on Echo Lake in Pascoag, Rhode Island, run with support from the Diocese of Rhode Island for over 75 years. Details for Summer 2027 have not been posted yet.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, 'Camp is on Echo Lake. Swimming is listed as an activity, but no details about the waterfront are given.', NULL, NULL, 2027, '3d6a7a6f-d5a1-5ba9-ba36-1c4077b02f6a', 'episcopal-conference-center-ecc-summer-camp-pascoag', ST_GeogFromText('SRID=4326;POINT(-71.7012 41.9554)'), FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.eccri.org/','https://www.eccri.org/aboutecc','https://www.eccri.org/pricingandscholarship','https://www.eccri.org/staff']::text[], '2026-11-13', '2026-11-13', TRUE),
('Narragansett Boat Club Youth Rowing Summer Camp', 'Narragansett Boat Club', 'https://rownbc.org/row-with-nbc/youth-rowing/summer-camp/', 'https://rownbc.org/product/summer-camp/', 'youthrowing@rownbc.org', '401-272-1838', '2 River Drive', 'Providence', 'RI', '02906', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Rowing']::text[], NULL, NULL, NULL, 6, NULL, 'A week-long rowing camp on the Seekonk River for beginner and intermediate youth rowers. It runs 9am–11am each weekday and is coached by varsity coaches, with current and former junior rowers on staff.', 'outdoor', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Rowing takes place on the water on the Seekonk River. The page does not state any swim test or swimming ability requirement.', NULL, NULL, 2026, '61f5243f-8812-543f-9d9f-0409ce5edfbc', 'narragansett-boat-club-youth-rowing-summer-camp-providence', ST_GeogFromText('SRID=4326;POINT(-71.4128 41.824)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://rownbc.org/product/summer-camp/','https://rownbc.org/row-with-nbc/youth-rowing/summer-camp/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Plainville Summer Recreation Program', 'Plainville Park Department', 'https://www.plainvillema.gov/281/Summer-Recreation-Program', 'https://forms.cloud.microsoft/g/xbzxCxnW7R', 'Plainvillepark@plainville.ma.us', '508-695-5451', '142 South Street', 'Plainville', 'MA', '02762', 'Providence, RI', 'day', ARRAY['sports','arts']::text[], ARRAY['swimming']::text[], ARRAY['sports','field games','court games','playground','swimming in the town pool','board games','arts and crafts','table games','library movie','story time','weekly field trips','weekly cookouts']::text[], NULL, NULL, NULL, 1, 8, 'A town-run summer day program for children entering grades 1-8, Monday-Friday 8:30 AM-4 PM at Plainville Town Park for 8 weeks, with before care from 7:30 and after care to 6. Sports, games, arts and crafts, daily swimming in the town pool, weekly cookouts and one field trip each week. Full weeks, single days and half days are offered.', NULL, NULL, 280, 280, 280, 'week', TRUE, NULL, NULL, TRUE, 'The $50 deposit per week per child is non-refundable. Cancelling a week requires at least one week''s notice; if you cancel later, you pay the full fee for the week(s) missed.', NULL, 'Daily pool time in the town pool is included in the weekly fee. The page gives no details on swim supervision or testing.', NULL, NULL, 2026, '4e80c2ba-672a-5fa4-952f-2e753b8494ca', 'plainville-summer-recreation-program-plainville', ST_GeogFromText('SRID=4326;POINT(-71.3328 42.0042)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.plainvillema.gov/240/Park-Department','https://www.plainvillema.gov/281/Summer-Recreation-Program']::text[], '2026-11-13', '2026-11-13', TRUE),
('Sail Newport Summer Youth Sailing Programs', 'Sail Newport', 'https://sailnewport.org/youth-sailing-programs/youth-instruction/', NULL, 'info@sailnewport.org', '(401) 846-1983', '72 Fort Adams Drive', 'Newport', 'RI', '02840', 'Providence, RI', 'specialty', ARRAY['sailing']::text[], NULL, ARRAY['Dinghy sailing','Keelboat sailing','Race training','Sailing games (Little Guppies)']::text[], NULL, 5, 17, NULL, NULL, 'Summer sailing classes for ages 5-17 at Fort Adams in Newport, RI. Two-week dinghy sessions (ages 7-17) and one-week keelboat sessions (ages 12-17) run from beginner to advanced, and Little Guppies is a short one-week introduction for 5- and 6-year-olds. Families apply online and are placed by experience, age and size.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, 'Once a student is accepted and paid: no obligation if they can''t attend at the payment deadline (usually March). Cancel before the mid-April cutoff (April 12 in the 2026 policy) for a refund minus a $30 fee; after that, a refund minus $50 only if the spot is filled, otherwise no refund.', NULL, 'Every child must pass a swim check at the start of each session: swim 20 yards and tread water for 2 minutes, wearing a life jacket. Life jackets must be worn at all times on the docks and in boats. Loaner life jackets are available for first-time sailors.', NULL, NULL, 2027, 'cb1b6d2d-672c-5430-895a-183db266bde3', 'sail-newport-summer-youth-sailing-programs-newport', ST_GeogFromText('SRID=4326;POINT(-71.3128 41.4901)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://sailnewport.org/youth-sailing-programs/youth-instruction/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Fun Program', 'Boys & Girls Club of Greater New Bedford', 'https://bgcnewbedford.org/programs/summer-fun-program-2/', 'https://visioncps.net/form/WRForm.asp?OrgUnit=1431/6', 'jsilva@bgcnewbedford.org', '(508) 992-8011', '166 Jenney St.', 'New Bedford', 'MA', '02744', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['Softball, flag football, relay races and water games','Basketball, volleyball, soccer, kickball and gym games','Billiards, table tennis and board games','Makerspace: coding, Scratch, digital art and music, 3D modeling and printing','Arts & crafts','Music','Gardening','Yoga','Cooking','Book club','Outdoor exploration','Financial literacy / Torch Club','Field trips (hikes, library, art tours, farm tours)']::text[], NULL, 7, 13, NULL, NULL, 'A weekday summer program (9am-4pm) at the Boys & Girls Club of Greater New Bedford, with outdoor games, gym sports, a games room, a makerspace (coding, digital art, 3D printing), arts and crafts, gardening, cooking and planned field trips. Children must be Club members.', NULL, NULL, 50, 50, 50, 'week', TRUE, NULL, NULL, NULL, 'No refunds. Weekly fees are charged at the full week''s rate regardless of how many days the child attends. Each week''s payment is due the Thursday before it starts.', NULL, NULL, NULL, NULL, 2026, 'ce651d18-6ba3-53c7-9f13-2aabd84b6f66', 'summer-fun-program-new-bedford', ST_GeogFromText('SRID=4326;POINT(-70.9379 41.6613)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://bgcnewbedford.org/contact-us/','https://bgcnewbedford.org/programs/summer-fun-program-2/','https://bgcnewbedford.org/programs/summer-fun-program/']::text[], '2026-11-13', '2026-11-13', TRUE),
('Teamworks Summer Camp (Somerset)', 'Teamworks/Indoor Sports LLC', 'https://www.teamworkssomerset.com/summercamphome.aspx', 'https://www.teamworkssomerset.com/upcomingsummerprogram.aspx', 'info@teamworkssomerset.com', '508.676.3939', '732 Lee''s River Avenue', 'Somerset', 'MA', '02725', 'Providence, RI', 'day', ARRAY['sports','arts','performing_arts']::text[], NULL, ARRAY['Multi-sport','Playground games','Traditional camp activities','Dance','Fashion','Arts & crafts','Jewelry making','Soccer','Flag football','Volleyball','Baseball','Basketball']::text[], NULL, 4, 14, NULL, NULL, 'A weekly day camp for ages 4–14 at the Teamworks indoor sports center in Somerset, MA. Options include a general sports and games camp (Cubs for ages 4–6, TW Camp for ages 7–14), TW Friends (dance, fashion, arts and crafts, jewelry) and sport-specialty camps for beginner and intermediate players.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'e716ca55-1694-510e-a119-c326a6e3873b', 'teamworks-summer-camp-somerset-somerset', ST_GeogFromText('SRID=4326;POINT(-71.1287 41.7695)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://www.teamworkssomerset.com/contactdirector.aspx?strContactDirectorType=EnumContactDirectorType.enumCampProgram','https://www.teamworkssomerset.com/summercamphome.aspx']::text[], '2026-11-13', '2026-11-13', TRUE),
('Warren Parks & Recreation Summer Camp', 'Town of Warren Parks & Recreation', 'https://www.townofwarren-ri.gov/departments/parks_recreation/summer_camp.php', 'http://warrenri.myrec.com', 'warrenrecreation@gmail.com', '401-824-4623', 'Burr''s Hill Park', 'Warren', 'RI', '02885', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['Arts & crafts','Games','Bowling','Weekly contests','Swimming','Camp performances','Field trips']::text[], NULL, 5, 14, NULL, NULL, 'The Town of Warren''s summer day camp at Burr''s Hill Park for ages 5-14, 9 am to 3 pm on weekdays from late June to mid-August, with extended hours from 7 am to 5 pm. An electronics-free camp with arts and crafts, games, bowling, weekly contests, swimming at the town beach, performances and field trips, and a free summer lunch program.', NULL, NULL, 200, 600, NULL, 'summer', TRUE, NULL, TRUE, TRUE, NULL, NULL, NULL, NULL, NULL, 2026, 'd1fc6d4a-7101-51d8-8326-3ec36ac8eff4', 'warren-parks-and-recreation-summer-camp-warren', ST_GeogFromText('SRID=4326;POINT(-71.2823 41.7301)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.census.gov/geographies/reference-files/time-series/geo/relationship-files.2020.html','https://www.townofwarren-ri.gov/departments/parks_recreation/index.php','https://www.townofwarren-ri.gov/departments/parks_recreation/summer_camp.php']::text[], '2026-11-13', '2026-11-13', TRUE),
('Wickford Sailing Association Summer Sailing Program', 'Wickford Sailing Association', 'https://wickfordsailing.org/', 'https://wickfordsailing.org/classes/', 'wsaprogramdirector@gmail.com', '(401) 372-7224', '165 Pleasant Street', 'North Kingstown', 'RI', '02852', 'Providence, RI', 'specialty', ARRAY['sailing']::text[], NULL, ARRAY['Sailing','Dinghy sailing','Opti racing','420 racing','Regattas','Marine STEM activities','Knots','Adult sailing']::text[], NULL, 5, 17, NULL, NULL, 'Summer sailing classes in Wickford (North Kingstown) for ages 5 to 17: half-day one-week Minnows (5.5-7.5), two-week Beginner and Beginner Plus, Intermediate, Adventure, and 8-week Opti and 420 racing teams that sail NBYA regattas, plus an adult class. Full-day classes run 9 am to 4 pm; the season runs June 22 to August 14.', NULL, NULL, 275, 1600, NULL, 'session', NULL, NULL, FALSE, TRUE, NULL, NULL, 'Every student takes a swim test on the first day (treading water in a life jacket for about 2 minutes). A US Coast Guard approved non-inflatable PFD and closed-toe shoes are required. Instructors are US Sailing Level 1 certified with CPR and First Aid.', NULL, NULL, 2026, 'f77b122c-033f-5e35-9e9d-3a06133d27fd', 'wickford-sailing-association-summer-sailing-program', ST_GeogFromText('SRID=4326;POINT(-71.4579 41.554)'), FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://wickfordsailing.org/','https://wickfordsailing.org/classes/','https://wickfordsailing.org/classes/minnows/','https://wickfordsailing.org/classes/opti-green/','https://wickfordsailing.org/contact/','https://wickfordsailing.org/policies-and-faqs/','https://wickfordsailing.org/wp-content/uploads/2025/06/1-WSA-Parent-handbook-2025-06-Google-Docs.pdf']::text[], '2026-11-13', '2026-11-13', TRUE),
('Camp LMNTREE', 'The Elemen-Tree House', 'https://www.elementreehouse.com/summer-camp', NULL, 'lmntree@verizon.net', '(508) 541-3998', '838 Upper Union Street', 'Franklin', 'MA', '02038', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['group games','free swim','arts and crafts','field trips','weekly theme-based activities']::text[], NULL, NULL, NULL, NULL, NULL, 'Full-summer day camp at The Elemen-Tree House in Franklin, MA, with weekly themes, field trips, group games, free swim with a certified lifeguard on duty, and arts and crafts. Weekly sessions from the last day of school; full and part time campers welcome. Summer hours 7:00 am to 6:00 pm.', NULL, NULL, 87, 349, 349, 'week', NULL, NULL, NULL, NULL, NULL, NULL, 'Free swim is offered. A certified lifeguard is on duty at all times.', NULL, NULL, 2026, 'bb2ce388-9fe4-5e9b-b89f-ffc84901e54b', 'camp-lmntree-franklin', ST_GeogFromText('SRID=4326;POINT(-71.3967 42.0834)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://www.elementreehouse.com/camp-schedule','https://www.elementreehouse.com/contact-and-tuition','https://www.elementreehouse.com/summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Children''s Summer Ballet Camp', 'Brae Crest School of Ballet', 'https://braecrestschool.com/summer/childrens-summer-camp', 'https://braecrestschool.com/contact', 'braecrest@stateballet.com', '(401) 334-2560', '52 Sherman Ave.', 'Lincoln', 'RI', '02865', 'Providence, RI', 'specialty', ARRAY['performing_arts','arts']::text[], NULL, ARRAY['Classical ballet','Character dancing','Stage make-up','Choreography','Sewing and costume design','Injury prevention','Nutrition','Art class','French class','Pilates','Theater class']::text[], NULL, 5, 12, NULL, NULL, 'Two 5-day ballet camps for children ages 5 to 12 who have at least one year of ballet training. Each week has a theme and covers ballet plus character dance, stage make-up, choreography, costume design, art, French, Pilates and theater.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, 'ba39e44f-baaa-5b77-9e22-fc36d38aeba2', 'children-s-summer-ballet-camp', ST_GeogFromText('SRID=4326;POINT(-71.4351 41.9212)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://braecrestschool.com/contact','https://braecrestschool.com/summer/childrens-summer-camp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer All Day Program', 'City of Attleboro Recreation Department', 'https://www.cityofattleboro.us/266/Summer-All-Day-Program', 'https://www.cityofattleboro.us/DocumentCenter/View/1263/2026-All-Day-Program-Application-Form-PDF', 'CClausen@cityofattleboro.us', '774-203-1889', '81 Pine Street', 'Attleboro', 'MA', '02703', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, ARRAY['Arts and crafts','Computer lab','Daily open swim','Swim lessons','Briggs Playground visits','Indoor sports and exercise','Field trips (bowling, zoo, laser tag, carnival)']::text[], NULL, NULL, 12, 1, NULL, 'A full-day summer program run by the Attleboro Recreation Department at the Bartek Recreation Center, 8:00am-5:00pm on weekdays. Activities include arts and crafts, a computer lab, daily swimming at Briggs Pool, indoor sports and up to 4 field trips.', NULL, NULL, 170, 200, 200, 'week', NULL, NULL, FALSE, NULL, 'Cancel in writing at least 14 days before the scheduled start for a refund minus the non-refundable deposit (the deposit equals the last week''s payment). No refund for cancellations less than 14 days before, no-shows or missed days unless there is a documented medical emergency. Full refund for a week the department cancels.', 'Families who need ADA accommodations or program changes must submit an ADA Program Accommodation Request Form in time. A late form may delay or prevent participation.', 'Daily open swim and swim lessons at the Briggs Pool. Children must bring a bathing suit and towel.', NULL, NULL, 2026, '6f7ed062-21c2-586d-a649-5e349388b701', 'summer-all-day-program-attleboro', ST_GeogFromText('SRID=4326;POINT(-71.2856 41.9445)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=81+Pine+Street&city=Attleboro&state=MA&benchmark=Public_AR_Current&format=json','https://www.cityofattleboro.us/266/Summer-All-Day-Program','https://www.cityofattleboro.us/DocumentCenter/View/13679/Cancellation-Policy-PDF','https://www.cityofattleboro.us/DocumentCenter/View/13799/2026-Attleboro-Recreation-Summer-Brochure']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Art Camp', 'Art Pop Club', 'https://www.artpopclub.com/summerartcamp', 'https://www.artpopclub.com/product-page/2026-summer-camp-whole-week', 'hello@artpopclub.com', '508-567-5761', '1115 GAR Highway', 'Somerset', 'MA', '02726', 'Providence, RI', 'specialty', ARRAY['arts']::text[], NULL, ARRAY['Art']::text[], NULL, 6, 11, NULL, NULL, 'A drop-off morning art camp (9:00am-12pm) for ages 6-11 at the Art Pop studio in Somerset, MA. Campers spend three hours a day on process art projects with many materials; themed weeks such as Adventure Makers Expedition are offered, and an Open Create add-on extends the day. Campers bring a snack and lunch; nut-free studio.', 'indoor', NULL, 45, 200, 200, 'week', TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '23f2650f-150c-52f6-8375-107bbfed0e4b', 'summer-art-camp-somerset', ST_GeogFromText('SRID=4326;POINT(-71.1287 41.7695)'), FALSE, FALSE, TRUE, FALSE, TRUE, FALSE, FALSE, 'unverified', ARRAY['https://www.artpopclub.com/contact','https://www.artpopclub.com/product-page/2026-summer-camp-whole-week','https://www.artpopclub.com/product-page/summer-camp-adventure-makers-expedition','https://www.artpopclub.com/summerartcamp']::text[], '2026-11-13', '2026-11-13', TRUE),
('Summer Camp with Six Bros. Baseball', 'Six Bros. Sports LLC (hosted by Bellingham Youth Baseball)', 'https://www.bellinghamyouthbaseball.com/bellinghamyouthbaseball/CampsandClinics', 'https://sixbrossports.com/', 'SIXBROSBASEBALL@GMAIL.COM', '+1 774-291-1414', 'Harpin St. Fields', 'Bellingham', 'MA', '02019', 'Providence, RI', 'specialty', ARRAY['sports']::text[], NULL, ARRAY['Baseball']::text[], NULL, 6, 12, NULL, NULL, 'A baseball skills day camp for ages 6-12 led by Six Bros. Baseball head coach Eli Sylvia and guest coaches, hosted by Bellingham Youth Baseball at Harpin St. Fields in Bellingham, MA. Two 4-day weeks (Monday to Thursday), 9:00 AM to 2:00 PM, booked by the week.', NULL, NULL, 215, 250, 250, 'week', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '03fb9a44-4352-5077-bc68-7e95f2dc2622', 'summer-camp-with-six-bros-baseball-bellingham', ST_GeogFromText('SRID=4326;POINT(-71.4745 42.0868)'), FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://sixbrossports.com/','https://www.bellinghamyouthbaseball.com/bellinghamyouthbaseball/CampsandClinics','https://www.census.gov/geographies/reference-files/time-series/geo/relationship-files.2020.html']::text[], '2026-11-13', '2026-11-13', TRUE),
('Teamworks Summer Camp – Seekonk', 'Teamworks/Indoor Sports LLC', 'https://www.teamworksseekonk.com/summercamphome.aspx', 'https://www.teamworksseekonk.com/upcomingsummerprogram.aspx', 'info@teamworksseekonk.com', '508.336.6565', '1314 Fall River Ave', 'Seekonk', 'MA', '02771', 'Providence, RI', 'day', ARRAY['sports','arts']::text[], NULL, ARRAY['sports','playground games','arts & crafts','cards and board games','gaga ball','team-building activities','theme days','basketball','flag football','soccer','baseball','volleyball']::text[], NULL, 4, 14, NULL, NULL, 'Weekly day camp at the Teamworks indoor sports facility in Seekonk (turf fields, basketball and volleyball courts), 9am to 3:30pm with extended day until 5pm and single-day options. TW Camp (ages 4-14) mixes sports, games and arts & crafts; sport specialty weeks cover basketball, flag football, soccer, baseball and volleyball, plus half-day Learn To Play camps.', 'indoor', NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '31a85c25-0df6-5bdc-ad27-b93f3e8e6b51', 'teamworks-summer-camp-seekonk-seekonk', ST_GeogFromText('SRID=4326;POINT(-71.337 41.8084)'), TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, 'unverified', ARRAY['https://service.twcenters.com/DownloadFile/RulesPolicy?strDocumentInfoId=6cd7d721-5352-4125-b210-db7ce6906909&location=10','https://www.teamworksseekonk.com/contactdirector.aspx?strContactDirectorType=EnumContactDirectorType.enumCampProgram','https://www.teamworksseekonk.com/summercamphome.aspx']::text[], '2026-11-13', '2026-11-13', TRUE),
('Teamworks Summer Camp (Warwick)', 'Teamworks/Indoor Sports LLC', 'https://www.teamworkswarwick.com/summercamphome.aspx', 'https://www.teamworkswarwick.com/upcomingsummerprogram.aspx', 'info@teamworkswarwick.com', '401.463.5565', '170 Jefferson Blvd', 'Warwick', 'RI', '02888', 'Providence, RI', 'day', ARRAY['sports']::text[], NULL, ARRAY['Sports','Playground games','Arts & crafts','Team-building activities','Theme days','Soccer','Basketball','Flag football','Volleyball','Advanced volleyball']::text[], NULL, 4, 15, NULL, NULL, 'A weekly day camp at Teamworks indoor sports center in Warwick, RI, with a general camp for ages 4-14 (sports, games, arts & crafts) and sport-specific camps for ages 4-15. Regular hours are 9am-3:30pm, and extended day runs until 5pm.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, FALSE, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '2a163783-dd53-560f-a422-0234c1ff31ad', 'teamworks-summer-camp-warwick-warwick', ST_GeogFromText('SRID=4326;POINT(-71.4162 41.7001)'), TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'unverified', ARRAY['https://service.twcenters.com/DownloadFile/RulesPolicy?strDocumentInfoId=6cd7d721-5352-4125-b210-db7ce6906909&location=2','https://www.teamworkswarwick.com/contactdirector.aspx?strContactDirectorType=EnumContactDirectorType.enumCampProgram','https://www.teamworkswarwick.com/summercamphome.aspx']::text[], '2026-11-13', '2026-11-13', TRUE),
('West Warwick Civic Center Summer Program', 'West Warwick Civic Center (Town of West Warwick)', 'https://westwarwickri.gov/civic-center', NULL, 'Westwarwickprograms@gmail.com', '401-822-9200', '100 Factory Street', 'West Warwick', 'RI', '02893', 'Providence, RI', 'day', ARRAY['general']::text[], NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'A town-run summer day program at the Thomas A. Lamb Field House in West Warwick, June 16 - August 14, 2026, weekdays 8:00 AM to 3:00 PM. Early drop-off from 7:30 AM and late pick-up to 3:30 PM are available for an extra fee. Paid by the week, with early-bird discounts for paying in full.', NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2026, '29450042-65ae-59c4-98b0-661ce50abbca', 'west-warwick-civic-center-summer-program-west-warwick', ST_GeogFromText('SRID=4326;POINT(-71.5218 41.6968)'), TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'unverified', ARRAY['https://geocoding.geo.census.gov/geocoder/locations/address?street=100+Factory+Street+%28Thomas+A.+Lamb+Field+House%29&city=West+Warwick&state=RI&benchmark=Public_AR_Current&format=json','https://westwarwickri.gov/civic-center','https://westwarwickri.gov/index.asp?SEC=5B604F5C-E48E-468C-ADF2-33A87C0D434E&DE=BA73515B-6EFA-4AA4-9F89-5AE8468F9EAB']::text[], '2026-11-13', '2026-11-13', TRUE)
